-- Żar i Szlif | Supabase PostgreSQL | katalog sprawności Royal Rangers Polska
-- Źródło danych: katalog sprawności RR (wersja 15.1.0, ten sam zestaw pól co
-- publiczny endpoint /api/sprawnosci). Tabela jest jedynym źródłem prawdy (Supabase = SoT),
-- więc katalog żyje tutaj, a nie w workerze.
-- Kontrakt pól jest 1:1 z odpowiedzią API: id, poziom, aspekt, grupa, grupa_label, tytul, wymagania.
-- Migracja jest idempotentna: można ją odtworzyć, a seed nadpisuje istniejące wpisy.
begin;

create table if not exists public.sprawnosci (
  id text primary key,
  poziom text not null check (poziom in ('odkrywcy', 'zwiadowcy', 'wedrownicy')),
  aspekt text not null check (aspekt in ('fizyczny', 'intelektualny', 'duchowy', 'spoleczny')),
  grupa text not null,
  grupa_label text not null,
  tytul text not null,
  wymagania text[] not null check (cardinality(wymagania) >= 1),
  constraint sprawnosci_poziom_grupa_tytul_key unique (poziom, grupa, tytul)
);

create index if not exists sprawnosci_poziom_aspekt_idx on public.sprawnosci (poziom, aspekt);
create index if not exists sprawnosci_grupa_idx on public.sprawnosci (grupa);

-- Katalog jest treścią publiczną (dotychczas serwowany bez autoryzacji), więc tylko odczyt
-- dla anon/authenticated. Zapis wyłącznie przez migracje i service_role.
alter table public.sprawnosci enable row level security;
revoke all on public.sprawnosci from anon, authenticated;
grant select on public.sprawnosci to anon, authenticated;

drop policy if exists "sprawnosci_select_public" on public.sprawnosci;
create policy "sprawnosci_select_public" on public.sprawnosci for select using (true);

on conflict (id) do update
set poziom = excluded.poziom,
    aspekt = excluded.aspekt,
    grupa = excluded.grupa,
    grupa_label = excluded.grupa_label,
    tytul = excluded.tytul,
    wymagania = excluded.wymagania;

commit;
