insert into public.sprawnosci (id, poziom, aspekt, grupa, grupa_label, tytul, wymagania)
values
  (E'odkrywcy-alarm-jezyk-indian', E'odkrywcy', E'fizyczny', E'alarm', E'Alarm', E'Język Indian', ARRAY[E'Znalazł książkę/strony www na temat języka migowego Indian i zapoznał się z nimi.', E'Opracował z zastępem słownik 30 migów indiańskich.', E'Posługuje się migami indiańskimi w zastępie.', E'Wymyślił pięć migów i wprowadził je w zastępie.']::text[]),
  (E'odkrywcy-alarm-lacznik', E'odkrywcy', E'fizyczny', E'alarm', E'Alarm', E'Łącznik', ARRAY[E'Przekazał ustny meldunek lub list do adresata poprawnie i w wyznaczonym terminie. Samodzielnie nadał na poczcie list polecony i paczkę.', E'Odebrał i wysłał wiadomość pocztą elektroniczną.', E'Samodzielnie odebrał wiadomość od lidera i przekazał ją wszystkim osobom z zastępu.', E'Pełnił służbę łącznika w czasie gry terenowej, zwiadu, wycieczki lub innej imprezy.']::text[]),
  (E'odkrywcy-alarm-melduj', E'odkrywcy', E'fizyczny', E'alarm', E'Alarm', E'Melduj', ARRAY[E'Wie, co to jest „łańcuch alarmowy" zastępu. Stawił się na alarm mundurowy w wyznaczonym czasie.', E'Posiada pełne umundurowanie, potrafi o nie zadbać. Zna symbolikę elementów munduru, rozróżnia stopnie i funkcje.', E'Zna musztrę pojedynczego skauta, potrafi się zameldować. Poprowadził musztrę zastępu.', E'Potrafi zaśpiewać piosenkę marszową.']::text[]),
  (E'odkrywcy-biblia-autorzy', E'odkrywcy', E'duchowy', E'biblia', E'Biblia', E'Autorzy', ARRAY[E'Przeczytał Łuk. 1:1-4. Porozmawiał z Rodzicami o tym, co opisywał w Ewangelii Łukasz.', E'Zna czterech autorów Ewangelii. Dowiedział się, kim byli i w jakich okolicznościach napisali swoje księgi.', E'Potrafi wymienić wszystkich autorów ksiąg biblijnych Starego i Nowego Testamentu.', E'Przeczytał książkę lub obejrzał film o którymś z autorów ksiąg biblijnych. O filmie porozmawiał na zbiórce.']::text[]),
  (E'odkrywcy-biblia-przyjaciel-dinozaurow', E'odkrywcy', E'duchowy', E'biblia', E'Biblia', E'Przyjaciel Dinozaurów', ARRAY[E'Przeczytał I Mojż. 1-2. Porozmawiał z Rodzicami na temat stworzenia świata.', E'Przeczytał co najmniej jedną książkę o tematyce kreacjonistycznej. Wyjaśnił na zbiórce, co to znaczy, że Bóg stworzył świat swoim Słowem i że stworzył świat z niczego.', E'Wskazał w Biblii przynajmniej jedno miejsce, w którym jest mowa o dinozaurach.', E'Przedstawił na zbiórce prezentację ciekawostki przyrodniczej, która potwierdza wiarę w stworzenie.']::text[]),
  (E'odkrywcy-biblia-wersety', E'odkrywcy', E'duchowy', E'biblia', E'Biblia', E'Wersety', ARRAY[E'Nauczył się na pamięć wersetu Jan 3:16 i porozmawiał z Rodzicami na jego temat.', E'Przeczytał z Rodzicami Przyp. 16 (codziennie czytając jeden werset i omawiając go).', E'Razem z zastępem wybrał przewodni werset biblijny dla swojego zastępu.', E'Porozmawiał z Rodzicami na temat wersetu przewodniego dla ich rodziny. Zrobił antyramę/obraz z tym wersetem i pokazał go na zbiórce. Wytłumaczył, dlaczego akurat ten werset jest przewodni dla jego rodziny.']::text[]),
  (E'odkrywcy-biblia-wielka-ksiega', E'odkrywcy', E'duchowy', E'biblia', E'Biblia', E'Wielka Księga', ARRAY[E'Przeczytał wspólnie z Rodzicami II Tym. 3:16-17 i porozmawiał o tym, czym Biblia jest dla osób wierzących.', E'Wziął udział w zajęciach o Biblii lub obejrzał program/film o Biblii.', E'Wysłuchał świadectwa osoby, dla której Biblia jest najwyższym autorytetem we wszystkich kwestiach, które porusza.', E'Wyjaśnił swojemu zastępowi, dlaczego wierzy, że Biblia jest Słowem przekazanym od Boga dla ludzi.']::text[]),
  (E'odkrywcy-czytelnictwo-bajki-i-basnie', E'odkrywcy', E'intelektualny', E'czytelnictwo', E'Czytelnictwo', E'Bajki i Baśnie', ARRAY[E'Przeczytał baśnie i bajki min. 10 autorów.', E'Przeczytał młodszej osobie kilka bajek.', E'Był w teatrze lalek na przedstawieniu bajki lub baśni.', E'Ma swojego ulubionego autora. Opowiedział komuś swoją ulubioną bajkę.']::text[]),
  (E'odkrywcy-czytelnictwo-ewangelie', E'odkrywcy', E'intelektualny', E'czytelnictwo', E'Czytelnictwo', E'Ewangelie', ARRAY[E'Przeczytał wszystkie Ewangelie.', E'Potrafi opowiedzieć o pięciu cudach, które uczynił Pan Jezus.', E'Potrafi wymienić wszystkich dwunastu apostołów i powiedzieć, kim byli, zanim zostali uczniami Jezusa.', E'Opowiedział na zbiórce jedną z przypowieści Pana Jezusa i wytłumaczył, co znaczyła.']::text[]),
  (E'odkrywcy-czytelnictwo-moj-bohater', E'odkrywcy', E'intelektualny', E'czytelnictwo', E'Czytelnictwo', E'Mój Bohater', ARRAY[E'Ma swojego ulubionego bohatera książkowego.', E'Wyszukał i przeczytał min. trzy książki ze swoim bohaterem książkowym.', E'Obejrzał film nakręcony na podstawie ulubionej książki.', E'Przyniósł na zbiórkę książkę o swoim bohaterze, opowiedział o nim i zachęcił do czytania osoby z zastępu.']::text[]),
  (E'odkrywcy-czytelnictwo-umiem-czytac', E'odkrywcy', E'intelektualny', E'czytelnictwo', E'Czytelnictwo', E'Umiem Czytać', ARRAY[E'Samodzielnie przeczytał książkę mającą 50 stron tekstu.', E'Wypożyczył i przeczytał książkę z biblioteki szkolnej.', E'Porozmawiał z Rodzicami o higienie czytania, zapobieganiu uszkodzenia wzroku. Wnioskami podzielił się na zbiórce zastępu.', E'Przeczytał na głos domownikom najciekawszy fragment poznanej ostatnio książki.']::text[]),
  (E'odkrywcy-harce-gracz', E'odkrywcy', E'spoleczny', E'harce', E'Harce', E'Gracz', ARRAY[E'Wyszukał, np. w Internecie, jedną grę niekonwencjonalną.', E'Dowiedział się, czym są gry niekonwencjonalne. Opowiedział o tym na zbiórce.', E'Wymyślił własną grę niekonwencjonalną.', E'Wykonał rekwizyty do gry, zaprezentował ją w zastępie, zaprosił do wspólnej gry/zabawy/ rywalizacji.']::text[]),
  (E'odkrywcy-harce-hopsasa', E'odkrywcy', E'spoleczny', E'harce', E'Harce', E'Hopsasa', ARRAY[E'Wyszukał, np. w Internecie, jedną grę mającą na celu integrację.', E'Dowiedział się, co to jest integracja i dlaczego jest istotna w życiu skauta. Opowiedział o tym na zbiórce.', E'Dobrze poznał zasady i nauczył się gry integracyjnej, chętnie uczestniczy w podobnych zabawach.', E'Przygotował i nauczył gry zastęp lub inne osoby, zaprosił do wspólnej gry/zabawy/ rywalizacji.']::text[]),
  (E'odkrywcy-harce-plasy', E'odkrywcy', E'spoleczny', E'harce', E'Harce', E'Pląsy', ARRAY[E'Wyszukał, np. w Internecie, jeden nowy pląs.', E'Dowiedział się, czym są pląsy i jakie mają znaczenie dla obrzędowości zastępu. Opowiedział o tym na zbiórce.', E'Nauczył się śpiewać i wykonywać poznany pląs. Przeprowadził go na zbiórce.', E'Nauczył zastęp lub inne osoby poznanego pląsu, chętnie uczestniczy w zabawach z pląsami, aktywizuje grupę w tym obszarze.']::text[]),
  (E'odkrywcy-harce-podchody', E'odkrywcy', E'spoleczny', E'harce', E'Harce', E'Podchody', ARRAY[E'Poznał zasady dowolnej gry terenowej, np. podchodów.', E'Zapoznał się z pojęciem „znaki patrolowe", nauczył się wybranych dwudziestu znaków patrolowych.', E'Wymyślił grę z wykorzystaniem znaków patrolowych, możliwą do zrealizowania w najbliższym otoczeniu.', E'Wykonał tablice dydaktyczne ze znakami patrolowymi lub zorganizował grę (przy pomocy osoby dorosłej) w najbliższym otoczeniu dla rodziny, przyjaciół lub zastępu. Zdał sprawozdanie.']::text[]),
  (E'odkrywcy-historia-bi-pi', E'odkrywcy', E'intelektualny', E'historia', E'Historia', E'Bi-Pi', ARRAY[E'Wie, skąd się wzięła i co oznacza tradycja węzełka na chuście. Przez miesiąc działał zgodnie z tą tradycją.', E'Wziął udział w quizie na temat Bi-Pi i skautingu.', E'Poznał życiorys gen. Roberta Baden-Powella.', E'W czasie zbiórki opowiedział w ciekawy sposób jedną z historii Bi-Pi.']::text[]),
  (E'odkrywcy-historia-moj-region', E'odkrywcy', E'intelektualny', E'historia', E'Historia', E'Mój Region', ARRAY[E'Był na wycieczce z zastępem lub z Rodzicami w historycznym miejscu w swoim mieście/ najbliższej okolicy.', E'Zna pięć zabytków najbliższej okolicy. Dowiedział się o nich podstawowych informacji.', E'Potrafi wymienić kilka potraw regionalnych ze swojego regionu oraz wie, jak się je przygotowuje.', E'Opowiedział swojemu zastępowi, z czego słynie jego miejscowość/region.']::text[]),
  (E'odkrywcy-historia-najblizsi', E'odkrywcy', E'intelektualny', E'historia', E'Historia', E'Najbliżsi', ARRAY[E'Odwiedził krewnych, żeby dowiedzieć się czegoś o historii rodziny, np. odwiedził babcię i wysłuchał jej historii z czasu, gdy była w jego wieku.', E'Zrobił minialbum ciekawych zdjęć, na których byli wszyscy bliscy członkowie rodzin Rodziców. Opisał zdjęcia w tym albumie.', E'Opisał najciekawszą historię z życia najstarszej osoby w rodzinie.', E'Opowiedział zastępowi dawne historie rodzinne, które usłyszał od krewnych.']::text[]),
  (E'odkrywcy-historia-rycerz', E'odkrywcy', E'intelektualny', E'historia', E'Historia', E'Rycerz', ARRAY[E'Potrafi opowiedzieć, kim byli rycerze i jaki był kodeks rycerski.', E'Wziął udział w zajęciach z odtwórstwa historycznego z okresu średniowiecza.', E'Poznał historię Zawiszy Czarnego. Potrafi wymienić jeszcze min. pięciu innych znanych polskich rycerzy.', E'Przeczytał książkę historyczną z okresu średniowiecza i opowiedział o jej bohaterze na zbiórce.']::text[]),
  (E'odkrywcy-logika-bystrzak', E'odkrywcy', E'intelektualny', E'logika', E'Logika', E'Bystrzak', ARRAY[E'Zna zasady rozwiązywania sudoku.', E'Przedstawił 10 zagadek logicznych na zbiórkach i pomógł kolegom je rozwiązać.', E'Rozwiązał samodzielnie 20 łamigłówek sudoku.', E'Nauczył kolegów w zastępie rozwiązywać sudoku.']::text[]),
  (E'odkrywcy-logika-dlaczego', E'odkrywcy', E'intelektualny', E'logika', E'Logika', E'Dlaczego', ARRAY[E'Porozmawiał z Rodzicami na trudny temat, np. Skąd się biorą dzieci? Dlaczego w domu nie wolno robić…? Dlaczego jednym wolno, a innym nie?', E'Rozmawiając z jakąś osobą podał pięć argumentów na poparcie swojego twierdzenia.', E'Poprowadził rokowania na zbiórce, dotyczące wyboru zastępowego lub przed podjęciem innej ważnej decyzji w zastępie.', E'Na zbiórce poprowadził w zastępie dyskusję na temat: „Jakie zasady powinny panować w zastępie i dlaczego?”']::text[]),
  (E'odkrywcy-logika-kombinator', E'odkrywcy', E'intelektualny', E'logika', E'Logika', E'Kombinator', ARRAY[E'Zna zasady gry i potrafi grać w co najmniej pięć gier planszowych (strategicznych bądź ekonomicznych, np. Pędzące Żółwie, Rummicub, Monopoly, Wsiąść do pociągu itp.).', E'Wziął grę na biwak/obóz i zachęcił zastęp do gry w wolnym czasie.', E'Zrobił z Rodzicami inwentaryzację gier w domu i zaproponował wspólne granie.', E'Nauczył swój zastęp grać w swoją ulubioną grę planszową.']::text[]),
  (E'odkrywcy-logika-pionek', E'odkrywcy', E'intelektualny', E'logika', E'Logika', E'Pionek', ARRAY[E'Wykazał się znajomością zasad gry w warcaby. Poznał i opowiedział na zbiórce historię powstania gry.', E'Ćwiczył z Rodzicami lub rodzeństwem grę w warcaby przez miesiąc, w sumie 10 godzin (około 2 h tygodniowo).', E'Zachęcił do gry w warcaby kolegów w zastępie, wytłumaczył zasady gry i pokazał, jak grać w warcaby.', E'Pomógł w organizacji turnieju warcabowego w zastępie/drużynie.']::text[]),
  (E'odkrywcy-misja-bog-zyje', E'odkrywcy', E'duchowy', E'misja', E'Misja', E'Bóg Żyje', ARRAY[E'Nauczył się na pamięć wersetu Gal. 2:20. Porozmawiał z Rodzicem/liderem, w jaki sposób Chrystus może mieszkać w nas.', E'Przeczytał fragment z Mar. 16:1-14. Opowiedział na zbiórce, dlaczego tak trudno było uwierzyć uczniom Jezusa, że zmartwychwstał.', E'Przeczytał historię śmierci i zmartwychwstania Jezusa. Policzył, jak wielu było świadków jego śmierci i kto widział Jezusa po zmartwychwstaniu. Wnioskami podzielił się na zbiórce.', E'Opowiedział na zbiórce, w jaki sposób Bóg może mieszkać w tych, którzy są jego dziećmi.']::text[]),
  (E'odkrywcy-misja-dobra-nowina', E'odkrywcy', E'duchowy', E'misja', E'Misja', E'Dobra Nowina', ARRAY[E'Nauczył się wersetu Dz. 5:42 na pamięć i porozmawiał z liderem/Rodzicem, dlaczego chrześcijanie wciąż powinni zwiastować Dobrą Nowinę.', E'Podzielił się Dobrą Nowiną z jedną osobą spoza swojej rodziny.', E'Wyjaśnił Ewangelię – Dobrą Nowinę – swojemu liderowi lub Rodzicowi.', E'Przygotował z zastępem zbiórkę świąteczną, na której przedstawiono w ciekawy sposób Dobrą Nowinę.']::text[]),
  (E'odkrywcy-misja-milosc', E'odkrywcy', E'duchowy', E'misja', E'Misja', E'Miłość', ARRAY[E'Nauczył się na pamięć wersetu I Kor. 13:13. Porozmawiał z Rodzicem lub liderem o tym, dlaczego miłość jest najważniejsza.', E'Przeczytał z liderem/Rodzicem fragment z I Kor. 13:1-13. Czytając słowo „miłość", zastąpił je swoim imieniem i porozmawiał o tym, nad czym w świetle tego słowa powinien pracować w swoim życiu.', E'Wymyślił i wykonał zadania, w których w praktyczny sposób okazał miłość dwóm osobom z rodziny i przyjacielowi.', E'Opowiedział na zbiórce, jak praktyczne okazanie komuś miłości wpłynęło na niego.']::text[]),
  (E'odkrywcy-misja-moj-zbawiciel', E'odkrywcy', E'duchowy', E'misja', E'Misja', E'Mój Zbawiciel', ARRAY[E'Nauczył się na pamięć wersetów Rzym. 10:8-9. Porozmawiał o tym fragmencie z Rodzicem lub liderem i w modlitwie wyznał, że Jezus jest jego Panem.', E'Przeczytał fragment z Jan 20:26-29. Wyjaśnił na zbiórce, dlaczego można wierzyć w coś, chociaż się tego nie widzi.', E'Opowiedział jednej osobie spoza rodziny, kim jest dla niego Jezus Chrystus.', E'Złożył świadectwo swojego nawrócenia na zbiórce, biwaku.']::text[]),
  (E'odkrywcy-pasje-i-talenty-grajek', E'odkrywcy', E'spoleczny', E'pasje-i-talenty', E'Pasje i talenty', E'Grajek', ARRAY[E'Nauczył zastęp piosenki.', E'Wysłuchał koncertu muzycznego.', E'Uczy się grać na instrumencie lub wykonał prosty instrument muzyczny.', E'Zrealizował minikoncert dla dowolnej grupy, na zbiórce zdał sprawozdanie, zachęcił inne osoby z zastępu do rozwijania swoich talentów.']::text[]),
  (E'odkrywcy-pasje-i-talenty-hobbysta', E'odkrywcy', E'spoleczny', E'pasje-i-talenty', E'Pasje i talenty', E'Hobbysta', ARRAY[E'Przygotował na zbiórkę minipokaz swojego hobby.', E'Poznał słownictwo związane z hobby - kolekcjoner, hobbysta, pasja, talent - poznał „przypowieść o talentach”.', E'W sposób uporządkowany poszerza swoją kolekcję.', E'Opowiedział o swoim hobby na zbiórce, zachęcił inne osoby z zastępu do rozwijania swoich talentów.']::text[]),
  (E'odkrywcy-pasje-i-talenty-lalkarz', E'odkrywcy', E'spoleczny', E'pasje-i-talenty', E'Pasje i talenty', E'Lalkarz', ARRAY[E'Wykonał pacynkę, kukiełkę, marionetkę itp.', E'Dowiedział się, jakie typy lalek są wykorzystywane w teatrze na całym świecie.', E'Zachęcił drugą osobę do wykonania lalki.', E'Zaprezentował na zbiórce (lub przedstawił w innym miejscu i zdał relację z wydarzenia) miniteatrzyku – wiersza, historyjki biblijnej itp.']::text[]),
  (E'odkrywcy-pasje-i-talenty-plastus', E'odkrywcy', E'spoleczny', E'pasje-i-talenty', E'Pasje i talenty', E'Plastuś', ARRAY[E'Wykonał samodzielnie dowolną pracę plastyczną na wybrany przez siebie temat (np. malarstwo, grafika, kolaż, rysunek pastelami, rzeźbę, fotografię).', E'Dowiedział się, co to są sztuki plastyczne.', E'Wybrał się do galerii, Muzeum Narodowego lub na dowolny wernisaż prac plastycznych.', E'Zaprezentował swą pracę plastyczną i krótko zachęcił inne osoby z zastępu do rozwijania swoich talentów.']::text[]),
  (E'odkrywcy-pasje-i-talenty-przyjaciel-roslin', E'odkrywcy', E'spoleczny', E'pasje-i-talenty', E'Pasje i talenty', E'Przyjaciel Roślin', ARRAY[E'Wyhodował roślinkę od sadzonki/nasionka do młodej roślinki.', E'Dowiedział się, jakich warunków do rozwoju wymaga jego roślinka, gdzie rośnie w warunkach naturalnych.', E'Wykonał tabliczkę do oznaczania roślin - umieścił na niej dane swojej hodowli.', E'Zaprezentował swoją hodowlę, opisał przebieg rozwoju rośliny, zachęcił inne osoby z zastępu do rozwijania swoich talentów.']::text[]),
  (E'odkrywcy-pasje-i-talenty-w-rytmie', E'odkrywcy', E'spoleczny', E'pasje-i-talenty', E'Pasje i talenty', E'W Rytmie', ARRAY[E'Wraz z innymi wystąpił z układem choreograficznym na dowolnej uroczystości.', E'Przeczytał w Biblii opis tańca Miriam - rozumie, że taniec może być formą uwielbienia.', E'Uczestniczy w zajęciach z rytmiki lub w zajęciach o podobnym charakterze.', E'Zrelacjonował swój występ na zbiórce, zachęcił inne osoby z zastępu do rozwijania swoich talentów.']::text[]),
  (E'odkrywcy-pasje-i-talenty-zrob-to-sam', E'odkrywcy', E'spoleczny', E'pasje-i-talenty', E'Pasje i talenty', E'Zrób To Sam', ARRAY[E'Wykonał samodzielnie dowolną rękodzielniczą pracę (np. haft, rzeźba w mydle, modelarstwo).', E'Do wykonania owego rękodzieła poszukał i zapoznał się z materiałami dydaktycznymi (np. obejrzał film instruktażowy na Youtube, uczestniczył w kursie, przeczytał w literaturze fachowej).', E'Nauczył min. jedną osobę nowo poznanej techniki, w której wykonał swe rękodzieło.', E'Zaprezentował swe rękodzieło i krótko zachęcił inne osoby z zastępu do prac twórczych (po co, dlaczego, korzyści).']::text[]),
  (E'odkrywcy-pionierka-drewno', E'odkrywcy', E'fizyczny', E'pionierka', E'Pionierka', E'Drewno', ARRAY[E'Potrafi rozpalić ognisko jedną zapałką korzystając z wcześniej przygotowanej samodzielnie rozpałki wstępnej.', E'Poznał różne rodzaje stosów ogniskowych, nauczył się je układać.', E'Poznał zasady przechowywania zapałek. Zabezpieczył zapałki i zrobił własne paliwko do rozpalania.', E'Razem z zastępem przygotował drewno na cały biwak - zadbali o jego dobrą jakość.']::text[]),
  (E'odkrywcy-pionierka-kuchcik', E'odkrywcy', E'fizyczny', E'pionierka', E'Pionierka', E'Kuchcik', ARRAY[E'Przygotował posiłek swojej rodzinie i jakiś prosty swojemu zastępowi.', E'Zrobił całodniowe menu i uzyskał zatwierdzenie od przybocznego lub Rodziców. Menu powinno być zaplanowane zgodnie z zasadami zdrowego odżywiania.', E'Przez miesiąc robił sobie śniadanie do szkoły.', E'Posprzątał po posiłku, wyczyścił kociołek lub menażkę z sadzy.']::text[]),
  (E'odkrywcy-pionierka-liny', E'odkrywcy', E'fizyczny', E'pionierka', E'Pionierka', E'Liny', ARRAY[E'Nauczył się wykonywać trzy węzły: ósemkę, wyblinkę i płaski (prosty).', E'Umie klarować liny. Potrafi zakończyć linę naturalną i sztuczną.', E'Wie, jak dbać o liny, jak rozpoznać ich uszkodzenie i jak je naprawić.', E'Zna 3 sposoby zastosowania lin w życiu codziennym i w przemyśle. Opowiedział i zademonstrował to na zbiórce zastępu.']::text[]),
  (E'odkrywcy-pionierka-technik-obozowy', E'odkrywcy', E'fizyczny', E'pionierka', E'Pionierka', E'Technik Obozowy', ARRAY[E'Był przynajmniej na jednym obozie, nocując pod namiotem.', E'Rozłożył i złożył w zespole 2-3-osobowym dwa różne namioty. Zna zasady składania, konserwowania i przechowywania namiotów. Naprawił proste uszkodzenie namiotu.', E'Ma własną finkę, scyzoryk. Potrafi się posługiwać piłą, nożem, siekierą. Zrobił własną laskę skautową i ją ozdobił.', E'Wykonał w zespole 2-3-osobowym jedno urządzenie obozowe (np. półka, prycza, trójnóg, stojak na plecak) i jeden element budownictwa obozowego (brama, tablica ogłoszeniowa, oznakowanie terenu obozu itp.).']::text[]),
  (E'odkrywcy-poboznosc-dawanie', E'odkrywcy', E'duchowy', E'poboznosc', E'Pobożność', E'Dawanie', ARRAY[E'Przeczytał fragment Dz. 20:25 i porozmawiał z Rodzicami na temat dawania.', E'Przez trzy dni wieczorem modlił się i zastanawiał, kim jest w świetle tego wersetu - dawcą czy biorcą? Porozmawiał z Rodzicami, w jaki sposób mógłby być lepszym dawcą.', E'Ustalił, czym mógłby dzielić się z innymi. Przez miesiąc raz na tydzień dawał coś komuś, nie oczekując zapłaty ani wdzięczności.', E'Wspólnie z Rodzicami ustalił kwotę, jaką chciałby uzbierać i dać komuś jako dar. Cel zrealizował.']::text[]),
  (E'odkrywcy-poboznosc-moj-kosciol', E'odkrywcy', E'duchowy', E'poboznosc', E'Pobożność', E'Mój Kościół', ARRAY[E'Przeczytał fragment Hebr. 10:24-25 i porozmawiał z Rodzicami na temat ważności chodzenia do kościoła.', E'Przez 10 tygodni systematycznie chodził do swojego kościoła na główne nabożeństwa w tygodniu.', E'Porozmawiał z Rodzicami na temat swojego kościoła i denominacji, jakiej są członkami. Dowiedział się, czym charakteryzuje się ich denominacja.', E'Opowiedział na zbiórce zastępu, do jakiego chodzi kościoła i jak wyglądają w nim nabożeństwa niedzielne.']::text[]),
  (E'odkrywcy-poboznosc-oddzielony', E'odkrywcy', E'duchowy', E'poboznosc', E'Pobożność', E'Oddzielony', ARRAY[E'Przeczytał z Rodzicami historię proroka Samuela (I Sam. 3) i porozmawiał z liderem/ Rodzicami, czy dzisiaj również Bóg może do nas mówić.', E'Przez miesiąc poświęcił ustalony z Rodzicami czas na modlitwę rano i wieczorem.', E'Przez trzy tygodnie codziennie samodzielnie czytał i rozważał werset/fragment z Biblii. Wybór fragmentów/wersetów ustalił z liderem/Rodzicem.', E'Wnioskami z wybranego rozważania biblijnego podzielił się na zbiórce.']::text[]),
  (E'odkrywcy-poboznosc-religia', E'odkrywcy', E'duchowy', E'poboznosc', E'Pobożność', E'Religia', ARRAY[E'Przeczytał z Rodzicami fragment Łuk. 2:39-52. Porozmawiał z Rodzicami, jak może rozwijać się duchowo.', E'Przez min. 10 tygodni brał systematycznie czynny udział w lekcjach religii/zajęciach szkoły niedzielnej.', E'Porozmawiał z liderem/Rodzicami na temat duchowego rozwoju. Dowiedział się, co mógłby robić, aby duchowo się rozwijać.', E'Zrealizował tygodniowy plan duchowego samorozwoju i opowiedział o tym na zbiórce.']::text[]),
  (E'odkrywcy-poznawanie-swiata-chrzescijanstwo', E'odkrywcy', E'intelektualny', E'poznawanie-swiata', E'Poznawanie świata', E'Chrześcijaństwo', ARRAY[E'Wie, co jest istotą chrześcijaństwa i skąd się wzięła nazwa.', E'Zna na pamięć nicejsko-konstantynopolitańskie wyznanie wiary.', E'Potrafi wytłumaczyć swoimi słowami istotę Trójcy Świętej i podwójną naturę Jezusa Chrystusa.', E'Zna podstawowe informacje na temat swojego wyznania. Potrafi o nim opowiedzieć.']::text[]),
  (E'odkrywcy-poznawanie-swiata-dziennikarz', E'odkrywcy', E'intelektualny', E'poznawanie-swiata', E'Poznawanie świata', E'Dziennikarz', ARRAY[E'Wziął udział w redagowaniu pisma/gazetki skautowej lub szkolnej.', E'Poznał cechy, jakimi powinni charakteryzować się dziennikarze oraz zasady, jakie obowiązują w ich zawodzie. Opowiedział o tym na zbiórce.', E'Zebrał materiał i napisał ciekawy artykuł o tematyce szczepowej lub skautowej.', E'Przeprowadził wywiad lub sondę na określony temat. Wyniki przedstawił na zbiórce.']::text[]),
  (E'odkrywcy-poznawanie-swiata-inne-kraje', E'odkrywcy', E'intelektualny', E'poznawanie-swiata', E'Poznawanie świata', E'Inne Kraje', ARRAY[E'Był na wycieczce w innym kraju. Opowiedział o tym na zbiórce, pokazał zdjęcia i pamiątki.', E'Przygotował trasę wycieczki zagranicznej do miasta w innym kraju. Spisał miejsca warte zobaczenia w tym mieście. Na zbiórce ciekawie opowiedział o tych miejscach.', E'Rozpoznaje flagi wszystkich krajów w Europie.', E'Interesuje się wybranym krajem w Europie - poznaje jego historię, kulturę, zwyczaje itp. Zrobił o nim prezentację i pokazał na zbiórce lub w szkole.']::text[]),
  (E'odkrywcy-poznawanie-swiata-jezyk-obcy', E'odkrywcy', E'intelektualny', E'poznawanie-swiata', E'Poznawanie świata', E'Język Obcy', ARRAY[E'Uczy się języka obcego i zna min. 200 słów w obcym języku.', E'Nawiązał kontakt korespondencyjny z osobą z innego kraju. Otrzymał zwrotnie min. pięć kartek/listów. Pokazał je na zbiórce.', E'Potrafi zadać 30 pytań w obcym języku i odpowiedzieć na nie.', E'Nauczył osoby z zastępu pięciu zwrotów obcojęzycznych.']::text[]),
  (E'odkrywcy-poznawanie-swiata-przyroda', E'odkrywcy', E'intelektualny', E'poznawanie-swiata', E'Poznawanie świata', E'Przyroda', ARRAY[E'Rozpoznał po sylwetkach, igłach i liściach 15 rodzimych polskich drzew.', E'Zna min. 15 gatunków zwierząt prawnie chronionych w Polsce. Opowiedział o jednym gatunku na zbiórce.', E'Studiuje życie fauny i flory w swojej okolicy. Potrafi wymienić miejsca występowania ciekawych roślin i zwierząt. Wskazał na pomnik przyrody w najbliższej okolicy.', E'Samodzielnie lub z zastępem zasadził drzewko w pobliżu swojego domu, na działce lub przy szkole. Razem z zastępem był na wycieczce w ZOO.']::text[]),
  (E'odkrywcy-puszczanstwo-chatka-robinsona', E'odkrywcy', E'fizyczny', E'puszczanstwo', E'Puszczaństwo', E'Chatka Robinsona', ARRAY[E'Rozbił samodzielnie mały namiot, a z zastępem namiot duży.', E'Zamaskował teren biwaku i umiejętnie posprzątał swoje miejsce biwakowe.', E'Potrafi zbudować legowisko pod pałatką i namiot z dwóch pałatek.', E'Z zastępem odbył całodniową wycieczkę po lesie, z dala od ludzi, obserwując życie lasu.']::text[]),
  (E'odkrywcy-puszczanstwo-plomyk', E'odkrywcy', E'fizyczny', E'puszczanstwo', E'Puszczaństwo', E'Płomyk', ARRAY[E'Rozpalił ognisko za pomocą szkła powiększającego.', E'Dowiedział się, jak można przechowywać i przenosić ogień. Wykonał własną hubkę.', E'Poznał przepisy przeciwpożarowe na biwakach i obozach. Wie, gdzie można palić ogniska w lesie i na jakich zasadach. Potrafi bezpiecznie zagasić ognisko.', E'Potrafi rozpalić i zagasić ognisko na łące, nie pozostawiając po sobie śladów.']::text[]),
  (E'odkrywcy-puszczanstwo-sopelek', E'odkrywcy', E'fizyczny', E'puszczanstwo', E'Puszczaństwo', E'Sopelek', ARRAY[E'Był na obozie zimowym. W trakcie obozu wziął udział w zajęciach na śniegu (podchody, bieg patrolowy, olimpiada sportowa).', E'Wie, jak zabezpieczyć się przed przemarznięciem i przemoczeniem. Odpowiednio ubierał się na śnieg. Potrafi zadbać o swoje buty w zimie (konserwować i suszyć).', E'Zbudował z zastępem igloo. Zna zasady jego budowania.', E'Skompletował na wycieczkę zimową właściwy ekwipunek: ubranie, pożywienie, sprzęt. Wie, jakie elementy ekwipunku są w zimie niezbędne i dlaczego.']::text[]),
  (E'odkrywcy-puszczanstwo-zielarz', E'odkrywcy', E'fizyczny', E'puszczanstwo', E'Puszczaństwo', E'Zielarz', ARRAY[E'Wybrał się z zastępem na grzyby. Odnalazł w atlasie i nazwał rodzaje znalezionych grzybów.', E'Przygotował do apteczki domowej zestaw pięciu ziół oraz krótki opis ich stosowania.', E'Przyrządził ziołowy środek przydatny w leczeniu, kosmetyce lub w gospodarstwie domowym.', E'Brał udział w wykonywaniu przetworów. Poznał co najmniej trzy sposoby konserwowania żywności.']::text[]),
  (E'odkrywcy-rodzina-dziadkowie', E'odkrywcy', E'spoleczny', E'rodzina', E'Rodzina', E'Dziadkowie', ARRAY[E'Napisał listy do Dziadków.', E'Poznał lepiej swoich Dziadków, porozmawiał z nimi osobiście lub opowiedzieli mu Rodzice - dowiedział się, co lubią, czego nie lubią czy chorują, kim chcieli być będąc dziećmi, jakie mają marzenia.', E'Przez tydzień modlił się o Dziadków, błogosławiąc im w kontekście wiedzy, którą uzyskał w wywiadzie.', E'Opowiedział na zbiórce jakąś ciekawą historię o swoich Dziadkach.']::text[]),
  (E'odkrywcy-rodzina-kuzyni', E'odkrywcy', E'spoleczny', E'rodzina', E'Rodzina', E'Kuzyni', ARRAY[E'Stworzył „rodzinną siatkę” kuzynostwa - uwzględnił w niej informację, w jaki sposób jest spokrewniony, kiedy są urodziny kuzynostwa i gdzie mieszkają.', E'Poznał lepiej wybranego kuzyna/wybraną kuzynkę - dowiedział się, co lubi, czego nie lubi, o czym marzy, czego się obawia.', E'Przez tydzień modlił się o kuzynostwo w kontekście wiedzy, którą uzyskał przy tworzeniu „rodzinnej siatki”.', E'Opowiedział na zbiórce jakąś ciekawą historię o swoich kuzynach.']::text[]),
  (E'odkrywcy-rodzina-rodzenstwo', E'odkrywcy', E'spoleczny', E'rodzina', E'Rodzina', E'Rodzeństwo', ARRAY[E'Przygotował jakiś drobiazg dla rodzeństwa na podstawie przeprowadzonego wcześniej wywiadu z rodzeństwem.', E'Poznał lepiej swoje rodzeństwo, dowiedział się, co lubi, czego nie lubi, o czym marzy, czego się obawia.', E'Przez tydzień modlił się o rodzeństwo w kontekście wiedzy, którą uzyskał w wywiadzie, starał się unikać konfliktów.', E'Zaprezentował historię biblijnego rodzeństwa (pozytywną lub negatywną) – opowiedział, czego możemy się nauczyć na podanym przykładzie (np. Mojżesz, Miriam i Aaron, Szymon i Andrzej, Józef i Beniamin) lub powiedział inne świadectwo miłości i troski między rodzeństwem.']::text[]),
  (E'odkrywcy-rodzina-rodzice', E'odkrywcy', E'spoleczny', E'rodzina', E'Rodzina', E'Rodzice', ARRAY[E'Zastanowił się, w jakiej czynności codziennej mógłby być pomocny Rodzicom - przez miesiąc starał się sumiennie pomagać.', E'Poznał lepiej swoich Rodziców, dowiedział się, co lubią, czego nie lubią, gdzie pracują, kim chcieli być będąc dziećmi, jakie mają marzenia.', E'Przez tydzień modlił się o Rodziców, błogosławiąc im w kontekście wiedzy, którą uzyskał w wywiadzie.', E'Zaprezentował historię biblijnych rodziców – opowiedział, czego możemy się nauczyć na podanym przykładzie (np. Abraham, Jakub, Jair) lub powiedział inne świadectwo miłości i troski rodzicielskiej.']::text[]),
  (E'odkrywcy-samodyscyplina-co-widze', E'odkrywcy', E'duchowy', E'samodyscyplina', E'Samodyscyplina', E'Co Widzę', ARRAY[E'Przeczytał fragmenty: Przyp. 3:21-22 i Ps. 119:37. Porozmawiał z Rodzicami na temat tego, jak możemy dbać o to, aby oglądać naszymi oczami same dobre rzeczy.', E'Ustalił z Rodzicami zasady oglądania telewizji i korzystania z Internetu. Przestrzega tych zasad.', E'Rozmawiał z Rodzicami lub liderem, jak podejmować decyzje, czego nie powinien oglądać, jak sobie radzić w sytuacjach, gdy inni chcą oglądać rzeczy, które są złe.', E'Opowiedział na zbiórce, jak unikać oglądania filmów i programów, które nie są dobre.']::text[]),
  (E'odkrywcy-samodyscyplina-codzienny-chleb', E'odkrywcy', E'duchowy', E'samodyscyplina', E'Samodyscyplina', E'Codzienny Chleb', ARRAY[E'Przez trzy tygodnie codziennie czytał jeden rozdział z Ewangelii Jana.', E'Czytając Ewangelię Jana odnalazł i zanotował wszystkie obietnice, które dotyczą osób wierzących.', E'Codziennie czytając Biblię, z przeczytanego tekstu wybierał jeden kluczowy werset i rozmawiał o nim z Rodzicem.', E'Opowiedział na zbiórce o jednej rzeczy, która bardzo go poruszyła, kiedy czytał Biblię.']::text[]),
  (E'odkrywcy-samodyscyplina-mezny', E'odkrywcy', E'duchowy', E'samodyscyplina', E'Samodyscyplina', E'Mężny', ARRAY[E'Porozmawiał z liderem lub Rodzicem na temat swoich wad, słabości, kompleksów. Wybrał jedną, która w szczególny sposób komplikuje mu współżycie z innymi ludźmi, np. kłótliwość, zarozumiałość, nietolerancja, nieśmiałość, spóźnianie się, nierzetelność.', E'Wybrał jedną, nad którą chciałby popracować. Ustalił trzy zadania, które pomogą mu w jej zniwelowaniu.', E'W trakcie próby (miesiąc) rozmawiał z liderem/Rodzicem i złożył min. dwa sprawozdania, jak udaje mu się realizować ustalone zadania.', E'Opowiedział na zbiórce świadectwo z przebiegu próby.']::text[]),
  (E'odkrywcy-samodyscyplina-modlitwa-indywidualna', E'odkrywcy', E'duchowy', E'samodyscyplina', E'Samodyscyplina', E'Modlitwa Indywidualna', ARRAY[E'Przeczytał fragment I Tes. 5:17 i porozmawiał z Rodzicami na temat systematycznej modlitwy. Od min. trzech tygodni codziennie spędza czas na modlitwie.', E'Nauczył się Modlitwy Pańskiej na pamięć.', E'Spisał, o co powinien się modlić (za co dziękować i o co prosić) i systematycznie przez min. miesiąc modlił się w tych sprawach.', E'Opowiedział na zbiórce świadectwo swojej wysłuchanej modlitwy.']::text[]),
  (E'odkrywcy-samozaradnosc-dam-rade', E'odkrywcy', E'intelektualny', E'samozaradnosc', E'Samozaradność', E'Dam Radę', ARRAY[E'Dokonał z osobą dorosłą przeglądu narzędzi w domu lub zastępie. Poznał nazwy i zastosowanie 10 z nich (klucze do śrub, wkrętaki, kombinerki, gumowy młotek, dłutko, piła, pilnik itp.).', E'W pracach pionierskich posłużył się: piłą, toporkiem, młotkiem, nożem; potrafi je zakonserwować po zakończonej pracy.', E'Nauczył się ostrzyć nóż i siekierę - zademonstrował to na zbiórce/biwaku.', E'Z pomocą Rodzica wybrał przedmiot w domu i dokonał prostej naprawy.']::text[]),
  (E'odkrywcy-samozaradnosc-moja-pierwsza-praca', E'odkrywcy', E'intelektualny', E'samozaradnosc', E'Samozaradność', E'Moja Pierwsza Praca', ARRAY[E'Przeczytał z Rodzicami werset II Tes. 3:10 i porozmawiał o tym, na czym polega praca oraz dlaczego powinno się pracować.', E'Umówił się na wykonanie konkretnej płatnej pracy poza domem - co? za ile? kiedy? (dla sąsiadów, znajomych, dziadków) i wykonał ją na ustalonych zasadach.', E'Ustalił z Rodzicami, co będzie jego pracą, którą wniesie coś dla rodziny i systematycznie przez okres miesiąca ją wykonywał.', E'Razem z Rodzicami podsumował realizację prac i ustalił stałą pracę w domu, którą będzie wykonywał jako członek rodziny.']::text[]),
  (E'odkrywcy-samozaradnosc-oszczedny', E'odkrywcy', E'intelektualny', E'samozaradnosc', E'Samozaradność', E'Oszczędny', ARRAY[E'Przeczytał z Rodzicami werset I Tym. 6:8 i porozmawiał o tym, na czym polegają różnice pomiędzy potrzebami, życzeniami i zachciankami. Wspólnie ustalili potrzeby skauta.', E'Zaoszczędził pieniądze na ustalony wcześniej z Rodzicami cel długoterminowy (min. sześć miesięcy).', E'Ustalił w domu zasady oszczędnego gospodarowania: wodą, prądem, gazem itp. i sam je stosuje.', E'Razem z Rodzicami podsumowali realizację zasad oszczędzania i ustalili kolejny cel oszczędzania długoterminowego.']::text[]),
  (E'odkrywcy-samozaradnosc-s-o-s', E'odkrywcy', E'intelektualny', E'samozaradnosc', E'Samozaradność', E'S.O.S.', ARRAY[E'Porozmawiał z Rodzicami na temat bezpieczeństwa w domu. Wspólnie ustalili, co ma zrobić w przypadkach niebezpiecznych: pożaru, zagubienia się w mieście, zatrzaśnięcia się w domu/klasie/toalecie, zobaczenia osoby potrzebującej pomocy itp.', E'Zna telefony alarmowe oraz wie, kiedy i jak ich użyć. Zna swoje dane (imię, nazwisko, adres) oraz dane kontaktowe do Rodziców (telefony, miejsca pracy). Udowodnił to.', E'Wie, jak się zachować w przypadku zgubienia się na biwaku, wycieczce. Chodzi na biwaki lub do lasu z gwizdkiem.', E'Razem z zastępem porozmawiali na temat niebezpiecznych sytuacji na zbiórkach i ustalili, jak będą działać. Zrobili symulację niebezpiecznej sytuacji i działali zgodnie z planem.']::text[]),
  (E'odkrywcy-samozaradnosc-zdrowe-cialo', E'odkrywcy', E'intelektualny', E'samozaradnosc', E'Samozaradność', E'Zdrowe Ciało', ARRAY[E'Przez miesiąc codziennie wykonywał cztery zadania: mycie zębów, zmienianie bielizny, mycie rąk przed posiłkami i czesanie włosów.', E'Ustalił z Rodzicami zasady oglądania telewizji, korzystania z komputera i godziny snu. Przestrzega ustalonych zasad.', E'Przez okres miesiąca robi sobie śniadania do szkoły. Menu opracował z Rodzicami.', E'Wyjaśnił grupie, na czym polega zdrowe odżywianie i dlaczego jest takie ważne.']::text[]),
  (E'odkrywcy-sluzba-innym-badz-przyjacielem', E'odkrywcy', E'duchowy', E'sluzba-innym', E'Służba innym', E'Bądź Przyjacielem', ARRAY[E'Przeczytał z Rodzicami fragment Przyp. 17:17. Porozmawiał z Rodzicami, jak wygląda jego postawa względem przyjaciół. Wspólnie ustalili, co będzie robił, aby okazać przyjaźń i w jaki sposób może pomóc przyjacielowi.', E'Przez miesiąc min. raz w tygodniu miał kontakt z przyjacielem i pomagał mu. Systematycznie modlił się o niego i jego potrzeby.', E'W ciągu miesiąca dwa razy zrobił przyjacielowi jakąś miłą niespodziankę.', E'Razem z Rodzicami podsumował ten czas i ustalił, jak dalej skaut będzie rozwijał przyjaźń.']::text[]),
  (E'odkrywcy-sluzba-innym-domus', E'odkrywcy', E'duchowy', E'sluzba-innym', E'Służba innym', E'Domuś', ARRAY[E'Przeczytał z Rodzicami fragment Mat. 21:28-31. Porozmawiał z Rodzicami, jak wygląda jego postawa w pracach domowych. Wspólnie ustalili pięć głównych obowiązków - prac domowych, które skaut w jego wieku powinien sam odpowiedzialnie wykonywać.', E'Przez miesiąc codziennie wykonywał swoje ustalone obowiązki, np. ścielił łóżko, sprzątał swój pokój, układał swoje rzeczy w półkach i w szafie, karmił rybki, wynosił śmieci.', E'W ciągu miesiąca nauczył się wykonywać nową pracę i wykonywał ją min. raz w tygodniu, np. odkurzał, robił pranie, robił sobie śniadanie itp.', E'Razem z Rodzicami podsumował realizację obowiązków i ustalił przyszłe stałe obowiązki.']::text[]),
  (E'odkrywcy-sluzba-innym-plasterek', E'odkrywcy', E'duchowy', E'sluzba-innym', E'Służba innym', E'Plasterek', ARRAY[E'Przeczytał z Rodzicami fragment Mat. 8:23-26 i porozmawiał o sytuacjach niebezpiecznych, które mogą się wydarzyć. Ustalił, jak i do kogo należy zwrócić się po pomoc.', E'Przejrzał z Rodzicami domową apteczkę i dowiedział się, do czego służą jej elementy. Ustalił, jakie środki opatrunkowe powinien mieć w chlebaku na biwaku i zbiórce oraz nauczył się ich używać. Skompletował apteczkę osobistą.', E'Poznał alarmowe numery telefonów. Wie, kiedy i w jaki sposób należy z nich korzystać. Zrobił na zbiórce symulację rozmowy ze służbami ratunkowymi, w której przekazał ważne informacje dotyczące potencjalnego wypadku.', E'Podsumował z Rodzicami wykonanie zadania i wytłumaczył w zastępie, dlaczego każdy powinien znać numery alarmowe.']::text[]),
  (E'odkrywcy-sluzba-innym-pomocnik', E'odkrywcy', E'duchowy', E'sluzba-innym', E'Służba innym', E'Pomocnik', ARRAY[E'Przeczytał z Rodzicami fragment Mar. 9:33-35. Porozmawiał z Rodzicami, jak wygląda jego postawa względem osób w domu i zastępie. Czy potrafi innym usługiwać czy tylko chce być największy?', E'Ustalił z Rodzicami zadanie, które będzie robił przez następny miesiąc dwa razy w tygodniu z prac, których nikt nie lubi, np. wynoszenie śmieci, mycie toalety, zmywanie naczyń itp.', E'W zastępie podjął się zadania, którego wszyscy unikają, np. pozamiatania po zbiórce, zmycia naczyń na biwaku itp.', E'Podsumował z Rodzicami wykonanie zadania i wytłumaczył w zastępie, co to znaczy być przywódcą i jak sobie radził z niewdzięcznymi pracami.']::text[]),
  (E'odkrywcy-sluzba-w-kosciele-jestem-z-nimi', E'odkrywcy', E'duchowy', E'sluzba-w-kosciele', E'Służba w kościele', E'Jestem z Nimi', ARRAY[E'Przeczytał z Rodzicami fragment I Sam. 18:1-5 i modlił się z Rodzicami o takiego przyjaciela, jakiego miał król Dawid.', E'Zaprosił kilku kolegów/kilka koleżanek z kościoła do siebie do domu na wspólne spędzenie czasu.', E'Zaproponował i zorganizował w grupie rówieśniczej w kościele zrobienie czegoś razem.', E'Porozmawiał z Rodzicami o przyjaźni i o korzyściach, jakie płyną z bliskich relacji.']::text[]),
  (E'odkrywcy-sluzba-w-kosciele-niespodzianka', E'odkrywcy', E'duchowy', E'sluzba-w-kosciele', E'Służba w kościele', E'Niespodzianka', ARRAY[E'Przeczytał z Rodzicami werset I Tes. 5:15 i na jego podstawie porozmawiał o tym, co to znaczy czynić dobrze.', E'Zrobił miłe niespodzianki w domu każdemu członkowi rodziny (z okazji urodzin, rocznicy ślubu itp. lub bez okazji).', E'Wie, co oznacza tradycja węzełka na chuście. Przez miesiąc codziennie robił dobry uczynek poza domem.']::text[]),
  (E'odkrywcy-sluzba-w-kosciele-pierwsza-sluzba', E'odkrywcy', E'duchowy', E'sluzba-w-kosciele', E'Służba w kościele', E'Pierwsza Służba', ARRAY[E'Przeczytał z Rodzicami werset Łuk. 4:16 i na jego podstawie porozmawiał o swoim kościele i chodzeniu do niego.', E'Zapoznał się z liderami i duchownymi swojego kościoła/wspólnoty. Wie, kto pełni jaką funkcję.', E'Zapoznał się z liderem jednej ze służb w swoim kościele. Wykonał jedną pracę na rzecz kościoła.', E'Podsumował z Rodzicami wykonanie zadania i porozmawiał, co mógłby kiedyś robić w kościele.']::text[]),
  (E'odkrywcy-sluzba-w-kosciele-znam-mojego-duchownego', E'odkrywcy', E'duchowy', E'sluzba-w-kosciele', E'Służba w kościele', E'Znam Mojego Duchownego', ARRAY[E'Przeczytał werset z Dz. 13:1. Zna z widzenia i z nazwiska wszystkich duchownych ze swojego kościoła/wspólnoty.', E'Odbył rozmowę z duchownym z kościoła/wspólnoty. Wypytał, na czym polega jego służba, czym się zajmuje, jakie ma hobby. Starał się w rozmowie poznać duchownego jak najlepiej.', E'Przez określony okres czasu systematycznie modlił się o duchownego ze swego kościoła.', E'Porozmawiał z Rodzicami o zaproszeniu duchownego na kawę i ciasto do domu. W trakcie spotkania zapytał o potrzeby duchownego, o które mógłby się modlić.']::text[]),
  (E'odkrywcy-spoleczenstwo-maly-sasiad', E'odkrywcy', E'spoleczny', E'spoleczenstwo', E'Społeczeństwo', E'Mały Sąsiad', ARRAY[E'Wymyślił i zrealizował drobną akcję pomocy sąsiedzkiej (pomoc samotnej starszej osobie, posprzątanie placu zabaw itp.).', E'Na zbiórce wyjaśnił skautom pojęcia: akcja charytatywna i wolontariusz.', E'Cechuje go wrażliwość na potrzeby innych, zrobił rozpoznanie, kto w sąsiedztwie potrzebuje pomocy.', E'Brał udział w zespołowej akcji pomocy sąsiedzkiej.']::text[]),
  (E'odkrywcy-spoleczenstwo-obywatel', E'odkrywcy', E'spoleczny', E'spoleczenstwo', E'Społeczeństwo', E'Obywatel', ARRAY[E'Zna krótką historię Polski (kluczowe daty i postaci) i mapę Polski (granice, województwa, największe miasta, regiony itp.).', E'Zna hymn państwowy, wie, jak się należy zachowywać w czasie wykonywania hymnu, zna godło, stolicę państwa, flagę.', E'Wybrał z Biblii i nauczył się wersetu modlitwy o swój kraj, aktywizuje rodzinę do uczestnictwa w świętach państwowych i do modlitwy o Polskę.', E'Zrealizował wraz z zastępem zbiórkę związaną z tematyką obywatelską (miał swoje zadanie) - święto narodowe, historia Polski itp.']::text[]),
  (E'odkrywcy-spoleczenstwo-ochrona-srodowiska', E'odkrywcy', E'spoleczny', E'spoleczenstwo', E'Społeczeństwo', E'Ochrona Środowiska', ARRAY[E'Segreguje śmieci w swoim domu.', E'Uzbierał 50 zł ze sprzedaży surowców wtórnych.', E'Brał udział w akcji sprzątania lasów, parków itp.', E'Wziął udział w zbiórce, prelekcji, spotkaniu o tematyce ekologicznej.']::text[]),
  (E'odkrywcy-spoleczenstwo-pyza-wedrowniczka', E'odkrywcy', E'spoleczny', E'spoleczenstwo', E'Społeczeństwo', E'Pyza Wędrowniczka', ARRAY[E'Przygotował na zbiórkę wiadomości dotyczące swojej małej ojczyzny: gwara, reportaż z muzeum etnograficznego, lokalne potrawy itp.', E'Wie, w jakim regionie mieszka, czym on się charakteryzuje i zna stolicę regionu.', E'Wziął udział w dowolnym święcie regionalnym.', E'Na zbiórce podzielił się zdobytą wiedzą na temat regionu.']::text[]),
  (E'odkrywcy-spoleczenstwo-zawody', E'odkrywcy', E'spoleczny', E'spoleczenstwo', E'Społeczeństwo', E'Zawody', ARRAY[E'Przeprowadził wywiad z członkiem rodziny, który w jego ocenie wykonuje ciekawy zawód.', E'Wie, czym zajmują się zawodowo jego Rodzice, umie opowiedzieć o ich pracy.', E'Poszukał informacji w Internecie (lub zapytał kogoś), czym są zawody ginące.', E'Zaprezentował na zbiórce zdobyte informacje.']::text[]),
  (E'odkrywcy-sport-plywaczek', E'odkrywcy', E'fizyczny', E'sport', E'Sport', E'Pływaczek', ARRAY[E'Przepłynął 100 metrów, w tym połowę na plecach.', E'Wytrzymał pod wodą 20 sekund.', E'Poznał zasady bezpieczeństwa i higieny kąpieli i przekazał je osobom z zastępu.', E'Przez min. trzy miesiące systematycznie (raz na tydzień) chodził na basen. Był z zastępem na basenie i zademonstrował swoje umiejętności.']::text[]),
  (E'odkrywcy-sport-silne-cialo', E'odkrywcy', E'fizyczny', E'sport', E'Sport', E'Silne Ciało', ARRAY[E'Przez miesiąc wykonywał trzy ćwiczenia fizyczne cztery razy w tygodniu.', E'Poprowadził rozgrzewkę na lekcji w-f lub obozie.', E'Poznał zasady i nauczył się grać w grę sportową nieolimpijską.', E'Nauczył zastęp zasad tej gry i zagrał w nią wspólnie z zastępem.']::text[]),
  (E'odkrywcy-sport-zabawy-zima', E'odkrywcy', E'fizyczny', E'sport', E'Sport', E'Zabawy Zimą', ARRAY[E'Nauczył się jeździć na łyżwach, sankach lub nartach.', E'Wie, jak zakonserwować i dbać o sportowy sprzęt zimowy.', E'Zadbał o swój sprzęt.', E'Razem z zastępem był na lodowisku, stoku zjazdowym, saneczkowym.']::text[]),
  (E'odkrywcy-sport-znawca-dyscypliny-olimpijskiej', E'odkrywcy', E'fizyczny', E'sport', E'Sport', E'Znawca Dyscypliny Olimpijskiej', ARRAY[E'Przeczytał z Rodzicami werset I Kor. 9:24 i porozmawiał o tym, jakie nastawienie do treningów powinni mieć sportowcy. Wspólnie ustalili, czy i jak może rozwijać się w jakiejś dyscyplinie sportu.', E'Interesuje się olimpijską dyscypliną sportu. Był na min. 10 zajęciach dodatkowych, treningach, na których rozwijał się w tej dyscyplinie.', E'Brał udział jako zawodnik w jakimś wydarzeniu sportowym z tej dyscypliny: turniej, rozgrywki, mecz międzyszkolny itp.', E'Przedstawił podstawowe zasady tej dyscypliny na zbiórce, obozie, biwaku i opowiedział zastępowi, co jest pasjonującego w tym sporcie. Przygotował i opowiedział o najciekawszych ostatnich wydarzeniach i sportowcach z tej dyscypliny.']::text[]),
  (E'odkrywcy-szczep-igielka', E'odkrywcy', E'spoleczny', E'szczep', E'Szczep', E'Igiełka', ARRAY[E'Zna kilka ściegów, potrafi przyszyć guzik i naszywkę. Umiejętności zaprezentował.', E'Poszerzył wiedzę na temat nazwy zastępu.', E'Współuczestniczył w tworzeniu okrzyku i piosenki zastępu.', E'Zaprojektował wraz z zastępem proporzec zastępu. Szył, haftował - czynnie uczestniczył w tworzeniu proporca zastępu.']::text[]),
  (E'odkrywcy-szczep-iskierka', E'odkrywcy', E'spoleczny', E'szczep', E'Szczep', E'Iskierka', ARRAY[E'Zna wszystkie osoby z zastępu. Zaproponował wspólne spotkanie zastępu poza zbiórkami.', E'Zapoznał się z kroniką szczepu lub w innej formie poznał historię szczepu.', E'Przez min. pół roku brał udział we wszystkich zbiórkach i akcjach swojego zastępu (biwaki, obozy, spotkania). Aktywnie w nich uczestniczył.', E'Współuczestniczył wraz z zastępem w organizacji imprezy szczepowej.']::text[]),
  (E'odkrywcy-szczep-starter', E'odkrywcy', E'spoleczny', E'szczep', E'Szczep', E'Starter', ARRAY[E'Zapoznał się z kroniką zastępu lub w innej formie poznał historię zastępu i jego obrzędowość.', E'Opowiedział dwóm osobom z klasy o RR i zachęcił do przyjścia na zbiórkę.', E'Przygotował i zaprezentował na zbiórce w formie pracy plastyczno-literackiej reportaż z wybranej zbiórki.']::text[]),
  (E'odkrywcy-szczep-zuch', E'odkrywcy', E'spoleczny', E'szczep', E'Szczep', E'Zuch', ARRAY[E'Przeprowadził wywiad z rówieśnikiem z innej organizacji skautowej.', E'Poznał Prawo wybranej organizacji skautowej, innej niż RR.', E'Porównał Prawo RR z Prawem innej organizacji skautowej, opowiedział o swych spostrzeżeniach na zbiórce.', E'Przedstawił na zbiórce zgromadzone informacje na temat innej organizacji harcerskiej.']::text[]),
  (E'odkrywcy-szkola-grupa-rowiesnicza-emblemat', E'odkrywcy', E'spoleczny', E'szkola-grupa-rowiesnicza', E'Szkoła i grupa rówieśnicza', E'Emblemat', ARRAY[E'Zademonstrował wśród rówieśników jedną umiejętność skautową.', E'Zaprosił osobę z klasy na zbiórkę lub akcję organizowaną przez RR.', E'Dba o mundur, w dniu mundurowym zakłada go do szkoły.', E'Zaprezentował w szkole organizację RR poprzez prezentację swojego zastępu (w formie opowiadania).']::text[]),
  (E'odkrywcy-szkola-grupa-rowiesnicza-pomagam-w-szkole', E'odkrywcy', E'spoleczny', E'szkola-grupa-rowiesnicza', E'Szkoła i grupa rówieśnicza', E'Pomagam w Szkole', ARRAY[E'Sumiennie wypełnia powierzone mu funkcje klasowe.', E'Zapoznał się z prawami i obowiązkami ucznia w swojej szkole.', E'Dowiedział się od wychowawcy, jak może pomóc w pracach szkolnych. Pomógł w konkretnej sytuacji.', E'Współuczestniczył w organizacji dowolnego przedsięwzięcia klasowego.']::text[]),
  (E'odkrywcy-szkola-grupa-rowiesnicza-znajomek', E'odkrywcy', E'spoleczny', E'szkola-grupa-rowiesnicza', E'Szkoła i grupa rówieśnicza', E'Znajomek', ARRAY[E'Przedstawił się w nowym otoczeniu – powiedział, jak się nazywa, co lubi, jakie ma hobby, co potrafi najlepiej itp. Opowiedział o tym na zbiórce.', E'Zna wszystkie osoby z klasy - potrafi o każdym z nich coś powiedzieć (co lubi, czy ma rodzeństwo, jakie ma hobby itp.).', E'Poznał trzy nowe osoby w swoim wieku. Sam wyszedł z inicjatywą poznania się.', E'Przygotował drobny prezent dla wybranego kolegi/wybranej koleżanki.']::text[]),
  (E'odkrywcy-technologia-bajtek', E'odkrywcy', E'intelektualny', E'technologia', E'Technologia', E'Bajtek', ARRAY[E'Korzystając z komputera połączył się z siecią. Podłączył wszystkie potrzebne urządzenia (myszkę, drukarkę, zasilacz).', E'Wykonał podstawowe czynności na komputerze: napisał tekst w edytorze tekstu i wydrukował go tworzył katalogi, przenosił, kopiował i usuwał pliki, napisał i wysłał wiadomość e-mail.', E'Znalazł potrzebne informacje w Internecie.', E'Obsługując komputer przestrzegał zasad bezpiecznego użytkowania.']::text[]),
  (E'odkrywcy-technologia-moj-robot', E'odkrywcy', E'intelektualny', E'technologia', E'Technologia', E'Mój Robot', ARRAY[E'Zna środowisko Scratch lub innego języka do nauki programowania.', E'Napisał prostą grę.', E'Był na warsztatach z programowania.', E'Na przykładzie gry takiej jak Minecraft pokazał, czego mogą nas nauczyć gry komputerowe oraz jakie zagrożenia niosą ze sobą.']::text[]),
  (E'odkrywcy-technologia-pixel', E'odkrywcy', E'intelektualny', E'technologia', E'Technologia', E'Pixel', ARRAY[E'Posiada własny aparat fotograficzny. Potrafi dopasować tryby fotografowania do danej sytuacji.', E'Potrafi zgrać zdjęcia do pamięci komputera.', E'Na zbiórce przedstawił album wykonanych przez siebie zdjęć.', E'Nauczył fotografować innego skauta.']::text[]),
  (E'odkrywcy-technologia-skad-sie-bierze', E'odkrywcy', E'intelektualny', E'technologia', E'Technologia', E'Skąd się Bierze', ARRAY[E'Wziął udział w wycieczce do zakładu rzemieślniczego.', E'Przeczytał książkę, z której dowiedział się wielu rzeczy na tematy techniczne, do tej pory niezrozumiałe. Opowiedział na zbiórce o pięciu zaskakujących dla siebie odkryciach technicznych.', E'Wziął udział w tematycznej imprezie etnograficznej lub był w muzeum techniki, gdzie poznał zasady działania archaicznych maszyn i urządzeń.', E'Wyszukał i przedstawił na zbiórce ciekawe doświadczenie z chemii.']::text[]),
  (E'odkrywcy-terenoznawstwo-kompasik', E'odkrywcy', E'fizyczny', E'terenoznawstwo', E'Terenoznawstwo', E'Kompasik', ARRAY[E'Wyznaczył strony świata za pomocą kompasu.', E'Potrafi zorientować mapę według kompasu i wyznaczyć właściwy azymut.', E'Przy pomocy kompasu dotarł do celu oddalonego o około dwa kilometry, mając za wskazówki tylko azymuty i odległości.', E'Dokonał parokrokami pomiaru odcinka długości ok. jednego kilometra, przeliczył parokroki na metry.']::text[]),
  (E'odkrywcy-terenoznawstwo-lekka-stopa', E'odkrywcy', E'fizyczny', E'terenoznawstwo', E'Terenoznawstwo', E'Lekka Stopa', ARRAY[E'Potrafi naśladować odgłosy przynajmniej jednego ptaka i jednego ssaka, żyjących dziko.', E'Rozpoznał strony świata w terenie (odkrytym i zalesionym, w pogodny dzień i przy całkowitym zachmurzeniu) po naturalnych znakach.', E'Rozpoznał w lesie ślady zwierząt, ludzi i pojazdów.', E'Zapamiętał przebytą drogę w terenie leśnym i wrócił nią samodzielnie bez błądzenia.']::text[]),
  (E'odkrywcy-terenoznawstwo-w-chmurach', E'odkrywcy', E'fizyczny', E'terenoznawstwo', E'Terenoznawstwo', E'W Chmurach', ARRAY[E'Potrafi rozpoznać i nazwać różne rodzaje chmur. Wie, jak powstają chmury, jak się przemieszczają i co zwiastują.', E'Zmierzył temperaturę powietrza, wody, ciśnienie, ocenił kierunek i prędkość wiatru.', E'Wykonał prosty przyrząd meteorologiczny, np. wiatromierz lub deszczomierz.', E'Przez okres dwóch tygodni dokonywał pomiarów i obserwacji, prowadził dziennik pogody. Wyniki pokazał na zbiórce zastępu.']::text[]),
  (E'odkrywcy-terenoznawstwo-znaki-patrolowe', E'odkrywcy', E'fizyczny', E'terenoznawstwo', E'Terenoznawstwo', E'Znaki Patrolowe', ARRAY[E'Zna podstawowe znaki topograficzne.', E'Uczestniczył w biegu patrolowym, poruszając się po znakach patrolowych.', E'Zna i posługiwał się w grach/biegach terenowych ok. 20 znakami patrolowymi.', E'Uczestniczył w min. trzech grach terenowych.']::text[]),
  (E'odkrywcy-wedrowka-kajakarz', E'odkrywcy', E'fizyczny', E'wedrowka', E'Wędrówka', E'Kajakarz', ARRAY[E'Uczestniczył w spływie kajakowym.', E'Potrafi wiosłować w kajaku dwuosobowym.', E'Zademonstrował wsiadanie i wysiadanie z kajaka i pomostu oraz wie, jak przenosić kajak.', E'Wziął udział w zbiórce na wodzie (kajaki, pontony, rowery wodne itp.) Zna zasady BHP na wodzie.']::text[]),
  (E'odkrywcy-wedrowka-lazik', E'odkrywcy', E'fizyczny', E'wedrowka', E'Wędrówka', E'Łazik', ARRAY[E'Potrafi skompletować indywidualny ekwipunek turystyczny na wędrówkę.', E'Uczestniczył w min. trzech wycieczkach, ubierając się stosownie do warunków terenowych i pogodowych.', E'Potrafi zabezpieczyć się przed deszczem, przegrzaniem, otarciem stóp.', E'Zna zasady poruszania się po drogach w czasie wycieczki oraz wie, jak zachować się podczas postoju.']::text[]),
  (E'odkrywcy-wedrowka-rower', E'odkrywcy', E'fizyczny', E'wedrowka', E'Wędrówka', E'Rower', ARRAY[E'Umie jeździć na rowerze i zna zasady bezpiecznego poruszania się pieszych i rowerzystów po drogach.', E'Zna budowę roweru i wie, jak należy go konserwować.', E'Wie, jaka jest różnica między wymijaniem, omijaniem i wyprzedzaniem oraz zna zasady pierwszeństwa przejazdu.', E'Wziął udział w wycieczce rowerowej.']::text[]),
  (E'odkrywcy-wedrowka-wskazidroga', E'odkrywcy', E'fizyczny', E'wedrowka', E'Wędrówka', E'Wskazidroga', ARRAY[E'Zna najbliższą okolicę zamieszkania i potrafi swobodnie się po niej poruszać.', E'Wskazał drogę do urzędów, stacji PKP i PKS, najbliższych sklepów, posterunku policji, apteki itp.', E'W czasie gry lub zwiadu orientował się w terenie i poprowadził do określonego miejsca. Odszukał wyznaczone miejsce lub obiekt.', E'Poznał obiekt godny odwiedzenia (zabytek, pomnik, miejsce osobliwe) i opowiedział o nim na zbiórce zastępu.']::text[]),
  (E'wedrownicy-alarm-manewry', E'wedrownicy', E'fizyczny', E'alarm', E'Alarm', E'Manewry', ARRAY[E'Zna Regulamin Musztry RRP i ceremoniał szczepowy. Przestrzega ich.', E'Wziął udział w przygotowaniu drużyny/szczepu do uroczystości skautowych. Dba o należyte umundurowanie w szczepie.', E'Poprowadził szkolenie dla młodszego zastępu z zakresu musztry.', E'W zespole 2-3-osobowym przygotował i poprowadził manewry dla młodszych skautów z elementami musztry, alarmów i sygnalizacji.']::text[]),
  (E'wedrownicy-alarm-rozmawiam-z-gluchoniemym', E'wedrownicy', E'fizyczny', E'alarm', E'Alarm', E'Rozmawiam Z Głuchoniemym', ARRAY[E'Ukończył kurs języka migowego.', E'Zapoznał się z osobą głuchoniemą i systematycznie rozmawiał z nią raz na tydzień przez trzy miesiące.', E'Poprowadził trzy zajęcia dla grupy z podstaw migania i nauczył uczestników alfabetu migowego.', E'Zaprosił osobę głuchoniemą na zbiórkę i był jej tłumaczem.']::text[]),
  (E'wedrownicy-alarm-szyfrant', E'wedrownicy', E'fizyczny', E'alarm', E'Alarm', E'Szyfrant', ARRAY[E'Zna alfabet Morse’a i różne sposoby szyfrowania wiadomości. Nadawał i odbierał wiadomości za pomocą sygnałów dźwiękowych i świetlnych.', E'Nawiązał łączność za pomocą CB, zna zasady pracy na fali.', E'Wykonał przyrząd do sygnalizacji w terenie. Nadał i odebrał za jego pomocą zaszyfrowaną depeszę.', E'Nadawał i odbierał wiadomości w min. trzech różnych szyfrach.']::text[]),
  (E'wedrownicy-biblia-droga-zbawienia', E'wedrownicy', E'duchowy', E'biblia', E'Biblia', E'Droga Zbawienia', ARRAY[E'Przeczytał cały List do Rzymian. Porozmawiał z mentorem na temat swojej drogi do Boga.', E'Wyjaśnił innej osobie, dlaczego cała Biblia opisuje plan zbawienia ludzkości.', E'Zna na pamięć nicejsko-konstantynopolitańskie wyznanie wiary i potrafi je wytłumaczyć swoimi słowami.', E'Dla młodszych skautów poprowadził zajęcia ze zrozumienia Pisma Świętego.']::text[]),
  (E'wedrownicy-biblia-kreacjonista', E'wedrownicy', E'duchowy', E'biblia', E'Biblia', E'Kreacjonista', ARRAY[E'Przeczytał Rzym. 1:18-25. Potrafi objaśnić, na czym polega poznanie Stwórcy poprzez Jego dzieła w kontekście kreacjonizmu.', E'Przeczytał kilka książek kreacjonistycznych i obejrzał kilka filmów. Wziął udział w konferencji kreacjonistycznej lub zapoznał się z zapisem video. Przedstawił na zbiórce linię czasu od Stworzenia do czasów dzisiejszych.', E'Rozróżnia fakty od ich interpretacji światopoglądowej. Przedstawił interpretację podstawowych argumentów ewolucyjnych z punktu widzenia kreacjonizmu.', E'Przeprowadził minidebatę kreacjonistyczno-ewolucyjną dla swojej grupy wiekowej lub wziął w takiej debacie udział jako strona.']::text[]),
  (E'wedrownicy-biblia-wiarygodnosc-biblii', E'wedrownicy', E'duchowy', E'biblia', E'Biblia', E'Wiarygodność Biblii', ARRAY[E'Zna wszystkich autorów ksiąg biblijnych. Dowiedział się, kim byli i w jakich okolicznościach napisali swoje księgi. Przestudiował jedną z tych postaci i opowiedział o niej na zbiórce.', E'Ma w domu kilka własnych tłumaczeń Biblii, potrafi wytłumaczyć, jak i kiedy powstały. Zna historię Wulgaty, Septuaginty, zwojów z Qumran. Opowiedział o nich na zbiórce.', E'Na podstawie przeczytanych lektur przedstawił na zbiórce prezentację/wykład na temat wiarygodności pism biblijnych.', E'Dla młodszych skautów poprowadził zajęcia z historii pism Starego i Nowego Testamentu.']::text[]),
  (E'wedrownicy-biblia-znawca-biblii', E'wedrownicy', E'duchowy', E'biblia', E'Biblia', E'Znawca Biblii', ARRAY[E'Przeczytał całą Biblię, potrafi się po niej poruszać. Zna historie i postacie biblijne i potrafi je bez trudu odnaleźć w Biblii.', E'Potrafi wytłumaczyć pojęcia: natchnienie, Słowo Boże, kanon, przymierze, Dobra Nowina.', E'Z zespołem 2- 3-osobowym zorganizował quiz/turniej wiedzy biblijnej dla młodszego zastępu lub na obozie.', E'Zrobił z zespołem 2- 3-osobowym tablice ułatwiające przyswojenie wiedzy biblijnej.']::text[]),
  (E'wedrownicy-czytelnictwo-bibliofil', E'wedrownicy', E'intelektualny', E'czytelnictwo', E'Czytelnictwo', E'Bibliofil', ARRAY[E'Zgromadził własny księgozbiór i prowadzi jego katalog rzeczowy.', E'Wykonał ex libris do biblioteki domowej, szkolnej lub publicznej.', E'Urządził w szczepie wystawę ciekawych książek, prezentując na niej także własne zbiory.', E'Nawiązał kontakt z najbliższym antykwariatem, poznał sposoby gromadzenia i przechowywania starodruków.']::text[]),
  (E'wedrownicy-czytelnictwo-mistrz-czytania', E'wedrownicy', E'intelektualny', E'czytelnictwo', E'Czytelnictwo', E'Mistrz Czytania', ARRAY[E'Czyta jedną książkę tygodniowo.', E'Ukończył kurs szybkiego czytania.', E'Czyta dużo i różne gatunki książek.', E'Ma swojego ulubionego poetę. Zna wielu autorów - potrafi wymienić tytuły ich książek.']::text[]),
  (E'wedrownicy-czytelnictwo-moj-ksiegozbior', E'wedrownicy', E'intelektualny', E'czytelnictwo', E'Czytelnictwo', E'Mój Księgozbiór', ARRAY[E'Od dłuższego czasu kupuje i zbiera książki.', E'Zrobił spis książek, które chciałby mieć w swoim księgozbiorze i systematycznie je nabywa.', E'Ma swój własny ex libris. Prowadzi spis pożyczonych książek.', E'Zgromadził własny księgozbiór i prowadzi jego katalog rzeczowy. Pokazał go osobom z zastępu.']::text[]),
  (E'wedrownicy-czytelnictwo-stary-testament', E'wedrownicy', E'intelektualny', E'czytelnictwo', E'Czytelnictwo', E'Stary Testament', ARRAY[E'Przeczytał cały Stary Testament.', E'Zrobił studium biblijne postaci ze Starego Testamentu.', E'Przeprowadził na zbiórce dla młodszego zastępu poselstwo z wykorzystaniem historii ze Starego Testamentu.', E'Poprowadził wykład/dyskusję na zbiórce zastępu/drużyny na temat starotestamentowy.']::text[]),
  (E'wedrownicy-harce-mistrz-harcow', E'wedrownicy', E'spoleczny', E'harce', E'Harce', E'Mistrz Harców', ARRAY[E'Wymyślił, wyszukał i zaadaptował na własne potrzeby zestaw gier niekonwencjonalnych, powiązanych tematycznie, zorganizowanych w turniej/olimpiadę dla szczepu.', E'Poszerzył swoją wiedzę na temat elementu rywalizacji - dowiedział się, jak nie wprowadzać do zabawy elementów agresji i przemocy i jak stworzyć atmosferę zaufania i przyjaźni.', E'Brał udział jako uczestnik w co najmniej dwóch turniejach gier niekonwencjonalnych, gromadzi w dowolnej formie scenariusze takich gier.', E'Zrealizował przygotowany turniej dla szczepu, wyciągnął wnioski na przyszłość (plusy i minusy gier), zaprezentował je w zastępie.\nUwagi: można przygotowywać w 2-3 osoby']::text[]),
  (E'wedrownicy-harce-szuwarek', E'wedrownicy', E'spoleczny', E'harce', E'Harce', E'Szuwarek', ARRAY[E'Wymyślił, wyszukał, np. w Internecie i zaadaptował na własne potrzeby zestaw zabaw wodnych (w wodzie lub z wykorzystaniem wody), mających na celu integrację (czas trwania zabaw: 30 minut).', E'Dowiedział się, jakie są zasady bezpiecznych zabaw z wodą.', E'Był na obozie lub innej formie spotkania letniego, w czasie którego brał udział w zabawach integracyjnych wodnych. Aktywizuje grupę do uczestnictwa w zabawach integracyjnych.', E'Przygotował rekwizyty, zrealizował przygotowaną zabawę, wyciągnął wnioski na przyszłość (plusy i minusy scenariusza zabawy), zaprezentował je w zastępie.\nUwagi: można przygotowywać w 2-3 osoby']::text[]),
  (E'wedrownicy-harce-terenowka', E'wedrownicy', E'spoleczny', E'harce', E'Harce', E'Terenówka', ARRAY[E'Stworzył scenariusz dowolnej gry terenowej/fabularnej/gry miejskiej i dostosował go do potrzeb szczepu (gra dla uczestników w różnym wieku). Przygotował kalkulację, obliczył czas trwania (czas gry: min. dwie godziny), obliczył zapotrzebowanie na pomocników, uwzględnił zróżnicowanie wiekowe uczestników w przygotowanych zadaniach itp.', E'Zapoznał się z zasadami tworzenia gier/zabaw dla różnych grup wiekowych, poznał reguły i opracował je tak, aby gra była przyjemna, pożyteczna i gwarantująca uczestnikom bezpieczeństwo.', E'Aktywnie uczestniczy w grach terenowych. Aktywizuje grupę w tym obszarze. Wziął udział jako uczestnik w co najmniej trzech grach terenowych, gromadzi w dowolnej formie scenariusze gier fabularnych, umie wskazać na słabe i mocne punkty scenariusza gier, w których brał udział i wykorzystać je w swojej propozycji.', E'Zorganizował stworzoną przez siebie grę dla szczepu, przygotował teren, rekwizyty, pomocników, nagrody. Zdał sprawozdanie, wyciągnął wnioski na przyszłość (plusy i minusy scenariuszy gier).\nUwagi: można przygotowywać w 2-3 osoby']::text[]),
  (E'wedrownicy-harce-wodzirej', E'wedrownicy', E'spoleczny', E'harce', E'Harce', E'Wodzirej', ARRAY[E'Przygotował scenariusz zabawy w oparciu o pląsy, tańce i zabawy ruchowe w kole dla młodszych zastępów lub innej grupy. Przygotował kalkulację, obliczył czas trwania (czas zabawy: min. jedna godzina), obliczył zapotrzebowanie na pomocników, rekwizyty, uwzględnił przerwy itp.', E'Rozumie rolę i odpowiedzialność animatora zabawy, dowiedział się, w jaki sposób ustalić porządek zabawy, aby spełniała ona możliwie jak najwięcej celów; dowiedział się, jak motywować i aktywizować w sposób godny uczestników zabawy.', E'Gromadzi w dowolnej formie scenariusze zabaw, pląsów, potrafi zaimprowizować zabawę.', E'Zrealizował przygotowaną zabawę dla młodszych, wyciągnął wnioski na przyszłość (plusy i minusy scenariusza zabawy), zaprezentował je w zastępie.\nUwagi: można przygotowywać w 2-3 osoby']::text[]),
  (E'wedrownicy-historia-historyk', E'wedrownicy', E'intelektualny', E'historia', E'Historia', E'Historyk', ARRAY[E'Wziął udział w olimpiadzie/turnieju wiedzy historycznej. W ciekawy sposób przedstawił zastępowi fakty wydarzenia historycznego.', E'Zna historię świąt: Narodowy Dzień Pamięci Żołnierzy Wyklętych, Święto Narodowe Trzeciego Maja, Narodowy Dzień Pamięci Powstania Warszawskiego, Święto Wojska Polskiego i Narodowe Święto Niepodległości.', E'Opowiedział trzy gawędy, biorąc za wątek ciekawe i pouczające wydarzenia historyczne.', E'Na biwaku/obozie wprowadził do tematyki i obrzędowości elementy z wybranego okresu historycznego.']::text[]),
  (E'wedrownicy-historia-kronikarz', E'wedrownicy', E'intelektualny', E'historia', E'Historia', E'Kronikarz', ARRAY[E'W dowolnej formie prowadził w okresie min. roku kronikę szczepu. Stosując różne formy wpisów w kronice zadbał o stronę graficzną.', E'Zna zasady kronikarskiego rzemiosła i zebrał pomysły na tworzenie kronik. Zrobił prezentację różnych kronik i podpowiedział młodszym kronikarzom, jak tworzyć ładną i ciekawą kronikę zastępu.', E'Stworzył kronikę rodzinną. Dbał o zdjęcia i wpisy z okresu teraźniejszego oraz uzupełniał kronikę zdjęciami i wątkami z przeszłości.', E'Sporządzał notatki z wydarzeń rodzinnych sprzed lat na podstawie relacji świadków lub informacji z drugiej ręki. Redagował je i wpisywał do rodzinnej kroniki.']::text[]),
  (E'wedrownicy-historia-kulturoznawca', E'wedrownicy', E'intelektualny', E'historia', E'Historia', E'Kulturoznawca', ARRAY[E'Potrafi po gwarze rozpoznać, z jakiego regionu pochodzi dana osoba. Zna po kilkanaście słów z kilku gwar.', E'Wie, jak wyglądają i czym się różnią stroje ludowe z różnych części Polski.', E'Opowiedział na zbiórce zastępu, skąd się wywodzi jakaś regionalna tradycja (obyczaj, pogląd, wierzenie).', E'Na obozie/akcji międzyszczepowej/szczepowej zrobił z zespołem 2-3-osobowym prezentację ciekawostek regionalnych: strojów, gwary, żartów, dań itp.']::text[]),
  (E'wedrownicy-historia-znawca-skautingu', E'wedrownicy', E'intelektualny', E'historia', E'Historia', E'Znawca Skautingu', ARRAY[E'Zna historię skautingu, harcerstwa i RR. Wie, jakie były początki tych ruchów i jak to wygląda dzisiaj.', E'Wie, na czym polega działanie skautowych organizacji światowych (WOSM i WAGGGS).', E'Zna najważniejsze organizacje skautowe działające w krajach europejskich. Potrafi po mundurach rozpoznać przynależność organizacyjną skautów.', E'Samodzielnie przygotował zbiórkę na temat skautingu.']::text[]),
  (E'wedrownicy-logika-arcymistrz', E'wedrownicy', E'intelektualny', E'logika', E'Logika', E'Arcymistrz', ARRAY[E'Wykazał się znajomością zasad gry w warcaby, szachy i go. Poznał i opowiedział na zbiórce, skąd się wywodzą te gry.', E'Zna min. trzy odmiany gry w go, zna japoński i chiński system liczenia wyników. Zrobił miniturniej gry w go i opowiedział o regułach i zwyczajach turniejowych.', E'Zrealizował pomysł na uczenie skautów zasad gry w go.', E'Zachęcił do gry w go osoby z zastępu, wytłumaczył zasady gry i pokazał, jak w nią grać.']::text[]),
  (E'wedrownicy-logika-madra-glowa', E'wedrownicy', E'intelektualny', E'logika', E'Logika', E'Mądra Głowa', ARRAY[E'Poznał zasady rozwiązywania Obrazków Logicznych (patrz: czasopismo Logi Mix). Rozwiązał samodzielnie 10 obrazków logicznych o podwyższonym stopniu trudności.', E'Wyszukał w Internecie lub w odpowiedniej książce 20 matematycznych zagadek logicznych (np. L. Pijanowski, Rozkosze łamania głowy), samodzielnie je rozwiązał.', E'Zachęcił do rozwiązywania i nauczył rozwiązywać Obrazki Logiczne kolegów w zastępie.', E'W zespole 2-3-osobowym zorganizował dla szczepu turniej w rozwiązywaniu zadań logicznych, obrazków logicznych, sudoku, kakuro itp.']::text[]),
  (E'wedrownicy-logika-mistrz-gier', E'wedrownicy', E'intelektualny', E'logika', E'Logika', E'Mistrz Gier', ARRAY[E'Zna zasady i potrafi grać w co najmniej pięć zaawansowanych gier planszowych (strategiczne bądź ekonomiczne: Ryzyko, Cashflow, Wysokie napięcie, Agricola, Puerto Rico itd.).', E'Zrealizował pomysł na uczenie skautów zasad gry w gry planszowe.', E'Prowadzi szczepowy magazyn gier planszowych.', E'W zespole 2-3-osobowym zorganizował dla szczepu turniej gier planszowych.']::text[]),
  (E'wedrownicy-logika-mowca', E'wedrownicy', E'intelektualny', E'logika', E'Logika', E'Mówca', ARRAY[E'W atrakcyjny sposób opowiedział na zbiórce jedną z przeczytanych książek o tematyce skautowej, zachęcając słuchaczy do jej przeczytania. W trakcie wystąpienia modulował głos.', E'Przeprowadził dla zastępu zajęcia z komunikacji. Przedstawił podstawowe założenia negocjacji i znaczenie mowy ciała.', E'Opowiedział „na zamówienie” trzy ciekawe gawędy: tematyczną, relacjonującą jakieś wydarzenie oraz dostosowaną do wybranej sytuacji.', E'Przeprowadził ćwiczenie, dyskusję lub debatę, podczas której skutecznie negocjował między stronami.']::text[]),
  (E'wedrownicy-misja-bog-czyni-cuda', E'wedrownicy', E'duchowy', E'misja', E'Misja', E'Bóg Czyni Cuda', ARRAY[E'Zrobił samodzielne studium cudów Jezusa i cudów uczynionych przez uczniów w Nowym Testamencie. Wnioskami podzielił się na biwaku/obozie.', E'Przeczytał książkę będącą świadectwem nadprzyrodzonego wydarzenia. Opowiedział o niej na zbiórce i zachęcił innych do jej przeczytania.', E'Zastanowił się, co dla niego znaczy słowo z Jan 14:11-14. Porozmawiał o tym z liderem/ Rodzicem.', E'Porozmawiał z osobą, która doświadczyła cudu w swoim życiu. Zaprosił ją na zbiórkę, aby złożyła świadectwo.']::text[]),
  (E'wedrownicy-misja-dary', E'wedrownicy', E'duchowy', E'misja', E'Misja', E'Dary', ARRAY[E'Zrobił samodzielne studium na temat darów duchowych. Wnioskami podzielił się z zastępem.', E'Wziął udział w nauczaniach/konferencji, na której nauczano na temat darów duchowych. Wnioskami podzielił się z liderem/Rodzicem.', E'W modlitwie rozważał fragment I Kor. 12. Rozpoznał swój dar i ustalił, jak może go rozwijać. Porozmawiał o tym z liderem/Rodzicem.', E'Przygotował i powiedział poselstwo na temat jednego z darów duchowych.']::text[]),
  (E'wedrownicy-misja-misjonarz', E'wedrownicy', E'duchowy', E'misja', E'Misja', E'Misjonarz', ARRAY[E'Przestudiował samodzielnie fragmenty z Mar. 16:15-18 i Dz. 1:8. Modlił się, co dla niego znaczy ten fragment - jak ma iść i głosić? Porozmawiał o tym z liderem/Rodzicem.', E'Wziął udział w kilkudniowym wyjeździe misyjnym.', E'Brał udział w przygotowaniu duchowego programu misyjnego, miał tam swoje zadania i zrealizował je.', E'Zrobił prezentację z wyjazdu misyjnego dla młodszego zastępu.']::text[]),
  (E'wedrownicy-misja-obronca-wiary', E'wedrownicy', E'duchowy', E'misja', E'Misja', E'Obrońca Wiary', ARRAY[E'Zrobił samodzielne studium biblijne na temat wiary. Wnioskami podzielił się z zastępem.', E'Spotkał się z osobą w trudnej sytuacji. Wsparł ją modlitwą i Słowem Bożym. Porozmawiał o tym z liderem/Rodzicem.', E'Opowiedział na zbiórce, co najbardziej buduje jego wiarę i dlaczego.', E'Z zespołem 2- 3-osobowym zorganizował akcję, której celem było podtrzymanie w wierze osoby/osób. Opowiedział o tym na zbiórce.']::text[]),
  (E'wedrownicy-pasje-i-talenty-artysta', E'wedrownicy', E'spoleczny', E'pasje-i-talenty', E'Pasje i talenty', E'Artysta', ARRAY[E'Od dłuższego czasu zajmuje się sztukami plastycznymi, podnosi swoje umiejętności - zorganizował wystawę swoich prac dla szerszego grona odbiorców.', E'Ma swoich mistrzów, zna ich biografię i twórczość, pogłębia wiedzę związaną z uprawianą przez siebie techniką plastyczną, uczestniczy w konkursach.', E'Rozwija swój talent w ramach regularnych warsztatów, uczestniczył w plenerze, chodzi na wystawy, zna harmonogram najbliższych ciekawych wydarzeń artystycznych z wybranej przez siebie dziedziny sztuki.', E'Zaprosił na wystawę swoich prac, wykonał zaproszenia, plakaty, przygotował ekspozycję, wykorzystał tę sposobność do mówienia dobrej nowiny.']::text[]),
  (E'wedrownicy-pasje-i-talenty-kustosz', E'wedrownicy', E'spoleczny', E'pasje-i-talenty', E'Pasje i talenty', E'Kustosz', ARRAY[E'Przygotował prezentację swojego hobby dla szerszego grona odbiorców.', E'Rozwija swoją wiedzę na temat pasji, którą się zajmuje, potrafi wskazać na literaturę lub muzea, w których można poszerzać wiedzę na dany temat.', E'Skatalogował swoją kolekcję, udostępnił w Internecie.', E'Zorganizował prezentację swojego hobby, wykorzystał tę sposobność w celach ewangelizacyjnych.']::text[]),
  (E'wedrownicy-pasje-i-talenty-milosnik-przyrody', E'wedrownicy', E'spoleczny', E'pasje-i-talenty', E'Pasje i talenty', E'Miłośnik Przyrody', ARRAY[E'Przygotował cykliczne spotkania na temat ochrony przyrody.', E'Systematycznie pogłębia wiedzę na temat ochrony przyrody, zna dobrze problematykę eko w swoim regionie.', E'Jest odpowiedzialny w szczepie za rozpowszechnianie wiedzy na temat ochrony przyrody, bierze udział w konkursach tematycznych.', E'Zorganizował akcję o charakterze ekologicznym dla szerszego grona odbiorców.']::text[]),
  (E'wedrownicy-pasje-i-talenty-mistrz-sceny', E'wedrownicy', E'spoleczny', E'pasje-i-talenty', E'Pasje i talenty', E'Mistrz Sceny', ARRAY[E'Wyreżyserował lub współuczestniczył w przygotowaniu dramy ewangelizacyjnej, przygotował się do roli pod kątem gry aktorskiej, charakteryzacji, kostiumu.', E'Zna historię teatru, zna pojęcia sceniczne (np. kulisy, ekspresja sceniczna, improwizacja itp.), uczestniczy w warsztatach pogłębiając swoją wiedzę na temat aktorstwa.', E'Regularnie chodzi do teatru (lub w innej formie ogląda sztuki teatralne).', E'Zrealizował w przestrzeni miejskiej dramę ewangelizacyjną, poprowadził warsztaty aktorskie.\nUwagi: można realizować w 2-3 osoby']::text[]),
  (E'wedrownicy-pasje-i-talenty-muzyk', E'wedrownicy', E'spoleczny', E'pasje-i-talenty', E'Pasje i talenty', E'Muzyk', ARRAY[E'Przyjął na siebie obowiązki w kościele, szczepie, szkole związane ze swoim talentem.', E'Ma swoich mistrzów, zna ich biografię i twórczość, pogłębia swoją wiedzę w sposób systematyczny.', E'Jest członkiem chóru lub orkiestry, regularnie rozwija swój talent.', E'Wywiązuje się z obowiązków, jakie przyjął na siebie w kościele, szczepie, szkole związanych ze swoim talentem, wykorzystuje go również w celach ewangelizacyjnych.']::text[]),
  (E'wedrownicy-pasje-i-talenty-rekodzielo', E'wedrownicy', E'spoleczny', E'pasje-i-talenty', E'Pasje i talenty', E'Rękodzieło', ARRAY[E'Zaplanował cykliczne warsztaty z wybranej dziedziny rękodzieła (napisał scenariusze, kosztorys, potrzebne narzędzia itp.).', E'Stale poszerza wiedzę na temat danej formy rękodzielniczej, korzysta z filmów instruktażowych, warsztatów itp.', E'Przygotował materiał instruktażowy dla osób chcących zapoznać się z daną dziedziną rękodzielniczą, dzieli się swoją pasją z innymi, wskazuje na źródło swych talentów (forma ewangelizacji).', E'Zrealizował cykliczne warsztaty z nauką wybranej techniki, zachęcił inne osoby z zastępu do rozwijania swoich talentów.']::text[]),
  (E'wedrownicy-pasje-i-talenty-tancmistrz', E'wedrownicy', E'spoleczny', E'pasje-i-talenty', E'Pasje i talenty', E'Tancmistrz', ARRAY[E'Przygotował, nauczył innych, opracował plan układu choreograficznego o charakterze ewangelizacyjnym w przestrzeni miejskiej.', E'Interesuje się różnymi formami tańca, regularnie ogląda przedstawienia taneczne.', E'Regularnie uczy się tańca.', E'Zrealizował w przestrzeni miejskiej układ choreograficzny o charakterze ewangelizacyjnym, poprowadził warsztaty taneczne.']::text[]),
  (E'wedrownicy-pionierka-kuchmistrz', E'wedrownicy', E'fizyczny', E'pionierka', E'Pionierka', E'Kuchmistrz', ARRAY[E'Prawidłowo posługuje się sprzętem kuchennym (noże, garnki, patelnie, cedzak itp.)', E'Wybrał na biwaku miejsce na kuchnię, zbudował kuchnię polową, funkcjonalnie ją urządził.', E'Pokierował przygotowaniem trzech posiłków na obozie: śniadanie, dwudaniowy obiad, kolacja.', E'Ułożył jadłospis na obóz.']::text[]),
  (E'wedrownicy-pionierka-kwatermistrz', E'wedrownicy', E'fizyczny', E'pionierka', E'Pionierka', E'Kwatermistrz', ARRAY[E'Przeprowadził czynności kwatermistrzowskie związane z przygotowaniem i rozliczeniem obozu/biwaku: lista potrzebnego sprzętu, przygotowanie - zakupy, transport sprzętu, podział, końcowe rozliczenie.', E'Pełnił funkcję kwatermistrza w szczepie przez okres min. pół roku (może być w zespole dwuosobowym). W tym czasie zrobił: inwentaryzację sprzętu, wymagane naprawy oraz zakupy.', E'Opracował i zrealizował plan zagospodarowania terenu na obozie/biwaku.', E'Poprowadził zajęcia z młodszymi skautami na temat podstawowego sprzętu biwakowego zastępu. Nauczył ich zasad właściwego używania, przechowywania i konserwacji tego sprzętu. Pomógł zorganizować taki sprzęt młodszemu zastępowi.']::text[]),
  (E'wedrownicy-pionierka-mistrz-ogniska', E'wedrownicy', E'fizyczny', E'pionierka', E'Pionierka', E'Mistrz Ogniska', ARRAY[E'Wygłosił gawędę na temat ognia i zasad zachowywania się przy ognisku skautowym.', E'Przygotował ognisko na dużą imprezę szczepową.', E'Przeprowadził zajęcia dla młodszego zastępu z rozpalania ognia: rozpałka wstępna, A, zapałki-ołówki-kciuki itp.', E'Potrafi rozpalić ognisko w trudnych warunkach atmosferycznych (wiatr, deszcz, śnieg).']::text[]),
  (E'wedrownicy-pionierka-mocowania', E'wedrownicy', E'fizyczny', E'pionierka', E'Pionierka', E'Mocowania', ARRAY[E'Nauczył się rozpoznawać i wiązać 10 chwytów (węzłów mocujących) i użył ich na zbiórkach czy biwaku.', E'Zna pięć rodzajów pętli. Umie je zastosować.', E'Nauczył zastęp wykonywać po jednym rodzaju: plecionki, splotu i przewiązu.', E'Poprowadził zajęcia z młodszymi skautami na temat węzłów i mocowań. Nauczył ich wykonywania trzech podstawowych węzłów.']::text[]),
  (E'wedrownicy-poboznosc-animator', E'wedrownicy', E'duchowy', E'poboznosc', E'Pobożność', E'Animator', ARRAY[E'Przestudiował biblijną postać Tymoteusza. Zastanowił się, jak mógłby pomagać sobie i innym w duchowym rozwoju.', E'Przygotował i powiedział dwa poselstwa na zbiórkach na temat duchowego rozwoju.', E'Przeprowadził na biwaku/obozie zajęcia z rozwoju duchowego.', E'Zaangażował się w pomoc młodszym w duchowym rozwoju. Przez okres min. pół roku pomagał w prowadzeniu zajęć o tematyce duchowej dla młodszego zastępu. Zakres prac ustalił z liderem.']::text[]),
  (E'wedrownicy-poboznosc-chodze-z-bogiem', E'wedrownicy', E'duchowy', E'poboznosc', E'Pobożność', E'Chodzę Z Bogiem', ARRAY[E'Przestudiował biblijną opowieść o Henochu. Zastanowił się, jak wygląda jego osobista relacja z Bogiem. Porozmawiał o tym z liderem lub Rodzicem.', E'Przez min. trzy miesiące codziennie w planowy sposób rozwijał relację z Bogiem. Plan rozwoju omówił z liderem bądź Rodzicem.', E'Spotkał się z osobą (lub przeczytał inspirującą chrześcijańską książkę), która ma dobrą relację z Bogiem. Zrobił z nią wywiad na temat tego, jak pielęgnuje tę więź. Wnioskami z wywiadu podzielił się na zbiórce.', E'Opowiedział świadectwo na zbiórce/biwaku, w jaki sposób Bóg do niego mówi.']::text[]),
  (E'wedrownicy-poboznosc-dziesiecina', E'wedrownicy', E'duchowy', E'poboznosc', E'Pobożność', E'Dziesięcina', ARRAY[E'Samodzielnie przestudiował biblijny temat dziesięciny. O wnioskach porozmawiał z liderem lub Rodzicem.', E'Przez rok systematycznie odkładał dziesięcinę i modlił się, co powinien z nią zrobić. Zgodnie ze swoim przekonaniem przekazał ją.', E'Z zespołem 2-3-osobowym zorganizował zbiórkę pieniężną na określony cel dobroczynny.', E'Zrobił dla zastępu studium z ofiarności lub dziesięciny.']::text[]),
  (E'wedrownicy-poboznosc-swietowanie', E'wedrownicy', E'duchowy', E'poboznosc', E'Pobożność', E'Świętowanie', ARRAY[E'Zrobił samodzielne studium biblijne na temat tego, jak powinno się świętować. Sporządził listę wniosków i podzielił się nimi z rodziną.', E'Zrobił analizę świąt kościelnych swojego kościoła i dowiedział się, czym się charakteryzują, skąd się wywodzą. Wziął udział w aktywnym obchodzeniu min. dwóch z nich.', E'Zaplanował i zorganizował czas świąteczny w domu. Zaangażował do tego rodzeństwo, Rodziców lub dziadków.', E'W zespole 2-3-osobowym zorganizował świąteczną zbiórkę dla młodszego zastępu.']::text[]),
  (E'wedrownicy-poznawanie-swiata-korespondent', E'wedrownicy', E'intelektualny', E'poznawanie-swiata', E'Poznawanie świata', E'Korespondent', ARRAY[E'Przekazał napisany przez siebie reportaż z imprezy skautowej do lokalnej gazety.', E'Samodzielnie lub z pomocą kamerzysty nagrał i przesłał trzy materiały filmowe do szczepu przebywając za granicą na wycieczce/biwaku/obozie.', E'Wykazał się pięcioma własnymi artykułami na dowolny temat zamieszczonymi w prasie lub na stronie www.', E'Nauczył chętnych techniki recytacji, interpretacji tekstu. Zna ćwiczenia pozwalające na opanowanie głosu, dykcji, mimiki.']::text[]),
  (E'wedrownicy-poznawanie-swiata-obiezyswiat', E'wedrownicy', E'intelektualny', E'poznawanie-swiata', E'Poznawanie świata', E'Obieżyświat', ARRAY[E'Był na min. trzech wycieczkach/wakacjach w innych krajach. Zrobił prezentacje i opowiedział (pokazał zdjęcia, pamiątki) na zbiórce o ciekawych miejscach, które zobaczył.', E'Poznaje kulturę wybranego kraju poza Europą. Wykorzystał swą wiedzę z tej dziedziny w trakcie zajęć skautowych z młodszym zastępem.', E'Ma znajomych w innych krajach, które odwiedził. Koresponduje z nimi.', E'Zorganizował wycieczkę zagraniczną dla rodziny lub znajomych: miejsce, przejazdy, hotele, atrakcje itp. Wycieczkę zrealizował i opowiedział na zbiórce o doświadczeniach.']::text[]),
  (E'wedrownicy-poznawanie-swiata-przyrodoznawca', E'wedrownicy', E'intelektualny', E'poznawanie-swiata', E'Poznawanie świata', E'Przyrodoznawca', ARRAY[E'Obserwował życie lasu o świcie, zmierzchu i w nocy. Przedstawił swoje spostrzeżenia na zbiórce.', E'Zorganizował wycieczkę do rezerwatu przyrody. Pełnił w jej trakcie rolę przewodnika.', E'W zespole 2-3-osobowym zorganizował dla młodszego zastępu akcję o tematyce przyrodniczej.', E'Był w min. trzech parkach narodowych. Potrafi o nich opowiedzieć, zna ich szlaki, ścieżki edukacyjne itp. Zrobił prezentację o jednym z nich na zbiórce.']::text[]),
  (E'wedrownicy-poznawanie-swiata-religioznawca', E'wedrownicy', E'intelektualny', E'poznawanie-swiata', E'Poznawanie świata', E'Religioznawca', ARRAY[E'Potrafi wymienić pięć głównych religii świata i ich założycieli. Umie wyjaśnić ich główne dogmaty wiary.', E'Zorganizował wyjście zastępu do świątyni wyznawców wybranej religii (np. meczet, synagoga) i przedstawił kilka informacji z nią związanych.', E'Przeprowadził w drużynie dyskusję na temat tolerancji religijnej (czym ona jest, jakie są skutki nietolerancji itp.).', E'Dowiedział się, czym jest ekumenizm i dialog międzyreligijny. Wytłumaczył to na zbiórce.']::text[]),
  (E'wedrownicy-poznawanie-swiata-tlumacz', E'wedrownicy', E'intelektualny', E'poznawanie-swiata', E'Poznawanie świata', E'Tłumacz', ARRAY[E'Zdał państwowy egzamin potwierdzający biegłą znajomość języka obcego.', E'Przetłumaczył na język polski artykuł o tematyce skautowej. Zdobyte informacje zaprezentował na zbiórce.', E'Pomagał w tłumaczeniu materiałów w obcym języku o tematyce skautowej z czasopism, stron www.', E'Zaprezentował swoje umiejętności jako tłumacz podczas międzynarodowej akcji skautowej lub innej, tłumacząc na żywo.']::text[]),
  (E'wedrownicy-puszczanstwo-eskimos', E'wedrownicy', E'fizyczny', E'puszczanstwo', E'Puszczaństwo', E'Eskimos', ARRAY[E'Był z zastępem na biwaku zimowym, śpiąc w ogrzewanej jurcie.', E'Skompletował własny zimowy sprzęt turystyczny (ubranie, śpiwór, materac, kuchenka itp.).', E'Spędził noc w wykonanej przez siebie jamie śnieżnej lub igloo.', E'W zespole 2-3-osobowym przygotował biwak zimowy w terenie dla zastępu: jurta, ogrzewanie, zaplecze sanitarne i kuchenne, program itp.']::text[]),
  (E'wedrownicy-puszczanstwo-lesny-czlowiek', E'wedrownicy', E'fizyczny', E'puszczanstwo', E'Puszczaństwo', E'Leśny Człowiek', ARRAY[E'Przebywał z zastępem na biwaku przez min. trzy doby w lesie, z dala od obozu i skupisk ludzkich, bez kontaktu z cywilizacją.', E'Sporządził całodniowe menu i jadł posiłki bez użycia naczyń, np.: ryba w liściach, pieczone jajka, ciasto na kiju itp. Żywił się tylko darami lasu przez dwie doby.', E'Posługując się tylko nożem, zbudował sobie legowisko. Spędził min. jedną noc, śpiąc na hamaku.', E'Z zastępem zbudował szałas pokryty warstwą suchych liści z ogniskiem wewnątrz i nocował w nim przez min. dwie noce.']::text[]),
  (E'wedrownicy-puszczanstwo-lowca', E'wedrownicy', E'fizyczny', E'puszczanstwo', E'Puszczaństwo', E'Łowca', ARRAY[E'Bezbłędnie rozpoznaje podstawowe gatunki grzybów i roślin jadalnych i trujących. Zorganizował zbiory darów natury. Przygotował z nich posiłek dla zastępu.', E'Zna objawy zatrucia grzybami i roślinami trującymi, potrafi udzielić pierwszej pomocy w nagłym przypadku.', E'Zna sposoby znajdowania i zbierania/łapania: ślimaków, raków, ryb, ptaków i zwierząt. Poznał polskie przepisy dotyczące łowiectwa i wędkarstwa.', E'Prowadził zbiór roślin (zna kalendarz ich zbierania, wie, co zbierać). Zbiera, suszy i przechowuje zioła tak, by nie straciły swoich właściwości.']::text[]),
  (E'wedrownicy-puszczanstwo-znawca-ognia', E'wedrownicy', E'fizyczny', E'puszczanstwo', E'Puszczaństwo', E'Znawca Ognia', ARRAY[E'Zademonstrował rozpalanie ognia pięcioma sposobami bez pomocy zapałek (lupa, krzesiwo, łuk ogniowy, ziemniak, bateria itp.).', E'Ma swój sposób na utrzymanie i „noszenie” ognia. Utrzymał przy sobie ogień na wędrówce przez całą dobę.', E'Zbudował platformę ogniskową na kuchni polowej i osobno. Ugotował posiłek dla zastępu na ognisku w namiocie.', E'Był odpowiedzialny za ogniska na biwaku/obozie wędrownym. Zadbał o sprzęt gaśniczy, przeszkolił innych z zasad i przepisów przeciwpożarowych. Zostawił po sobie miejsca ogniskowe w idealnym stanie.']::text[]),
  (E'wedrownicy-rodzina-animator-krewnych', E'wedrownicy', E'spoleczny', E'rodzina', E'Rodzina', E'Animator Krewnych', ARRAY[E'Przygotował zjazd rodzinny, mający na celu zacieśnianie więzów rodzinnych.', E'Prowadził pamiętnik urodzinowy, czyli spis dat urodzin członków rodziny i wysyłał im życzenia w formie kartek, e-maili.', E'Zastanowił się, co znaczy pojęcie ‘kryzys więzi rodzinnych’. Zrealizował osobisty pomysł, jak temu przeciwdziałać w swojej rodzinie.', E'Przygotował i zaprezentował wykład/dyskusję dla grupy wędrowniczej na temat więzi rodzinnych z uwzględnieniem biblijnego punktu widzenia na tę sprawę.']::text[]),
  (E'wedrownicy-rodzina-jeden-za-wszystkich', E'wedrownicy', E'spoleczny', E'rodzina', E'Rodzina', E'Jeden Za Wszystkich', ARRAY[E'W trakcie np. wakacji, ferii lub kilku weekendów zorganizował atrakcyjnie czas dla młodszego rodzeństwa lub grupy młodszych dzieci (urodziny, wyjazd na lodowisko, klub pomocy, korepetycje itp.).', E'Przestudiował książkę na temat służby, misji itp. pod kątem realizacji zasady „Jedni drugim”.', E'W codziennym życiu stara się być pomocny młodszym, potrafi wskazać obszary, gdzie pomaga.', E'Stworzył dla szczepu bank pomysłów i zabaw dla młodszych lub uzupełnił istniejący o co najmniej 10 wpisów.\nUwagi: można realizować w 2-3 osoby']::text[]),
  (E'wedrownicy-rodzina-ocalic-wspomnienia', E'wedrownicy', E'spoleczny', E'rodzina', E'Rodzina', E'Ocalić Wspomnienia', ARRAY[E'Spisał, nagrał lub w innej formie udokumentował (np. skatalogował zdjęcia) historię swej rodziny do trzech pokoleń.', E'Zrobił wywiad ze starszymi mieszkańcami wspólnoty, miasta, okolicy na temat tego, jak zmieniło się otoczenie, zwyczaje, relacje (lub zgromadził tę wiedzę w inny sposób).', E'Czyta artykuły, uczestniczy w spotkaniach lub wycieczkach wzbogacających wiedzę na temat minionych czasów, potrafi biblijnie uzasadnić potrzebę pamięci pokoleniowej.', E'Zorganizował dla szczepu grę miejską w oparciu o przeprowadzone wywiady.']::text[]),
  (E'wedrownicy-rodzina-wspolny-wyjazd', E'wedrownicy', E'spoleczny', E'rodzina', E'Rodzina', E'Wspólny Wyjazd', ARRAY[E'Zorganizował wyjazd rodzinny z noclegiem (w porozumieniu z Rodzicami) lub przygotował piknik rodzinny z grami i zabawami integrującymi, rodzinny bieg patrolowy.', E'Przeczytał książkę na temat buntów w okresie dojrzewania. Rozpoznał w swoim zachowaniu obszar, w którym ma problemy z Rodzicami. Zaplanował, w jaki sposób może pracować nad swoim charakterem w kontekście relacji z Rodzicami.', E'Zaplanował i zorganizował wyjście z każdym z Rodziców osobno, spędzając z nim wspólny czas na rozrywce i rozmowach.', E'Przygotował dla wędrowników w szczepie dowolną akcję na rzecz poprawiania relacji z Rodzicami (prelekcja, film połączony z klubem dyskusyjnym itp.).']::text[]),
  (E'wedrownicy-samodyscyplina-animator-modlitwy', E'wedrownicy', E'duchowy', E'samodyscyplina', E'Samodyscyplina', E'Animator Modlitwy', ARRAY[E'Zrobił samodzielne studium biblijne na temat modlitwy. Sporządził listę wniosków i podzielił się nimi z liderem bądź Rodzicem.', E'Przynajmniej od pół roku prowadzi Dziennik Modlitewny - zapisuje w nim: intencje, dziękczynienia, prośby, wysłuchane modlitwy, słowa otrzymane od Boga itp.', E'Zaplanował i zorganizował systematyczne spotkania modlitewne (min. raz na dwa tygodnie) dla przyjaciół, znajomych, zastępu itp. Prowadzi je min. przez pół roku.', E'Poprowadził studium dla młodszego zastępu na temat modlitwy.']::text[]),
  (E'wedrownicy-samodyscyplina-studium-biblii', E'wedrownicy', E'duchowy', E'samodyscyplina', E'Samodyscyplina', E'Studium Biblii', ARRAY[E'Zna sposoby studiowania Biblii. Samodzielnie przestudiował wybrane zagadnienia: prawdę biblijną, postać biblijną, wydarzenie biblijne. Zrobił egzegezę wybranego fragmentu. Prowadził notatki.', E'Zorganizował cykl min. pięciu spotkań dla rówieśników, na których wspólnie rozważano i studiowano konkretny temat z Biblii. Spotkania prowadził.', E'Ukończył Kurs Alfa lub inny kurs, gdzie omawiane są podstawowe tematy chrześcijaństwa.', E'Poprowadził cykl tematycznego studium biblijnego na biwaku/obozie.']::text[]),
  (E'wedrownicy-samodyscyplina-szara-lilijka', E'wedrownicy', E'duchowy', E'samodyscyplina', E'Samodyscyplina', E'Szara Lilijka', ARRAY[E'Przez 24 godziny oderwał się od zwykłych spraw codziennych, nie kontaktował się, nie rozmawiał z nikim (polecana samotna wycieczka na cały dzień do lasu, w góry itd.). W tym czasie przemyślał Prawo RR i swój dotychczasowy do niego stosunek. Ocenił samego siebie i swoją wolę wypełniania Prawa RR.', E'Zastanowił się nad swoimi wadami, które przeszkadzają mu być dobrym skautem. Przemyślał i postanowił, jak będzie z nimi walczyć.', E'Przez min. trzy miesiące (do pół roku) walczył ze swoimi wadami. O szczegółach walki porozmawiał z liderem lub Rodzicem.', E'Sprawność skaut przyznaje sobie sam podczas spotkania zastępu/drużyny, zgodnie z poczuciem uczciwości i szczerym postanowieniem, że chce żyć zgodnie z zasadami skautowymi, zawartymi w Przyrzeczeniu i Prawie RR. W trakcie spotkania opowiada, co przeżył i co zrozumiał w okresie próby.']::text[]),
  (E'wedrownicy-samodyscyplina-wlocznia-swietego-jerzego', E'wedrownicy', E'duchowy', E'samodyscyplina', E'Samodyscyplina', E'Włócznia Świętego Jerzego', ARRAY[E'Przeczytał werset Łuk. 6:45. Porozmawiał z liderem lub Rodzicem, jak może obfitować w dobro wewnętrzne.', E'Ma sprecyzowany pogląd na świat. Jest osobą wierzącą i nie ukrywa tego. Powiedział o tym rówieśnikom w szkole.', E'Mówi to, co myśli. Stał po stronie słabszych i pokrzywdzonych. Przeciwstawił się jawnej niesprawiedliwości.', E'Opowiedział świadectwo na zbiórce/biwaku, w jaki sposób Bóg pomaga mu w trudnych sytuacjach - kiedy musiał przeciwstawić się złu.']::text[]),
  (E'wedrownicy-samozaradnosc-finansista', E'wedrownicy', E'intelektualny', E'samozaradnosc', E'Samozaradność', E'Finansista', ARRAY[E'Przestudiował wersety: Ps. 24:1; I Tym. 6:8; I Piotr 3:3-4; I Jan 2:15-16 i Przyp. 22:7. W modlitwie rozważył, jak powinien w biblijny sposób zarządzać swoimi finansami. O wnioskach porozmawiał z liderem. Przygotował i przeprowadził poselstwo na temat finansów.', E'Zachęcił dwie osoby i wspólnie opracowali swoje budżety na rok (ustalili zasady oszczędzania, wydawania i dawania). Konsekwentnie go przestrzegał. Systematycznie co miesiąc prowadził zestawienia przychodów i rozchodów.', E'Pełnił obowiązki skarbnika w zastępie, drużynie, na obozie lub wycieczce. Poprowadził i rozliczył się z akcji zarobkowej.', E'Podsumował swój roczny budżet i porozmawiał o tym z liderem. Zebrał wnioski i opinie od osób uczestniczących w elementach tej próby i podzielił się świadectwem na ten temat na zbiórce, w społeczności itp.']::text[]),
  (E'wedrownicy-samozaradnosc-lider-zdrowia', E'wedrownicy', E'intelektualny', E'samozaradnosc', E'Samozaradność', E'Lider Zdrowia', ARRAY[E'Wziął udział w szkoleniu dotyczącym zdrowej żywności i zdrowego żywienia.', E'Prowadzi zdrowy styl życia: zdrowe odżywianie, higiena nauki i pracy, sport, zdrowy sen. Ma na to konkretny plan i go stosuje.', E'Poprowadził zajęcia dla młodszych na temat uzależnień i konsekwencji z nich płynących.', E'W zespole 2-3-osobowym zorganizował akcję promującą zdrowy styl życia lub akcję antyuzależnieniową.']::text[]),
  (E'wedrownicy-samozaradnosc-przedsiebiorca', E'wedrownicy', E'intelektualny', E'samozaradnosc', E'Samozaradność', E'Przedsiębiorca', ARRAY[E'Przestudiował wersety: I Tes. 4:9-12; II Tes. 3:6-15. W modlitwie rozważył, do jakiej pracy jest uzdolniony. O wnioskach porozmawiał z Rodzicami. Wybrał szkołę ponadgimnazjalną, kierując się świadomym wyborem.', E'Wykonał płatną pracę na podstawie spisanej umowy (dzieło, zlecenie).', E'W zespole 2-3-osobowym wymyślił 3-miesięczny projekt biznesowy. Opracował strategię i budżet, zaangażował swoje środki. Po przeprowadzeniu projektu podzielił się wnioskami w zastępie/drużynie.', E'Ma spisane swoje obowiązki i cele: w domu, szkole, szczepie itp. Pracując z kalendarzem potrafi planować. Przedstawił w zastępie realizację zamierzonych celów dalekosiężnych (min. półrocznych) udokumentowanych systematyczną pracą.']::text[]),
  (E'wedrownicy-samozaradnosc-ratownik', E'wedrownicy', E'intelektualny', E'samozaradnosc', E'Samozaradność', E'Ratownik', ARRAY[E'Wziął udział w min. jednodniowym szkoleniu z pierwszej pomocy i BHP zakończonym uzyskaniem certyfikatu. Zademonstrował swoje umiejętności w zastępie.', E'Przeprowadził zajęcia dla młodszych z pierwszej pomocy i BHP na zbiórce lub biwaku/ obozie.', E'Przygotował zestaw ppoż. na biwaku/obozie. Poinstruował uczestników, gdzie będzie i jak należy go używać.', E'Zrobił przegląd wiedzy i umiejętności samarytańskich i BHP w szczepie/drużynie. Wnioski przedstawił drużynowemu lub komendantowi. (można zrealizować w 2-3 osoby).']::text[]),
  (E'wedrownicy-samozaradnosc-zlota-raczka', E'wedrownicy', E'intelektualny', E'samozaradnosc', E'Samozaradność', E'Złota Rączka', ARRAY[E'Dokonał dużej naprawy mechanicznej (roweru, samochodu, motocykla) lub wykonał remont pomieszczenia. Prace udokumentował zdjęciami.', E'Opanował bezpieczne wykonywanie czterech łączeń nierozłącznych (nitowanie, klejenie, lutowanie, spawanie itp.). Przeprowadził szkolenie na zbiórce/biwaku.', E'Zapoznał się z rodzajami rur, armaturą oraz narzędziami hydraulicznymi. Zaprojektował, skonsultował i wykonał w zespole prostą instalację sanitarną na potrzeby biwaku lub obozu (umywalnię, prysznic itp.)', E'Przeczytał książkę z dziedziny techniki (mechanika pojazdów, elektryka, elektronika itp.). Zdobytą wiedzą praktyczną podzielił się ze skautami.']::text[]),
  (E'wedrownicy-sluzba-innym-opiekun', E'wedrownicy', E'duchowy', E'sluzba-innym', E'Służba innym', E'Opiekun', ARRAY[E'Samodzielnie przestudiował fragment Łuk 10:30-37. Przygotował i przeprowadził poselstwo na temat prawdy biblijnej z tego fragmentu.', E'Znalazł osobę potrzebującą pomocy (osoby starsze, niepełnosprawne, samotne). Sprawdził, jakiej pomocy potrzebuje wybrana przez niego osoba i starał się zaspokoić tę potrzebę z zaangażowanymi przez siebie osobami lub zastępem przez min. trzy miesiące.', E'Pełnił służbę w innej akcji pomocy potrzebującym (kościelnej, szkolnej, publicznej).', E'Zebrał wnioski i opinie od osób uczestniczących w pomocy wybranej osobie, przedstawił wyniki i podzielił się świadectwem z zadań na zbiórce, w społeczności itp.']::text[]),
  (E'wedrownicy-sluzba-innym-pomocnik-spolecznosci', E'wedrownicy', E'duchowy', E'sluzba-innym', E'Służba innym', E'Pomocnik Społeczności', ARRAY[E'Przeczytał w różnych tłumaczeniach werset Przyp. 24:27 i zastanowił się, o czym on mówi.', E'Przygotował i przeprowadził poselstwo na temat prawdy biblijnej, którą tam odkrył.', E'Zaplanował całodniowy czyn społeczny dla swojej lokalnej społeczności, np. akcję sprzątania w parku, kiermasz sąsiedzki, sprzątanie strychu itp. Uzyskał zgodę odpowiedniej władzy lokalnej. Zaangażował do tego min. pięć osób.', E'Wykonał samodzielnie coś pożytecznego dla społeczności, w której mieszka lub się uczy.', E'Zebrał wnioski i opinie od osób uczestniczących w realizacji zadań, przedstawił wyniki i podzielił się świadectwem z zadań na zbiórce, w społeczności itp.']::text[]),
  (E'wedrownicy-sluzba-innym-pomocnik-w-szczepie', E'wedrownicy', E'duchowy', E'sluzba-innym', E'Służba innym', E'Pomocnik W Szczepie', ARRAY[E'Samodzielnie przestudiował fragment Rzym. 12:3-5. Przygotował i przeprowadził poselstwo na temat prawdy biblijnej z tego fragmentu. Porozmawiał z komendantem szczepu na temat konkretnych potrzeb w szczepie.', E'Biorąc pod uwagę obdarowanie i talenty osób, podjął się odpowiedzialnej służby przez min. trzy miesiące i zaangażował do tego min. dwie osoby, np. redagował aktualności na stronę szczepową, zajmował się inwentaryzacją magazynu, był pomocnikiem przybocznego w młodszym zastępie, zrobił archiwum zdjęć szczepowych itp.', E'Samodzielnie, po ustaleniu z komendantem, wykonał na rzecz szczepu zadanie, którego nikt nie chciał lub nie miał czasu zrobić.', E'Zebrał wnioski i opinie od osób uczestniczących w realizacji zadań, przedstawił wyniki i podzielił się świadectwem z zadań na zbiórce, w społeczności itp.']::text[]),
  (E'wedrownicy-sluzba-innym-sanitariusz', E'wedrownicy', E'duchowy', E'sluzba-innym', E'Służba innym', E'Sanitariusz', ARRAY[E'Samodzielnie przestudiował fragment Łuk. 10:30-37. Zastanowił się, co wie na temat opatrywania ran i ustalił, jak pogłębić swoją wiedzę i umiejętności w tym zakresie. Przygotował i przeprowadził poselstwo wykorzystując jako rekwizyt element z apteczki.', E'Prawidłowo postąpił w przypadku: krwotoku z kończyny, stłuczenia, zaprószenia oka, omdlenia, odmrożenia, oparzenia. Przyłożył okład, zabandażował kilkoma sposobami kończyny, głowę, tułów. Przeprowadził na zbiórce zajęcia z samarytanki. Pełnił służbę samarytańską na pięciu zbiórkach lub biwaku.', E'Wie, jak postąpić przy udrażnianiu dróg oddechowych, unieruchomieniu kończyn. Wie, jak wykonać sztuczne oddychanie i zewnętrzny masaż serca. Zrobił na zbiórce prezentacje i ćwiczenia na manekinie.', E'Zebrał wnioski i opinie od osób uczestniczących w realizacji zadań. Spisał wnioski na przyszłość i podzielił się nimi z liderem.']::text[]),
  (E'wedrownicy-sluzba-w-kosciele-aniol-stroz', E'wedrownicy', E'duchowy', E'sluzba-w-kosciele', E'Służba w kościele', E'Anioł Stróż', ARRAY[E'Przemyślał werset z Przyp. 3:27. Znalazł osoby potrzebujące ze swojego kościoła. Modlił się o mądrość w tej sprawie - jak może tym osobom pomóc?', E'Znalazł osobę, którą w tajemnicy wspierał przez min. trzy miesiące (w modlitwie, dawaniu, niespodziankach, dobrym słowem w listach itp.)', E'Z zespołem kilku skautów podjął się systematycznej pomocy osobie potrzebującej z kościoła bez zdradzania swoich tożsamości.', E'Złożył świadectwo na zbiórce zastępu, jak wpłynęło na niego wykonane zadanie i jakie ma przemyślenia na przyszłość.']::text[]),
  (E'wedrownicy-sluzba-w-kosciele-moja-sluzba', E'wedrownicy', E'duchowy', E'sluzba-w-kosciele', E'Służba w kościele', E'Moja Służba', ARRAY[E'Przemyślał werset I Piotr 4:10. Modlił się, aby odkryć dar, którym mógłby usługiwać w kościele. Porozmawiał o tym z liderem lub Rodzicami.', E'Podjął się służby w kościele na min. trzy miesiące i sumiennie ją wykonywał. Opowiedział o niej na zbiórce.', E'Zorganizował z zespołem 2-3 osób służbę na rzecz kościoła.', E'Zebrał wnioski i opinie od osób uczestniczących w zorganizowanej służbie. Spisał wnioski na przyszłość i podzielił się nimi z liderami kościoła/wspólnoty.']::text[]),
  (E'wedrownicy-sluzba-w-kosciele-my', E'wedrownicy', E'duchowy', E'sluzba-w-kosciele', E'Służba w kościele', E'My', ARRAY[E'Wyszukał wszystkie fragmenty z Księgi Przypowieści Salomona, mówiące o przyjaźni i w modlitwie zastanowił się, jak wyglądają jego przyjaźnie z osobami z kościoła. Porozmawiał o tym z mentorem.', E'Dbał o relację, przez pół roku spotykając się min. raz na dwa tygodnie z przyjacielem z kościoła i wspólnie spędzając czas.', E'Zaproponował i zorganizował wspólny wyjazd dla grupy 3-4 przyjaciół z kościoła.', E'Zebrał wnioski i opinie od przyjaciół z kościoła, jak chcieliby rozwijać swoje relacje. Spisał wnioski na przyszłość i wspólnie ustalili, co zrobią przez najbliższy rok.']::text[]),
  (E'wedrownicy-sluzba-w-kosciele-powolanie', E'wedrownicy', E'duchowy', E'sluzba-w-kosciele', E'Służba w kościele', E'Powołanie', ARRAY[E'Samodzielnie przestudiował fragment I Tym. 3:1-13. Porozmawiał z mentorem na temat powołania do służby w kościele i kwalifikacji, jakie powinien spełniać kandydat do służby.', E'Odbył min. trzy spotkania z duchownym z kościoła/wspólnoty. Rozmawiali na temat odkrywania swojego powołania w życiu, służbie, rodzinie, pracy itp.', E'Zaprosił duchownego z kościoła/wspólnoty na biwak, gdzie wspólnie rozmawiali przy ognisku o swoich potrzebach i planach.', E'Poprowadził na zbiórce zastępu/biwaku temat odkrywania powołania, zapraszając do tego osobę, która wypełnia swoje powołania.']::text[]),
  (E'wedrownicy-spoleczenstwo-animator-regionu', E'wedrownicy', E'spoleczny', E'spoleczenstwo', E'Społeczeństwo', E'Animator Regionu', ARRAY[E'Zaplanował i przygotował imprezę szczepową dotyczącą regionu.', E'Zna problematykę swojego regionu, jego atuty i słabości - opowiedział o tym na zbiórce.', E'Brał udział w świętach regionalnych, aktywnie działał na rzecz regionu, promował go.', E'Przygotował i zrealizował z zespołem 2-3-osobowym zbiórkę dotyczącą regionu dla młodszego zastępu.\nUwagi: można realizować w 2-3 osoby']::text[]),
  (E'wedrownicy-spoleczenstwo-ekolog', E'wedrownicy', E'spoleczny', E'spoleczenstwo', E'Społeczeństwo', E'Ekolog', ARRAY[E'Jest członkiem organizacji ekologicznej.', E'Wziął udział w akcji ekologicznej o zasięgu min. województwa, regionu.', E'W zespole 2-3-osobowym przygotował i przeprowadził szczepową akcję ekologiczną.', E'Przygotował i poprowadził zbiórkę ekologiczną dla młodszego zastępu.']::text[]),
  (E'wedrownicy-spoleczenstwo-europejczyk', E'wedrownicy', E'spoleczny', E'spoleczenstwo', E'Społeczeństwo', E'Europejczyk', ARRAY[E'Zaplanował zbiórkę tematyczną dotyczącą problematyki europejskiej lub uczestniczył w wymianie międzynarodowej.', E'Zna historię Europy, Unii Europejskiej. Potrafi wskazać jej plusy i minusy, umie porównać nacjonalizm, patriotyzm i kosmopolityzm.', E'Jest otwartą osobą, uczy się języków obcych, koresponduje z rówieśnikami z Europy, modli się o władze unijne.', E'Zrealizował zbiórkę tematyczną o Europie lub podzielił się wrażeniami i wnioskami z wymiany międzynarodowej.']::text[]),
  (E'wedrownicy-spoleczenstwo-wolontariusz', E'wedrownicy', E'spoleczny', E'spoleczenstwo', E'Społeczeństwo', E'Wolontariusz', ARRAY[E'Brał udział w ogólnopolskiej akcji charytatywnej.', E'Zna zasady wolontariatu. Podpisał umowę wolontariacką i wykonywał określone w niej prace.', E'Aktywnie i regularnie działał w instytucji prowadzącej charytatywną działalność.', E'Przygotował i poprowadził akcję charytatywną lub pomocy sąsiedzkiej z młodszym zastępem.']::text[]),
  (E'wedrownicy-spoleczenstwo-zawodowiec', E'wedrownicy', E'spoleczny', E'spoleczenstwo', E'Społeczeństwo', E'Zawodowiec', ARRAY[E'Przeszkolił się i wykonywał konkretną pracę zarobkową (min. 40 godzin pracy w ciągu dwóch miesięcy). Przedstawił/opowiedział na zbiórce o efektach swojej pracy.', E'Wie, jak zdobywa się wykształcenie zawodowe, umie wymienić kolejne etapy edukacji, potrafi przekazać tę wiedzę, napisał swoje CV i list motywacyjny.', E'Zdobył informacje na temat kształcenia zawodowego w swoim regionie, potrafi się tą wiedzą dzielić, zna swoje atuty i potrafi wskazać na swoje „ścieżkę kariery zawodowej”.', E'W swojej grupie rówieśniczej przygotował i zrealizował akcję związaną z doradztwem zawodowym.']::text[]),
  (E'wedrownicy-sport-graj-ze-mna', E'wedrownicy', E'fizyczny', E'sport', E'Sport', E'Graj Ze Mną', ARRAY[E'Wziął udział w min. trzech turniejach gier sportowych.', E'Brał udział w turnieju/zawodach jako sędzia.', E'Nauczył zastęp grać w min. trzy nowe gry.', E'Razem z zastępem zorganizował zawody drużyn w sporcie nieolimpijskim.']::text[]),
  (E'wedrownicy-sport-lodolamacz', E'wedrownicy', E'fizyczny', E'sport', E'Sport', E'Lodołamacz', ARRAY[E'Wziął udział w min. trzech turniejach w sportach zimowych.', E'Systematycznie doskonali swoje umiejętności w klubie lub na zajęciach dodatkowych.', E'Był odpowiedzialny za zimowy sprzęt sportowy na biwaku/obozie.', E'Zaproponował i zorganizował dla zastępu zajęcia sportowe na obozie zimowym (min. pięć dni).']::text[]),
  (E'wedrownicy-sport-organizator-sportu', E'wedrownicy', E'fizyczny', E'sport', E'Sport', E'Organizator Sportu', ARRAY[E'Przestudiował fragment I Kor. 9:24-27. Zastanowił się, jakie są korzyści z uprawiania sportu. Zweryfikował swoje motywacje do uprawiania sportu i porozmawiał o nich z liderem. Przygotował i przeprowadził poselstwo wykorzystując jako temat coś z uprawianej przez siebie dyscypliny sportu.', E'Jest zawodnikiem klubu sportowego od min. trzech lat. Brał udział w wydarzeniu sportowym: turniej, rozgrywki o zasięgu wojewódzkim lub ogólnopolskim.', E'Zorganizował rozgrywki szczepowe, osiedlowe lub turniej międzyszczepowy. Zaangażował do tego min. dwie osoby. Podczas rozgrywek poprowadził samodzielnie zespół.', E'Zebrał wnioski i opinie od osób uczestniczących w realizacji zadań, przedstawił wyniki i podzielił się świadectwem na ten temat na zbiórce, w społeczności itp.']::text[]),
  (E'wedrownicy-sport-ratownik', E'wedrownicy', E'fizyczny', E'sport', E'Sport', E'Ratownik', ARRAY[E'Zdobył patent Młodszego Ratownika.', E'Pomagał ratownikowi na kąpielisku lub basenie.', E'Pokierował przygotowaniem kąpieliska na obozie/biwaku.', E'Przeprowadził na obozie/biwaku cykl zajęć z nauki pływania i BHP z zastępem.']::text[]),
  (E'wedrownicy-szczep-braterstwo', E'wedrownicy', E'spoleczny', E'szczep', E'Szczep', E'Braterstwo', ARRAY[E'Zaprojektował, przygotował imprezę szczepową.', E'Zna strukturę i historię swojego szczepu oraz organizacji RR Polska oraz zna i bardzo dobrze opanował ceremoniał szczepowy.', E'Aktywnie bierze udział w życiu szczepu, współtworzył co najmniej trzy imprezy szczepowe.', E'Zorganizował imprezę szczepową.\nUwagi: można realizować w 2-3 osoby']::text[]),
  (E'wedrownicy-szczep-gawedziarz', E'wedrownicy', E'spoleczny', E'szczep', E'Szczep', E'Gawędziarz', ARRAY[E'W szczepie był odpowiedzialnym i aktywnym kronikarzem szczepu. Prowadził w dowolnej formie kronikę szczepu.', E'Zna strukturę i historię swojego szczepu, organizacji RR, harmonogram imprez szczepowych i ogólnopolskich.', E'Zachęcił innych do przyłączenia się do RR, zrealizował projekt na rozpowszechnianie idei skautingu, aktywnie działał na rzecz integracji w szczepie.', E'Wyszukuje i gromadzi w dowolnej formie ciekawe gawędy. Wygłosił w szczepie na zbiórkach lub ogniskach min. trzy gawędy.']::text[]),
  (E'wedrownicy-szczep-mistrz-polowy', E'wedrownicy', E'spoleczny', E'szczep', E'Szczep', E'Mistrz Polowy', ARRAY[E'Pełnił funkcję pomocnika oboźnego imprezy szczepowej typu biwak/obóz.', E'Zna ceremoniał skautowy, zasady ogólne, apel, sposób postępowania z proporcami i sztandarami.', E'Regularnie (przez min. pół roku) i godnie pełnił funkcje odpowiedzialne za ceremoniał/ obrzędowość szczepu. Wykonywał naprawy, dbał i przechowywał sztandar szczepu.', E'Poprowadził zajęcia dla młodszego zastępu na temat ceremoniału/obrzędowości szczepowej.']::text[]),
  (E'wedrownicy-szczep-skauting', E'wedrownicy', E'spoleczny', E'szczep', E'Szczep', E'Skauting', ARRAY[E'Zna pięć największych organizacji skautowych w Polsce, poznał ich Prawa i ich historie.', E'Utrzymuje kontakt/więzi z osobami z innej organizacji skautowej, uczestniczył w min. dwóch biegach, rajdach, na których były osoby z różnych organizacji skautowych.', E'Zorganizował harc dla szczepu z okazji Dnia Myśli Braterskiej mający na celu integrację różnych środowisk harcerskich.', E'W zespole 2-3-osobowym przygotował i przeprowadził akcję skautową, do współorganizacji zaprosił skautów z innej organizacji.']::text[]),
  (E'wedrownicy-szkola-grupa-rowiesnicza-aktywista', E'wedrownicy', E'spoleczny', E'szkola-grupa-rowiesnicza', E'Szkoła i grupa rówieśnicza', E'Aktywista', ARRAY[E'Był w samorządzie szkolnym lub reprezentował szkołę zaewnątrz w rozgrywkach sportowych, naukowych itp.', E'Zna historię swojej szkoły i jej patrona oraz poznał szkolny Statut.', E'Zna kalendarz imprez szkolnych - czynnie w nich uczestniczy i zachęca innych.', E'Zorganizował imprezę w szkole lub najbliższym środowisku (lub pełnił odpowiedzialną funkcję przy organizacji dużej imprezy).']::text[]),
  (E'wedrownicy-szkola-grupa-rowiesnicza-ambasador-rr', E'wedrownicy', E'spoleczny', E'szkola-grupa-rowiesnicza', E'Szkoła i grupa rówieśnicza', E'Ambasador RR', ARRAY[E'Reprezentował RR w miejskiej akcji typu uroczystość patriotyczna, gra miejska itp.', E'Zna harmonogram działania na dany rok i plan pracy w swoim szczepie. Zaprosił grupę znajomych na akcję organizowaną przez szczep. Pełnił rolę gospodarza na takiej akcji.', E'W zespole 2-3-osobowym zorganizował akcję skautową w nowym środowisku.', E'Zrealizował akcję naborową w szkole lub w swoim środowisku lub był odpowiedzialny za działanie szczepu w ramach dowolnej miejskiej akcji.']::text[]),
  (E'wedrownicy-szkola-grupa-rowiesnicza-przyjaciel', E'wedrownicy', E'spoleczny', E'szkola-grupa-rowiesnicza', E'Szkoła i grupa rówieśnicza', E'Przyjaciel', ARRAY[E'Ma pomysł na rozwój przyjaźni z wybraną osobą (wspólne hobby, sport itp.). Realizował go przez min. pół roku.', E'Pamięta o urodzinach swoich przyjaciół - składa im życzenia, daje upominki.', E'Zorganizował min. cztery spotkania w gronie przyjaciół.', E'Przygotował i przeprowadził cykl min. trzech gawęd na temat przyjaźni.']::text[]),
  (E'wedrownicy-technologia-kamerzysta', E'wedrownicy', E'intelektualny', E'technologia', E'Technologia', E'Kamerzysta', ARRAY[E'Poznał budowę, rodzaje i zasady działania kamer cyfrowych. Rozróżnia elementy osprzętu kamerzysty. Zapoznał się z różnymi nośnikami obrazu.', E'Zna zasady tworzenia i obróbki filmów. Opanował podstawowe funkcje wybranego programu do tworzenia i edycji filmów.', E'Nakręcił film kamerą cyfrową według własnego scenariusza, obrobił go oraz zaprezentował publiczności.', E'Wziął udział w warsztatach lub przeczytał książkę dotyczącą produkcji filmu.']::text[]),
  (E'wedrownicy-technologia-programista', E'wedrownicy', E'intelektualny', E'technologia', E'Technologia', E'Programista', ARRAY[E'Wziął udział w kursie lub przeczytał książkę dotyczącą programowania.', E'Zna polecenia i składnię dowolnego współczesnego języka programowania.', E'Zainstalował na komputerze system operacyjny z rodziny Linux (np. Ubuntu).', E'Poprowadził zajęcia z podstaw programowania dla kogoś młodszego.']::text[]),
  (E'wedrownicy-technologia-technolog', E'wedrownicy', E'intelektualny', E'technologia', E'Technologia', E'Technolog', ARRAY[E'Opracował i przeprowadził w zastępie/drużynie proces wytworzenia narzędzia lub urządzenia przydatnego na obozie (np. łuk, strzała, wózek, oświetlenie namiotu, śledzie, sznur, krosna).', E'Spopularyzował (przedstawił) w szczepie lub szkole wybrane odkrycie lub wydarzenie naukowe, wyjątkowo ważne dla dziejów ludzkości.', E'Przygotował i przeprowadził z zespołem 2-3-osobowym zbiórkę dla młodszego zastępu pokazującą wybrany proces przetwarzania (np. papier czerpany, mydło, farbowanie).', E'Wyszukał i przedstawił na zbiórce ciekawe doświadczenie z termodynamiki.']::text[]),
  (E'wedrownicy-technologia-twardziel', E'wedrownicy', E'intelektualny', E'technologia', E'Technologia', E'Twardziel', ARRAY[E'Samodzielnie złożył zestaw komputerowy lub zmodernizował stary komputer wymieniając podzespoły na lepsze.', E'Zainstalował na komputerze system operacyjny oraz potrzebne oprogramowanie.', E'Zainstalował i skonfigurował klienta poczty elektronicznej.', E'Pełnił służbę opartą na wiedzy informatycznej, np. administrator stron www, serwisant sprzętu itp.']::text[]),
  (E'wedrownicy-terenoznawstwo-orientacja', E'wedrownicy', E'fizyczny', E'terenoznawstwo', E'Terenoznawstwo', E'Orientacja', ARRAY[E'Trafił do wyznaczonego miejsca w nieznanym terenie na podstawie szkicu lub mapy.', E'Odnalazł na mapie miejsce postoju, określił na tej podstawie odległość do wyznaczonego miejsca marszu, wykorzystując zasady określania odległości w terenie.', E'Dokonał pomiaru niedostępnych obiektów w terenie (wysokość drzewa, szerokość rzeki).', E'Z zespołem 2-3-osobowym zorganizował zawody na orientację.']::text[]),
  (E'wedrownicy-terenoznawstwo-synoptyk', E'wedrownicy', E'fizyczny', E'terenoznawstwo', E'Terenoznawstwo', E'Synoptyk', ARRAY[E'Po układzie chmur i innych zjawisk określił sytuację baryczną.', E'Rozpoznał moment przejścia frontu i podał przewidywany rozwój sytuacji meteorologicznej.', E'Wyjaśnił specjalistyczną (morską lub lotniczą) prognozę pogody; wie, jak do niej dotrzeć.', E'Prowadził codzienną obserwację meteorologiczną, dokonywał pomiarów, zapisywał wyniki co najmniej przez miesiąc.']::text[]),
  (E'wedrownicy-terenoznawstwo-topograf', E'wedrownicy', E'fizyczny', E'terenoznawstwo', E'Terenoznawstwo', E'Topograf', ARRAY[E'Wykonał szkic drogi z wykorzystaniem podziałki, znaków topograficznych, azymutów.', E'Trafił według mapy do odległego o kilka kilometrów obiektu, wykonując w czasie drogi szkic sytuacyjny terenu.', E'Wykonał szkic sytuacyjny terenu z punktu widokowego.', E'Przeszkolił młodszych z zakresu znajomości znaków patrolowych i topograficznych.']::text[]),
  (E'wedrownicy-terenoznawstwo-tropiciel', E'wedrownicy', E'fizyczny', E'terenoznawstwo', E'Terenoznawstwo', E'Tropiciel', ARRAY[E'Wytropił i obserwował zwierzynę (ssaki). Znalazł miejsca lęgowe ptaków. Opowiedział o tym na zbiórce.', E'Wykonał zdjęcia obserwowanych zwierząt, miejsc lęgowych, tropów. Zrobił odlew gipsowy tropów min. trzech zwierząt.', E'Wykonał raport z obserwacji zwierząt w lesie, opisując tryb życia, zachowania, pokarm itp.', E'Przygotował i przeprowadził zbiórkę w terenie z rozpoznawania tropów i śladów dla młodszego zastępu.']::text[]),
  (E'wedrownicy-wedrowka-krajoznawca', E'wedrownicy', E'fizyczny', E'wedrowka', E'Wędrówka', E'Krajoznawca', ARRAY[E'Oprowadził trzy wycieczki po swoim mieście (okolicy), wykazując się znajomością jego historii, zabytków i ciekawych obiektów.', E'Pokierował sporządzeniem informacji o walorach turystycznych okolicy na podstawie zajęć terenowych i literatury.', E'Zaplanował cykl wycieczek (min. trzy) do ciekawych miejsc historycznych, przyrodniczych, geograficznych, posługując się mapami i przewodnikami.', E'Uczestniczył w trzech wycieczkach krajoznawczych w różnych regionach Polski.']::text[]),
  (E'wedrownicy-wedrowka-rowerem-przez-polske', E'wedrownicy', E'fizyczny', E'wedrowka', E'Wędrówka', E'Rowerem Przez Polskę', ARRAY[E'Wziął udział w kilkudniowym obozie rowerowym po Polsce. W trakcie przejechał min. 150 km.', E'Zna zasady turystyki rowerowej - na zbiórce zastępu opowiedział o niej i zachęcił do zorganizowania wycieczki.', E'Opracował trasę wycieczki rowerowej dla młodszego zastępu. W trakcie wycieczki pomagał liderom i uczestnikom.', E'W zespole 2-3-osobowym pomógł młodszym skautom przygotować się do egzaminu na Kartę Rowerową.']::text[]),
  (E'wedrownicy-wedrowka-wedrowiec', E'wedrownicy', E'fizyczny', E'wedrowka', E'Wędrówka', E'Wędrowiec', ARRAY[E'Potrafi skompletować ekwipunek turystyczny na wędrówkę dla zastępu.', E'Zorganizował wycieczkę dla szczepu, potrafi skorzystać z rozkładu PKS, PKP, map, przewodników.', E'Ułożył preliminarz finansowy wycieczki oraz przedstawił rozliczenie.', E'Był współorganizatorem obozu wędrowniego. Podczas obozu wykazał się znajomością trasy i miejsc godnych odwiedzenia.']::text[]),
  (E'wedrownicy-wedrowka-zeglarz', E'wedrownicy', E'fizyczny', E'wedrowka', E'Wędrówka', E'Żeglarz', ARRAY[E'Zdobył patent żeglarza jachtowego.', E'Wziął udział w obozie żeglarskim.', E'Wziął udział w zbiórce na wodzie (kajaki, pontony, rowery wodne itp.) młodszego zastępu. W trakcie uczył zasad BHP na wodzie.', E'W zespole 2-3-osobowym zorganizował spływ kajakowy, pontonowy lub inny dla swojego zastępu.']::text[]),
  (E'zwiadowcy-alarm-musztra', E'zwiadowcy', E'fizyczny', E'alarm', E'Alarm', E'Musztra', ARRAY[E'Zapoznał się z Regulaminem Musztry RRP.', E'Nienagannie wydaje i wykonuje komendy.', E'Przeprowadził zajęcia z musztry z zastępem lub drużyną.', E'Brał udział w pokazie musztry zastępu lub drużyny.']::text[]),
  (E'zwiadowcy-alarm-sygnalista', E'zwiadowcy', E'fizyczny', E'alarm', E'Alarm', E'Sygnalista', ARRAY[E'Poznał alfabet Morse\'a. Pełnił funkcję sygnalisty na biwaku, obozie.', E'Opracował system sygnałów dla swojego zastępu. Sygnały wykorzystał na podchodach, zwiadzie, biwaku itp.', E'Potrafi się porozumiewać za pomocą alfabetu semaforowego. Zademonstrował to.', E'Przygotował dla zastępu grę z wykorzystaniem elementów sygnalizacji.']::text[]),
  (E'zwiadowcy-alarm-umiem-migac', E'zwiadowcy', E'fizyczny', E'alarm', E'Alarm', E'Umiem Migać', ARRAY[E'Nauczył się 100 migów z języka dla niesłyszących.', E'Nauczył się alfabetu migowego i umie się nim posługiwać.', E'Poprowadził na zbiórce zajęcia z języka migowego i nauczył zastęp 30 migów.', E'Spotkał się z osobą głuchoniemą i nawiązał z nią kontakt za pomocą języka migowego.']::text[]),
  (E'zwiadowcy-biblia-arka-noego', E'zwiadowcy', E'duchowy', E'biblia', E'Biblia', E'Arka Noego', ARRAY[E'Przeczytał I Mojż. 7-8. Zastanowił się, co wie na temat biblijnego potopu.', E'Znalazł film chrześcijański i literaturę na temat dowodów na prawdziwość istnienia biblijnego potopu i Arki Noego. Zaproponował zastępowi obejrzenie filmu na ten temat.', E'Przedstawił na zbiórce prezentację ciekawostki przyrodniczej, która potwierdza biblijny potop.', E'Wyjaśnił na zbiórce zastępu, jakie zmiany nastąpiły w przyrodzie na skutek potopu.']::text[]),
  (E'zwiadowcy-biblia-historie-biblijne', E'zwiadowcy', E'duchowy', E'biblia', E'Biblia', E'Historie Biblijne', ARRAY[E'Przeczytał historię Jozjasza z II Król. 22-23. Zastanowił się, jak Jozjasz traktował Boże Słowo. Porozmawiał o tym z liderem lub Rodzicami.', E'Przeszedł kurs biblijny (w kościele lub przez Internet).', E'Wziął udział w quizie/turnieju z zakresu wiedzy biblijnej.', E'Opowiedział na zbiórce, czym dla niego jest Biblia i jaki wpływ ma na jego życie to, co jest w niej zapisane.']::text[]),
  (E'zwiadowcy-biblia-historycznosc-biblii', E'zwiadowcy', E'duchowy', E'biblia', E'Biblia', E'Historyczność Biblii', ARRAY[E'Przeczytał fragment z Łuk. 3:1-2. Dowiedział się, kim były osoby tam wymienione i opowiedział o nich na zbiórce.', E'Wie, co znaczy słowo „Biblia”, jak powstała, ile ksiąg zawiera i jak jest podzielona. Dowiedział się, jak nazywa się najstarsze tłumaczenie Biblii w języku polskim.', E'Opowiedział na zbiórce, jak i kiedy powstał kanon Starego i Nowego Testamentu.', E'Przeczytał książkę historyczną o jakiejś osobie lub wydarzeniu mającym miejsce w Biblii. Opowiedział o nim na zbiórce.']::text[]),
  (E'zwiadowcy-biblia-przypowiesci', E'zwiadowcy', E'duchowy', E'biblia', E'Biblia', E'Przypowieści', ARRAY[E'Przeczytał wszystkie przypowieści Jezusa z wybranej Ewangelii, wybrał ulubioną i porozmawiał o niej z Rodzicami lub liderem.', E'Nauczył się opowiadać pięć przypowieści, których użył Jezus. Potrafi wytłumaczyć, o czym one mówią.', E'Przeczytał i przemyślał Przyp. 17-27. Nauczył się na pamięć 10 wybranych wersetów.', E'Wraz ze swoim zastępem przygotował dla młodszego zastępu scenkę/teatrzyk, przedstawiające jedną z przypowieści Jezusa i wytłumaczył własnymi słowami, czego ta przypowieść dotyczyła.']::text[]),
  (E'zwiadowcy-czytelnictwo-moj-autor', E'zwiadowcy', E'intelektualny', E'czytelnictwo', E'Czytelnictwo', E'Mój Autor', ARRAY[E'Ma swojego ulubionego autora, przeczytał min. trzy jego książki.', E'Zapoznał się z biografią ulubionego autora.', E'Zrobił spis książek ulubionego autora i systematycznie dąży do przeczytania wszystkich.', E'Zaprosił zastęp do obejrzenia ekranizacji książki ulubionego autora lub zrobił ciekawą prezentację na jego temat.']::text[]),
  (E'zwiadowcy-czytelnictwo-mol-ksiazkowy', E'zwiadowcy', E'intelektualny', E'czytelnictwo', E'Czytelnictwo', E'Mól Książkowy', ARRAY[E'Lubi czytać książki i robi to systematycznie.', E'Wziął udział w konkursie pięknego czytania.', E'Zadbał o higienę czytania. Przygotował wyciszone i dobrze oświetlone miejsce do czytania, z którego regularnie korzystał.', E'Wykonywał regularnie pięć ćwiczeń poszerzających pole widzenia.']::text[]),
  (E'zwiadowcy-czytelnictwo-nowy-testament', E'zwiadowcy', E'intelektualny', E'czytelnictwo', E'Czytelnictwo', E'Nowy Testament', ARRAY[E'Przeczytał cały Nowy Testament.', E'Systematycznie od miesiąca czyta Nowy Testament (jeden rozdział dziennie).', E'Potrafi wymienić wszystkie Księgi Nowego Testamentu.', E'Ma ulubionego bohatera z Nowego Testamentu - opowiedział o nim na zbiórce zastępu.']::text[]),
  (E'zwiadowcy-czytelnictwo-przyjaciel-ksiazki', E'zwiadowcy', E'intelektualny', E'czytelnictwo', E'Czytelnictwo', E'Przyjaciel Książki', ARRAY[E'Systematycznie czyta książki. Zgromadził biblioteczkę ulubionych lektur/autorów.', E'Brał udział w konkursie czytelniczym organizowanym w szkole lub drużynie.', E'Wykonał drobne naprawy kilku książek (okładka, zakładka, podklejenie).', E'Pomagał w bibliotece (porządkował katalogi, układał książki itp.).']::text[]),
  (E'zwiadowcy-harce-gra-fabularna', E'zwiadowcy', E'spoleczny', E'harce', E'Harce', E'Gra Fabularna', ARRAY[E'Stworzył scenariusz dowolnej gry terenowej/fabularnej, trwającej co najmniej godzinę i dostosował go do warunków okolicy.', E'Zapoznał się z zasadami dwóch/trzech gier fabularnych.', E'Aktywnie uczestniczy w grach terenowych. Aktywizuje grupę w tym obszarze. Wziął udział jako uczestnik w co najmniej jednej grze terenowej.', E'Stworzoną przez siebie grę zorganizował (przy pomocy instruktora) z udziałem co najmniej 10 osób. Zdał sprawozdanie. Wyciągnął wnioski na przyszłość (plusy i minusy scenariusza gry).']::text[]),
  (E'zwiadowcy-harce-harcownik', E'zwiadowcy', E'spoleczny', E'harce', E'Harce', E'Harcownik', ARRAY[E'Wymyślił lub wyszukał i zaadaptował na własne potrzeby zestaw gier niekonwencjonalnych, powiązanych tematycznie w np. turniej.', E'Wie, czym są gry niekonwencjonalne, rozumie i umie wytłumaczyć, jak można powiązać tematycznie grę z myślą przewodnią imprezy zastępowej.', E'Brał udział jako uczestnik w co najmniej jednym turnieju gier niekonwencjonalnych.', E'Wykonał rekwizyty do zestawu gier niekonwencjonalnych, zaprezentował je w zastępie, zaprosił do wspólnej gry/zabawy/rywalizacji. Wyciągnął wnioski na przyszłość (plusy i minusy scenariusza gry).']::text[]),
  (E'zwiadowcy-harce-mors', E'zwiadowcy', E'spoleczny', E'harce', E'Harce', E'Mors', ARRAY[E'Wymyślił lub wyszukał, np. w Internecie i zaadaptował na własne potrzeby trzy gry/zabawy w warunkach zimowych, mające na celu integrację.', E'Rozumie, czym jest integracja i dlaczego jest istotna w życiu skauta. Potrafi to uzasadnić.', E'Brał udział w zimowisku lub innej formie spotkania zimowego, w którym aktywnie uczestniczył. Brał udział w zabawach integracyjnych, aktywizując grupę. Przygotował i nauczył zastęp lub inne osoby trzech zimowych gier/zabaw integracyjnych.', E'Zaprosił do wspólnej gry/zabawy/rywalizacji. Wyciągnął wnioski na przyszłość (plusy i minusy scenariuszy gier).']::text[]),
  (E'zwiadowcy-harce-zabawy-ruchowe', E'zwiadowcy', E'spoleczny', E'harce', E'Harce', E'Zabawy Ruchowe', ARRAY[E'Wymyślił pląs związany z nazwą zastępu lub imprezą zastępową, np. wymyślił rymowankę i układ ruchów pod istniejącą melodię.', E'Rozumie, czym są pląsy i jakie mają znaczenie dla obrzędowości zastępu, poznaje nowe pląsy. Prowadzi własny notatnik, zawierający zbiór pląsów do wykorzystania na zbiórkach.', E'Sam umie i uczy chętnie inne osoby pląsów, zaprezentował co najmniej pięć wyuczonych na pamięć pląsów.', E'Nauczył zastęp wymyślonego przez siebie pląsu obrzędowego lub związanego z jakąś imprezą zastępową, chętnie uczestniczy w zabawach z pląsami, aktywizuje grupę w tym obszarze.']::text[]),
  (E'zwiadowcy-historia-drzewo-genealogiczne', E'zwiadowcy', E'intelektualny', E'historia', E'Historia', E'Drzewo Genealogiczne', ARRAY[E'Stworzył min. pięciopokoleniowe drzewo genealogiczne z uwzględnieniem dat i miejsc urodzin.', E'Uporządkował rodzinne albumy, opisał zdjęcia.', E'Przygotował w formie prezentacji gawędę na temat „Rodzinny bohater”, „Ta historia zdarzyła się w naszej rodzinie” itp.', E'Współorganizował i uczestniczył w szczególnej rodzinnej imprezie lub wycieczce do ważnych dla rodziny miejsc.']::text[]),
  (E'zwiadowcy-historia-folklor', E'zwiadowcy', E'intelektualny', E'historia', E'Historia', E'Folklor', ARRAY[E'Wziął udział w imprezie folklorystycznej, gdzie dowiedział się o tradycjach z przeszłości.', E'Wziął udział w zabawach lub warsztatach ze sztuki ludowej. Przedstawił na zbiórce to, co zrobił lub opowiedział, w czym brał udział.', E'Wie, jak wygląda strój ludowy z jego regionu. Zna jeden taniec ludowy oraz potrafi wymienić kilka słów gwary ludowej.', E'Wziął udział w przygotowaniu zbiórki, na której był pokazywany folklor własnego regionu.']::text[]),
  (E'zwiadowcy-historia-historyk-skautingu', E'zwiadowcy', E'intelektualny', E'historia', E'Historia', E'Historyk Skautingu', ARRAY[E'Zna symbolikę skautowej lilijki i koniczynki, wie, jak wyglądają i jaka jest ich historia.', E'Wie, kiedy powstał skauting i kto go założył. Zna początki harcerstwa i RR w Polsce.', E'Poznał życiorysy twórców skautingu, harcerstwa i RR. Opowiedział o jednym z nich na zbiórce zastępu.', E'Przygotował i przeprowadził ciekawą prezentację i quiz dla młodszego zastępu na temat Bi-Pi i skautingu.']::text[]),
  (E'zwiadowcy-historia-patriota', E'zwiadowcy', E'intelektualny', E'historia', E'Historia', E'Patriota', ARRAY[E'Zna historię flagi i godła polskiego. Potrafi zaśpiewać z pamięci cały „Mazurek Dąbrowskiego”.', E'Opowiedział w ciekawy sposób na zbiórce zastępu o jednym ważnym dla Polski historycznym wydarzeniu (Odsiecz Wiedeńska, Bitwa pod Grunwaldem, Cud nad Wisłą, Obrona Westerplatte itp.).', E'Zna wszystkich polskich noblistów. Potrafi w kilku zdaniach o każdym z nich coś powiedzieć.', E'Zorganizował w zastępie/drużynie obchody jednego ze świąt narodowych, nawiązując w wieczernicy, grze lub biegu do wydarzeń z dawnych lat.']::text[]),
  (E'zwiadowcy-logika-mistrz-lamiglowek', E'zwiadowcy', E'intelektualny', E'logika', E'Logika', E'Mistrz Łamigłówek', ARRAY[E'Zna zasady rozwiązywania kakuro.', E'Zna zasady i potrafi grać w co najmniej pięć dwuosobowych gier logicznych (Warcaby, Szachy, Abalone, Pentago, Link 4 (Connect 4), Pylos, Inside, Quixo, Backgammon, Rój, Quarto, Gobblet).', E'Rozwiązał samodzielnie 20 łamigłówek kakuro.', E'Zachęcił do rozwiązywania i nauczył rozwiązywać kakuro kolegów w zastępie.']::text[]),
  (E'zwiadowcy-logika-strateg', E'zwiadowcy', E'intelektualny', E'logika', E'Logika', E'Strateg', ARRAY[E'Zna zasady gry i potrafi grać w co najmniej 10 złożonych gier planszowych (strategiczne bądź ekonomiczne: Osadnicy z Catanu, Carcassonne, Monopoly itp.).', E'Wziął grę na biwak/obóz i zachęcił zastęp do gry w wolnym czasie.', E'Ma w domu spis wszystkich gier planszowych. Systematycznie w nie gra i wymienia się nimi z innymi osobami.', E'Nauczył zastęp grać w jedną strategiczną grę karcianą.']::text[]),
  (E'zwiadowcy-logika-szach-mat', E'zwiadowcy', E'intelektualny', E'logika', E'Logika', E'Szach Mat', ARRAY[E'Wykazał się znajomością zasad gry w szachy: znajomością figur, ich ruchów i wartości. Orientuje się, kto obecnie jest w czołówce najlepszych szachistów świata.', E'Brał udział w pięciu turniejach szachowych, organizowanych przez kluby szachowe lub inne organizacje.', E'Pomógł w organizacji turnieju szachowego dla drużyny/szczepu.', E'Zachęcił do gry w szachy osoby z zastępu, wytłumaczył zasady gry i pokazał, jak w nią grać.']::text[]),
  (E'zwiadowcy-logika-udowodnie', E'zwiadowcy', E'intelektualny', E'logika', E'Logika', E'Udowodnię', ARRAY[E'Wyjaśnił zastępowi, dlaczego dyskusja jest dobrym sposobem rozwiązywania konfliktów.', E'Wziął udział w dyskusji na jakiś temat. Wyjaśnił swój punkt widzenia na podstawie przytoczonych faktów, opinii i badań.', E'Doprowadził do kompromisu strony mające różne interesy. Przedstawił rozwiązanie oraz argumenty potwierdzające korzyści dla obu stron.', E'Przeprowadził dla zastępu debatę na temat istotny dla uczestników. Debatę podsumował i wyciągnął wnioski.']::text[]),
  (E'zwiadowcy-misja-bog-dziala', E'zwiadowcy', E'duchowy', E'misja', E'Misja', E'Bóg Działa', ARRAY[E'Przeczytał i rozważył fragment z Jan 5:15-17. Zastanowił się, w jaki sposób Bóg działa dzisiaj.', E'Przeczytał książkę będącą świadectwem, jak Bóg wciąż działa na Ziemi. Opowiedział o niej na zbiórce i zachęcił innych do jej przeczytania.', E'Opowiedział na zbiórce świadectwo z Bożego działania w jego życiu/w jego rodzinie.', E'Wziął udział w spotkaniu, na którym wierzący dzielili się świadectwami, w jaki sposób Bóg działa w ich życiu.']::text[]),
  (E'zwiadowcy-misja-ewangelista', E'zwiadowcy', E'duchowy', E'misja', E'Misja', E'Ewangelista', ARRAY[E'Zna na pamięć wersety, które mówią o drodze człowieka do Boga (np. „droga rzymska”: Rzym. 3:23; 6:23; 5:8; 10:9; 10:13; 5:1; 8:1; 8:38-39).', E'Przeczytał biografię znanego ewangelisty czasów nowożytnych i opowiedział o nim na zbiórce.', E'Brał udział w ewangelizacji jako duchowy doradca.', E'Przygotował i powiedział poselstwo na temat potrzeby osobistego nowonarodzenia.']::text[]),
  (E'zwiadowcy-misja-owoce', E'zwiadowcy', E'duchowy', E'misja', E'Misja', E'Owoce', ARRAY[E'Nauczył się na pamięć wersetu Gal. 5:22. Porozmawiał z Rodzicem lub liderem, jakie owoce wydaje w swoim życiu.', E'Wymyślił i zrealizował dwa zadania, dzięki którym objawił się w jego życiu mało widoczny owoc Ducha.', E'Wziął udział w spotkaniu, na którym omawiano fragment Gal. 5:24-26. Zrobił notatki na temat: „Jak żyć według Ducha?”.', E'Przygotował i powiedział poselstwo na temat jednego z owoców Ducha.']::text[]),
  (E'zwiadowcy-misja-wierzacy-kto-to-taki', E'zwiadowcy', E'duchowy', E'misja', E'Misja', E'Wierzący - Kto To Taki?', ARRAY[E'Przeczytał fragmenty Rzym. 10:17 i I Kor. 2:4-5. Porozmawiał z liderem lub Rodzicem na temat wiary - skąd się bierze i na czym się opiera?', E'Zaproponował w domu rozmowę na temat fragmentu z Jan 13:34-35. W trakcie rozmowy spisał wnioski - w jaki sposób będą okazywać sobie miłość?', E'Na spotkaniu kilku osób powiedział, że jest chrześcijaninem i co to znaczy.', E'Opowiedział na zbiórce o pięciu cechach, które powinny charakteryzować chrześcijan poparł swoją wypowiedź cytatami z Biblii.']::text[]),
  (E'zwiadowcy-pasje-i-talenty-aktor', E'zwiadowcy', E'spoleczny', E'pasje-i-talenty', E'Pasje i talenty', E'Aktor', ARRAY[E'Uczestniczył w przedstawieniu teatralnym, opanował na pamięć swoje kwestie, przygotował się do roli pod kątem gry aktorskiej, charakteryzacji, kostiumu.', E'Zna historię teatru, ma ulubionych aktorów i reżyserów, potrafi o nich opowiedzieć, zna pojęcia sceniczne (np. kulisy, ekspresja sceniczna, improwizacja itp.).', E'Był w teatrze lub w innej formie obejrzał sztukę teatralną, zastanowił się nad przypowieścią Jezusa na temat talentów - czemu mogą służyć - po co są?', E'Zaprezentował na zbiórce sylwetkę ulubionego aktora, zachęcił inne osoby z zastępu do rozwijania swoich talentów.\nUwagi: można realizować w 2-3 osoby']::text[]),
  (E'zwiadowcy-pasje-i-talenty-kolekcjoner', E'zwiadowcy', E'spoleczny', E'pasje-i-talenty', E'Pasje i talenty', E'Kolekcjoner', ARRAY[E'Przygotował prezentację swojego hobby na lekcji w szkole lub zbiórce.', E'Rozwija swoją wiedzę na temat pasji, którą się zajmuje.', E'Skatalogował swoją kolekcję.', E'Zorganizował prezentację swojego hobby na lekcji w szkole lub zbiórce, zachęcił inne osoby z zastępu do rozwijania swoich talentów.']::text[]),
  (E'zwiadowcy-pasje-i-talenty-malarz', E'zwiadowcy', E'spoleczny', E'pasje-i-talenty', E'Pasje i talenty', E'Malarz', ARRAY[E'Od dłuższego czasu zajmuje się sztukami plastycznymi, podnosi swoje umiejętności - zorganizował wystawę swoich prac dla zastępu lub klasy.', E'Pogłębia wiedzę związaną z uprawianą przez siebie techniką plastyczną.', E'Uczestniczy w zajęciach kółka plastycznego lub w innej formie rozwija swój talent - zastanowił się nad przypowieścią Jezusa na temat talentów - czemu mogą służyć - po co są?', E'Zaprosił na wystawę swoich prac, wykonał zaproszenia, plakaty, przygotował ekspozycję, zachęcił inne osoby z zastępu do rozwijania swoich talentów.']::text[]),
  (E'zwiadowcy-pasje-i-talenty-muzykant', E'zwiadowcy', E'spoleczny', E'pasje-i-talenty', E'Pasje i talenty', E'Muzykant', ARRAY[E'Brał udział jako uczestnik (w chórze, w orkiestre) w dowolnym koncercie.', E'Ma swoich mistrzów, zna ich biografię i twórczość.', E'Uczestniczy w zajęciach kółka/szkółki muzycznej, próbach chóru itp., regularnie rozwija swój talent - zastanowił się nad przypowieścią Jezusa na temat talentów - czemu mogą służyć - po co są?', E'W zastępie gra na instrumencie lub jest odpowiedzialny za prowadzenie śpiewnika, inicjuje i zachęca do śpiewania.']::text[]),
  (E'zwiadowcy-pasje-i-talenty-przyjaciel-zwierzat', E'zwiadowcy', E'spoleczny', E'pasje-i-talenty', E'Pasje i talenty', E'Przyjaciel Zwierząt', ARRAY[E'Opiekuje się zwierzątkiem, lubi zwierzęta.', E'Dowiedział się, jakich warunków do rozwoju wymaga jego podopieczny, wzbogaca swoją wiedzę przyrodniczą. Potrafi wymienić np. zwierzęta chronione w Polsce lub wie, jakie dziko żyjące zwierzęta mieszkają w jego okolicy, rozpoznaje gatunki ptaków itp.', E'Jest odpowiedzialny za swoje zwierzątko, jeździ z nim do weterynarza, kupuje jedzenie, samodzielnie po nim sprząta.', E'Zorganizował akcję charytatywną na rzecz schroniska lub akcję dokarmiania zwierząt leśnych zimą, lub na zbiórce pokazał jak wykonać prosty karmik dla ptaków.']::text[]),
  (E'zwiadowcy-pasje-i-talenty-rzemieslnik', E'zwiadowcy', E'spoleczny', E'pasje-i-talenty', E'Pasje i talenty', E'Rzemieślnik', ARRAY[E'Od dłuższego czasu zajmuje się wybraną dziedziną rękodzielniczą, przygotował scenariusz warsztatów dla zastępu z nauką wybranej techniki (kosztorys, potrzebne narzędzia itp.).', E'Stale poszerza wiedzę na temat danej formy rękodzielniczej, korzysta z filmów instruktażowych, warsztatów itp.', E'Gromadzi książki, czasopisma, wzory do inspiracji, wyznaczył sobie następny poziom rozwoju, zastanowił się nad przypowieścią Jezusa na temat talentów - czemu mogą służyć - po co są?', E'Zrealizował warsztaty dla zastępu z nauką wybranej techniki, zachęcił inne osoby z zastępu do rozwijania swoich talentów.']::text[]),
  (E'zwiadowcy-pasje-i-talenty-tancerz', E'zwiadowcy', E'spoleczny', E'pasje-i-talenty', E'Pasje i talenty', E'Tancerz', ARRAY[E'Przygotował układ choreograficzny do wybranego utworu muzycznego.', E'Interesuje się różnymi formami tańca, obejrzał dowolne przedstawienie taneczne.', E'Chodzi na zajęcia taneczne lub sam korzystając z Internetu uczy się regularnie w domu wybranego tańca.', E'Zrealizował minipokaz dla dowolnej grupy, na zbiórce zdał sprawozdanie, zachęcił inne osoby z zastępu do rozwijania swoich talentów.']::text[]),
  (E'zwiadowcy-pionierka-kucharz', E'zwiadowcy', E'fizyczny', E'pionierka', E'Pionierka', E'Kucharz', ARRAY[E'Zapoznał się z zasadami higieny i bezpieczeństwa podczas służby w kuchni. Przestrzega ich.', E'Opracował menu na biwak i uzyskał zatwierdzenie od przybocznego lub Rodziców. Menu powinno być zaplanowane zgodnie z zasadami zdrowego odżywiania.', E'Przygotował w terenie posiłek dla zastępu, korzystając z kuchni polowej lub turystycznej.', E'Wie, jak przechowywać żywność w domu, na biwaku, na obozie.']::text[]),
  (E'zwiadowcy-pionierka-ognisko', E'zwiadowcy', E'fizyczny', E'pionierka', E'Pionierka', E'Ognisko', ARRAY[E'Nauczył się rozpoznawać różne gatunki drewna, dowiedział się, czym się charakteryzują i jak się palą.', E'Zastosował w praktyce przynajmniej trzy różne rodzaje ognisk, np. piramidę, wigwam i gwiazdę.', E'Nauczył się zdobywać drewno i rozpałkę przy deszczowej pogodzie.', E'Razem z 2-3 osobami był odpowiedzialny na biwaku za podtrzymywanie ognia.']::text[]),
  (E'zwiadowcy-pionierka-wezly', E'zwiadowcy', E'fizyczny', E'pionierka', E'Pionierka', E'Węzły', ARRAY[E'Nauczył się rozpoznawać i wiązać 10 węzłów i użył ich na zbiórkach czy biwaku.', E'Zna pięć rodzajów stoperów. Umie je zastosować.', E'Zna trzy sposoby zwijania lin. Umie je zastosować.', E'Nauczył zastęp jednego ciekawego węzła. Zademonstrował, gdzie można go użyć.']::text[]),
  (E'zwiadowcy-pionierka-wyga-obozowy', E'zwiadowcy', E'fizyczny', E'pionierka', E'Pionierka', E'Wyga Obozowy', ARRAY[E'Był przynajmniej na czterech obozach, w tym na dwóch pod namiotem. Skompletował swój osobisty sprzęt obozowy/biwakowy: plecak, menażkę, niezbędnik, latarkę, karimatę i śpiwór.', E'Samodzielnie zbudował: pryczę, stojak na plecak i półkę obozową.', E'Razem z zastępem zorganizowali podstawowy sprzęt biwakowy zastępu: narzędzia, namiot, sprzęt kuchenny, apteczkę. Zadbali o transport tego sprzętu na biwak.', E'Zbudował z zastępem budowle obozowe/biwakowe: plac pracy, umywalnię, kuchnię, zadaszenie i latrynę.']::text[]),
  (E'zwiadowcy-poboznosc-dzien-swiety', E'zwiadowcy', E'duchowy', E'poboznosc', E'Pobożność', E'Dzień Święty', ARRAY[E'Przeczytał fragment I Mojż. 2:1-3. Zastanowił się, jak powinno się odpoczywać siódmego dnia. Dowiedział się, dlaczego chrześcijanie odpoczywają w niedzielę.', E'Przez trzy miesiące odpoczywał w niedziele. Wszystkie prace i obowiązki wykonywał w tygodniu.', E'W trakcie trzech miesięcy robił notatki z kazań niedzielnych w swoim kościele. W domu czytał i rozważał wersety, które były czytane na nabożeństwach.', E'Podzielił się na zbiórce zastępu wnioskami z okresu, kiedy nie wykonywał żadnej pracy w niedziele.']::text[]),
  (E'zwiadowcy-poboznosc-nie-jest-mi-obojetne', E'zwiadowcy', E'duchowy', E'poboznosc', E'Pobożność', E'Nie Jest Mi Obojętne', ARRAY[E'Przeczytał fragment I Tym. 4:12-16. Zastanowił się, jak sam może rozwijać się duchowo.', E'Wymyślił i zrealizował miesięczny plan samorozwoju duchowego. Wnioskami podzielił się z liderem/Rodzicem.', E'Przez trzy miesiące robił notatki z kazań w kościele i rozważał, co Bóg chciałby przez te kazania mu powiedzieć osobiście.', E'Pomógł przeprowadzić zajęcia na lekcji religii/w szkole niedzielnej. Wykonał konkretną pracę i opowiedział o tym na zbiórce.']::text[]),
  (E'zwiadowcy-poboznosc-ofiarnosc', E'zwiadowcy', E'duchowy', E'poboznosc', E'Pobożność', E'Ofiarność', ARRAY[E'Przeczytał fragment II Kor. 9:5-9. Zastanowił się, jak wyglądają biblijne motywacje dawcy.', E'W modlitwie podjął decyzję, kogo i w jaki sposób pobłogosławi jakimś darem.', E'Przez pięć tygodni z rzędu ofiarowywał coś komuś w tajemnicy. Opowiedział o tym tylko liderowi bądź Rodzicom.', E'Przez pół roku zbierał środki finansowe i ofiarował je na określony cel dobroczynny. Dowiedział się, czym jest biblijna jałmużna i opowiedział o tym na zbiórce.']::text[]),
  (E'zwiadowcy-poboznosc-post', E'zwiadowcy', E'duchowy', E'poboznosc', E'Pobożność', E'Post', ARRAY[E'Przeczytał fragmenty: Mat. 6:16-18 i Izaj. 58:1-12. Zastanowił się, jakimi zasadami powinien się kierować chrześcijanin w trakcie postu i porozmawiał o tym z Rodzicem lub liderem. Dowiedział się, co post wnosi do chrześcijańskiego życia i jakie są formy postu.', E'Systematycznie przez miesiąc pościł raz w tygodniu i modlił się w konkretnej intencji.', E'Przez miesiąc świadomie rezygnował z jednej rzeczy (słodycze, telewizja, komputer itp.), a zaoszczędzony czas poświęcał na relację z Bogiem: modlitwę, czytanie i studium Biblii.', E'Opowiedział na zbiórce zastępu, czym jest post i opowiedział o swoim czasie postu.']::text[]),
  (E'zwiadowcy-poznawanie-swiata-bylem-tam', E'zwiadowcy', E'intelektualny', E'poznawanie-swiata', E'Poznawanie świata', E'Byłem Tam', ARRAY[E'Był na wycieczce/wakacjach w innym kraju. Zrobił prezentację i opowiedział (pokazał zdjęcia, pamiątki) na zbiórce o ciekawych miejscach, które zobaczył.', E'Przygotował trasę wycieczki zagranicznej do pięciu miast w innym kraju. Spisał miejsca warte zobaczenia w tym mieście. Na zbiórce ciekawie opowiedział o tych miejscach.', E'Wie, gdzie się znajdują i jaka jest stolica wszystkich krajów na świecie, rozpoznaje ich flagi.', E'Był w co najmniej trzech krajach obcych w Europie. Opowiedział na zbiórce/w szkole ciekawe historie, zwyczaje, miejsca, które zobaczył i o których usłyszał w tych krajach.']::text[]),
  (E'zwiadowcy-poznawanie-swiata-jezykoznawca', E'zwiadowcy', E'intelektualny', E'poznawanie-swiata', E'Poznawanie świata', E'Językoznawca', ARRAY[E'Uczy się języka obcego od min. trzech lat i miał przez te lata ocenę bardzo dobrą lub celującą.', E'Systematycznie koresponduje ze skautem z innego kraju w obcym języku.', E'Na obozie międzynarodowym porozumiał się w obcym języku w sprawach życia codziennego.', E'Wziął udział w olimpiadzie z języka obcego na szczeblu międzyszkolnym.']::text[]),
  (E'zwiadowcy-poznawanie-swiata-przyrodnik', E'zwiadowcy', E'intelektualny', E'poznawanie-swiata', E'Poznawanie świata', E'Przyrodnik', ARRAY[E'Był z zastępem na wycieczce lub wystawie o tematyce przyrodniczej.', E'Ma ulubiony gatunek/rodzaj zwierząt lub roślin. Systematycznie poszerza swoją wiedzę i zbiera ciekawe materiały na ich temat. Pokazał je na zbiórce i w ciekawy sposób opowiedział o nich.', E'Przedstawił na zbiórce trzy wybrane gatunki zwierząt występujących na świecie, zagrożonych wyginięciem („czerwona księga”).', E'Odwiedził ZOO i Ogród Botaniczny na wiosnę i jesienią. Opowiedział na zbiórce, co się zmieniło w czasie pomiędzy wizytami.']::text[]),
  (E'zwiadowcy-poznawanie-swiata-reporter', E'zwiadowcy', E'intelektualny', E'poznawanie-swiata', E'Poznawanie świata', E'Reporter', ARRAY[E'Przygotował min. trzy rzeczowe relacje z biwaku, wycieczki, obozu lub innej imprezy skautowej/szkolnej. Zaprezentował je w prasie lub na stronie www.', E'Posługiwał się sprzętem reporterskim (magnetofon, aparat, kamera) w przygotowaniu reportażu z imprezy.', E'Napisał reportaże na wybrany i zadany temat, ilustrując je rysunkami lub zdjęciami. Przedstawił je na zbiórce zastępu.', E'Był komentatorem na wydarzeniu sportowym lub prowadzącym quiz, wieczór talentów lub inne wydarzenie z dużą publicznością.']::text[]),
  (E'zwiadowcy-poznawanie-swiata-znam-innych', E'zwiadowcy', E'intelektualny', E'poznawanie-swiata', E'Poznawanie świata', E'Znam Innych', ARRAY[E'Zna główne odłamy chrześcijaństwa. Potrafi je wymienić i krótko scharakteryzować.', E'Dowiedział się, czym się charakteryzuje ruch charyzmatyczny i w jakich odłamach chrześcijaństwa ma miejsce.', E'Poznał osobę uczęszczającą do innego kościoła chrześcijańskiego. Dowiedział się, jak w jego kościele przebiega nabożeństwo.', E'Poznał i ciekawie opowiedział na zbiórce o wybranym wyznaniu chrześcijańskim.']::text[]),
  (E'zwiadowcy-puszczanstwo-ognik', E'zwiadowcy', E'fizyczny', E'puszczanstwo', E'Puszczaństwo', E'Ognik', ARRAY[E'Rozpalił ognisko za pomocą krzesiwa i krzemienia.', E'Przeniósł ogień z miejsca na miejsce oddalone o dwa kilometry, używając hubki.', E'Rozpalił i dbał o ognisko przy namiocie/szałasie, dające mieszkańcom ciepło w nocy.', E'Poznał sposoby gaszenia ognia w terenie bez sprzętu gaśniczego.']::text[]),
  (E'zwiadowcy-puszczanstwo-przetrwac-w-zimie', E'zwiadowcy', E'fizyczny', E'puszczanstwo', E'Puszczaństwo', E'Przetrwać W Zimie', ARRAY[E'Był z zastępem na jednodniowej wycieczce zimowej po opadach śniegu. Wziął udział w tropieniu zwierząt na śniegu.', E'Wie, jak pomóc osobie przemarzniętej, przemoczonej. Ma własną folię termiczną i potrafi jej użyć.', E'Zbudował własną jamę śnieżną i spędził w niej trzy godziny. Zna zasady budowania schronień w zimie.', E'Przygotował podczas zimowej wycieczki ciepły posiłek.']::text[]),
  (E'zwiadowcy-puszczanstwo-sobieradek', E'zwiadowcy', E'fizyczny', E'puszczanstwo', E'Puszczaństwo', E'Sobieradek', ARRAY[E'Z zastępem zbudował szałas, w którym nocował.', E'W pracach pionierskich umiejętnie posługiwał się nożem, toporkiem, piłą, młotkiem. Zna zasady ich konserwacji i przechowywania.', E'Zaprojektował i wykonał drobny przedmiot pionierki obozowej (ławeczkę, drogowskaz, kosz na śmieci itp.).', E'Z zastępem zaprojektował i zbudował miejsce biwakowe: sypialnię, kuchnię, umywalnię, toaletę, plac pracy.']::text[]),
  (E'zwiadowcy-puszczanstwo-zbieracz', E'zwiadowcy', E'fizyczny', E'puszczanstwo', E'Puszczaństwo', E'Zbieracz', ARRAY[E'Był na grzybobraniu. Rozpoznaje min. 10 gatunków grzybów jadalnych.', E'Przygotował informację o 10 wybranych roślinach zielarskich oraz pięciu roślinach trujących, występujących w Polsce i przedstawił je na zbiórce zastępu.', E'Zna co najmniej 10 roślin jadalnych występujących dziko w naturze.', E'Zrobił pięć przetworów z darów natury. Opowiedział o tym na zbiórce i poczęstował efektami swojej pracy.']::text[]),
  (E'zwiadowcy-rodzina-dzien-z-dziadkami', E'zwiadowcy', E'spoleczny', E'rodzina', E'Rodzina', E'Dzień Z Dziadkami', ARRAY[E'Zaplanował dzień z Dziadkami tak, by móc ich jeszcze lepiej poznać. Plan zrealizował.', E'Rozumie trudności wynikające z wieku osób starszych, wie jak i chętnie pomaga osobom starszym.', E'Nauczył się wybranego wersetu z Biblii na temat sędziwego wieku (np. Przyp. 16:31; III Mojż. 19:32). Zastanowił się, co oznaczają te słowa.', E'Wykonał wraz z zastępem akcję na rzecz ludzi starszych (Dzień Babci/Dziadka, odwiedziny w domu opieki społecznej, wieczernicę z piosenkami starszego pokolenia, akcję niewidzialnej ręki itp.).']::text[]),
  (E'zwiadowcy-rodzina-jednodniowy-biwak', E'zwiadowcy', E'spoleczny', E'rodzina', E'Rodzina', E'Jednodniowy Biwak', ARRAY[E'Zaplanował jednodniowy biwak, wycieczkę rodzinną, w czasie której rodzina będzie miała okazję spędzić ze sobą czas. Plan zrealizował.', E'Rozpoznał w swoim zachowaniu obszar, w którym jest nieposłuszny Rodzicom (np. stosunek do szkoły, porządek, higiena osobista, relacje z rodzeństwem czy w grupie rówieśniczej). Zaplanował, jak się w tym wybranym aspekcie poprawić.', E'Nauczył się wybranego wersetu z Biblii na temat posłuszeństwa Rodzicom. Przez miesiąc starał się zrealizować plan poprawy w obszarze posłuszeństwa.', E'Zdał sprawozdanie na zbiórce z zaplanowanego rodzinnego wypadu, z uwzględnieniem pozytywów wynikających z takiej formy spędzenia czasu.']::text[]),
  (E'zwiadowcy-rodzina-poznajmy-sie', E'zwiadowcy', E'spoleczny', E'rodzina', E'Rodzina', E'Poznajmy Się', ARRAY[E'Stworzył „siatkę” najbliższej rodziny. Skontaktował się z nimi poprzez spotkania, rozmowy telefoniczne, maile itp.', E'Przeprowadził wywiady z członkami rodziny. Spisał ciekawe rodzinne historie (rodzinny bohater, wyjątkowe wydarzenie itp.). Zdobył maksymalnie dużo informacji na te tematy.', E'Współorganizował i uczestniczył w rodzinnej wycieczce do miejsc ważnych dla rodziny.', E'Zaprezentował w czasie rodzinnego spotkania prezentację, np. „Rodzinny bohater”, „Ta historia zdarzyła się w naszej rodzinie” itp.']::text[]),
  (E'zwiadowcy-rodzina-starszy-brat-starsza-siostra', E'zwiadowcy', E'spoleczny', E'rodzina', E'Rodzina', E'Starszy Brat Starsza Siostra', ARRAY[E'Zaplanował, w jaki sposób może pomóc swojemu rodzeństwu lub „adopcyjnemu” rodzeństwu (jeżeli jest jedynakiem lub najmłodszym członkiem rodziny, może pomagać wybranemu dziecku ze szkoły, kościoła) - zrealizował plan w ciągu miesiąca.', E'Zapoznał się z biblijną i świecką formą pomagania sobie nawzajem – dowiedział się, czym jest wolontariat.', E'Stara się być pomocny w grupie rówieśniczej - nauczył się wybranego wersetu z Biblii na temat miłości braterskiej.', E'Zdał sprawozdanie na zbiórce ze swej działalności - zachęcił inne osoby do akcji „Starszy brat, starsza siostra”.']::text[]),
  (E'zwiadowcy-samodyscyplina-chwat', E'zwiadowcy', E'duchowy', E'samodyscyplina', E'Samodyscyplina', E'Chwat', ARRAY[E'Słowo „chwat” jest złożone z pierwszych liter następujących cech charakteru: C-cnota (postępowanie zgodne z zasadami moralnymi), H-hart (wytrwałość wobec przeciwności losu), W-wola (siła woli, umiejętność konsekwentnego dążenia do celu), A-altruizm (poświęcanie swoich talentów na rzecz innych), T-tężyzna (ćwiczenie sprawnego i wytrzymałego ciała i ducha).', E'Opracował zadania, dla każdej litery po jednym, które pomogły mu rozwinąć te cechy (powinny to być zadania realizowane specjalnie na potrzeby tej sprawności, nie powtarzające się przy zdobywaniu innych sprawności i stopnia).', E'Przedstawił zadania liderowi lub Rodzicowi, którzy motywowali go podczas wykonywania zadań. Poszczególne zadania omówił w trakcie realizacji.', E'Po zakończeniu próby opowiedział świadectwo na zbiórce/biwaku, w jaki sposób Bóg pomagał mu w realizacji zadań.']::text[]),
  (E'zwiadowcy-samodyscyplina-co-mowie', E'zwiadowcy', E'duchowy', E'samodyscyplina', E'Samodyscyplina', E'Co Mówię', ARRAY[E'Nauczył się na pamięć wersetu Efez. 4:27. Zastanowił się, co może zrobić, aby żyć w zgodzie z tym wersetem.', E'Ma sprecyzowane zasady wyrażania się - nie przeklina i mówi o tym innym. Przestrzega tych zasad.', E'Rozmawiał z Rodzicami lub liderem, jakie konsekwencje niesie kłamstwo. Jest prawdomówny.', E'Opowiedział na zbiórce budującą historię, jak radzi sobie wśród rówieśników z czystością języka.']::text[]),
  (E'zwiadowcy-samodyscyplina-modlitwa-w-rodzinie', E'zwiadowcy', E'duchowy', E'samodyscyplina', E'Samodyscyplina', E'Modlitwa W Rodzinie', ARRAY[E'Przeczytał fragment Dz. 1:13-14. Zastanowił się, co jest szczególnego we wspólnej modlitwie. Dowiedział się, jaka jest obietnica dla tych, którzy uzgodnią swoje prośby przed Bogiem.', E'Dowiedział się od kogoś z rodziny (dziadków, kuzynów itp.), o co mógłby się modlić i robił to systematycznie przez miesiąc.', E'Zrobił pisemną listę modlitewną całej rodziny i według tej listy proponował wspólne modlitwy. Spisywał świadectwa wysłuchanych modlitw.', E'Zaproponował wspólne rodzinne modlitwy wieczorne i min. dwa razy w tygodniu przez miesiąc prowadził te spotkania modlitewne.']::text[]),
  (E'zwiadowcy-samodyscyplina-rozwazanie', E'zwiadowcy', E'duchowy', E'samodyscyplina', E'Samodyscyplina', E'Rozważanie', ARRAY[E'Przez miesiąc codziennie czytał i rozważał jeden rozdział z księgi Przypowieści Salomona.', E'Codziennie notował ważne wskazówki dla siebie, znalezione w Biblii, które mogą mu pomóc w życiu chrześcijańskim.', E'Ukończył kurs biblijny dla dzieci w kościele bądź w Internecie.', E'Na podstawie rozważań biblijnych przygotował poselstwo i powiedział je na zbiórce.']::text[]),
  (E'zwiadowcy-samozaradnosc-bezpieczenstwo', E'zwiadowcy', E'intelektualny', E'samozaradnosc', E'Samozaradność', E'Bezpieczeństwo', ARRAY[E'Wziął udział w min. dwóch godzinnych zajęciach dotyczących 1 pomocy i BHP.', E'Wziął udział w zajęciach przeciwpożarowych.', E'Wie, jak się zachować w przypadku pożaru budynku, lasu, szkoły itp. Dowiedział się, jak wygląda sprzęt przeciwpożarowy stosowany na biwaku/obozie i jak się go używa.', E'Razem z zastępem przeprowadził ćwiczenia, zorganizował zawody przeciwpożarowe dla skautów.']::text[]),
  (E'zwiadowcy-samozaradnosc-dbam-o-siebie', E'zwiadowcy', E'intelektualny', E'samozaradnosc', E'Samozaradność', E'Dbam O Siebie', ARRAY[E'Ustalił z Rodzicami, jakie i kiedy powinien jeść śniadania i przestrzega tych ustaleń. Sam robi sobie drugie śniadania do szkoły.', E'Wybrał jeden sport, który uprawia systematycznie dwa razy w tygodniu (min. przez trzy miesiące).', E'Wziął udział w zajęciach dotyczących uzależnień. Wie, dlaczego mają negatywny wpływ na organizm.', E'Wskazał rówieśnikom korzyści płynące ze zdrowego stylu życia.']::text[]),
  (E'zwiadowcy-samozaradnosc-gospodarz', E'zwiadowcy', E'intelektualny', E'samozaradnosc', E'Samozaradność', E'Gospodarz', ARRAY[E'Przeczytał wersety: Ps. 24:1; I Tym. 6:8; I Piotr 3:3-4 i w modlitwie rozważył, jakie ma motywacje do posiadania różnych rzeczy. Porozmawiał o tym z liderem/Rodzicem i ustalił, jak powinien traktować rzeczy, które posiada.', E'Z pomocą osoby dorosłej ustalił i realizował zasady i plan: dawania, wydawania i oszczędzania przez min. sześć miesięcy. Zrobił inwentaryzację swoich rzeczy, ustalił, co jest jego potrzebą, co życzeniem, a co zachcianką.', E'Brał udział w przygotowaniu i przeprowadzeniu akcji zarobkowej zastępu.', E'Razem z liderem podsumował akcję zarobkową, a z Rodzicem sześć miesięcy zrealizowanego planu finansowego.']::text[]),
  (E'zwiadowcy-samozaradnosc-majsterkowicz', E'zwiadowcy', E'intelektualny', E'samozaradnosc', E'Samozaradność', E'Majsterkowicz', ARRAY[E'Skompletował dla siebie zestaw 10 podstawowych narzędzi do majsterkowania. Potrafi się nimi bezpiecznie posługiwać.', E'Poznał i nauczył się bezpiecznie używać pięciu elektronarzędzi (szlifierka, wiertarka, lutownica, wyrzynarka, wypalarka, ładowarka itp.).', E'W zespole 2- 3-osobowym zaprojektował i wykonał z surowych elementów drewnianych i metalowych (arkusz blachy i płyta sklejki) skarbiec zastępu. Poszczególne etapy prac udokumentował zdjęciami.', E'Wykonał prosty użytkowy przedmiot do domu: półkę, wieszak, skrzynkę i pokazał w zastępie. Dokonał dwóch drobnych napraw w domu.']::text[]),
  (E'zwiadowcy-samozaradnosc-pracownik', E'zwiadowcy', E'intelektualny', E'samozaradnosc', E'Samozaradność', E'Pracownik', ARRAY[E'Przeczytał wersety: II Tes. 3:7-12 i w modlitwie rozważył, czy jest dobrym świadectwem w tej dziedzinie. Porozmawiał o tym z liderem/Rodzicem i ustalił, jaką pracę będzie wykonywał w domu.', E'Umówił się na wykonanie konkretnej płatnej pracy poza domem - co? za ile? jak? kiedy? (dla sąsiadów, znajomych, dziadków) i wykonał ją na ustalonych zasadach.', E'Spisał swoje obowiązki: domowe, szkolne, szczepowe itp. Ustalił swój tygodniowy plan, wpisując do niego czas na obowiązki, spotkania, relaks, hobby itp.', E'Przez okres trzech miesięcy starał się żyć zgodnie z tygodniowym planem, spisując, co zrealizował. Podsumował ten okres z Rodzicami i wspólnie spisali wnioski na przyszłość.']::text[]),
  (E'zwiadowcy-sluzba-innym-higienista', E'zwiadowcy', E'duchowy', E'sluzba-innym', E'Służba innym', E'Higienista', ARRAY[E'Przeczytał fragment Łuk. 10:30-37. Zastanowił się, co wie na temat opatrywania ran i jak pogłębić swoją wiedzę i umiejętności w tym zakresie. Wziął udział w zbiórce na temat samarytanki i pierwszej pomocy.', E'Poznał zasady kompletowania apteczki i skompletował apteczkę zastępu. Zaradził na zbiórkach w prostych przypadkach skaleczenia, stłuczenia, krwotoku z nosa, ukąszenia przez owady. Zmierzył temperaturę choremu i ustalił, czy jest właściwa.', E'Zabezpieczył się na biwaku przed udarem, odwodnieniem i odparzeniem nóg lub przed przeziębieniem i odmrożeniem na zimowisku. Opowiedział innym, jak się to robi.', E'Był odpowiedzialny za apteczkę zastępu przez pięć zbiórek. Pokazał i wyjaśnił zastępowi, do czego służą rzeczy w apteczce zastępu.']::text[]),
  (E'zwiadowcy-sluzba-innym-pomoc-sasiedzka', E'zwiadowcy', E'duchowy', E'sluzba-innym', E'Służba innym', E'Pomoc Sąsiedzka', ARRAY[E'Przeczytał werset Przyp. 27:10. W modlitwie odebrał, co dla niego może oznaczać ten werset. Porozmawiał z Rodzicami, w jaki sposób mógłby się stać lepszym sąsiadem. Ustalił z Rodzicami, z kim z sąsiedztwa się zapozna i co dla niego zrobi.', E'Codziennie przez tydzień lub raz w tygodniu przez miesiąc modlił się o sąsiada i pomagał mu w jakiejś pracy.', E'Po wykonanej pracy dla sąsiada lub w trakcie porozmawiał z nim i nawiązywał relację.', E'Opowiedział zastępowi, jak pomagał sąsiadowi i jaka była jego reakcja.']::text[]),
  (E'zwiadowcy-sluzba-innym-pomocna-dlon', E'zwiadowcy', E'duchowy', E'sluzba-innym', E'Służba innym', E'Pomocna Dłoń', ARRAY[E'Przeczytał werset I Tym. 1:8. W modlitwie odebrał, w jaki sposób może u siebie w domu realizować biblijną prawdę z tego wersetu. Wnioskami podzielił się z Rodzicami lub liderem.', E'Na podstawie biblijnej prawdy ustalił systematyczne zadanie, które wykonywał przez min. miesiąc, np. opiekował się młodszym rodzeństwem przez 8 h tygodniowo, wyręczał inną osobę w domowych obowiązkach.', E'Zrealizował samodzielnie okazjonalne zadanie w domu, wykazując się odpowiedzialnością, np. opiekował się chorym domownikiem (podawał posiłki, lekarstwa, umilał czas), pomagał Rodzicom w organizacji rodzinnego wydarzenia (remont, uroczystość).', E'Podsumował swoje zadania i opisał, jak mu poszło. O wnioskach porozmawiał z liderem lub Rodzicami. Ustalił plan zadań na przyszłość - jak chciałby zadbać o domowników z własnej woli?']::text[]),
  (E'zwiadowcy-sluzba-innym-pomocnik-przybocznego', E'zwiadowcy', E'duchowy', E'sluzba-innym', E'Służba innym', E'Pomocnik Przybocznego', ARRAY[E'Przeczytał II Mojż. 18 i w modlitwie rozważał, dlaczego Mojżesz potrzebował wielu liderów i jak to się przekłada na szczep. Dowiedział się, jakie są zadania zastępowego i podzastępowego. Porozmawiał z przybocznym i ustalił, w jaki sposób mógłby pomóc w pracach zastępu lub szczepu.', E'Systematycznie (min. na czterech zbiorkach) wykonywał zadanie ustalone z przybocznym.', E'Samodzielnie wymyślił i wykonał zadanie, przez które pomógł w służbie jakiemuś liderowi w szczepie.', E'Opowiedział w zastępie jakąś biblijną historię o przywódcy, który najpierw komuś pomagał w służbie i podzielił się swoim doświadczeniem, jak pomagał w szczepie.']::text[]),
  (E'zwiadowcy-sluzba-w-kosciele-duchowni', E'zwiadowcy', E'duchowy', E'sluzba-w-kosciele', E'Służba w kościele', E'Duchowni', ARRAY[E'Zrobił charakterystykę Apostoła Pawła na podstawie lektury Nowego Testamentu. Wypisał wersety z życia Apostoła i opisał, jakim był człowiekiem.', E'Zaprosił duchownego z kościoła/wspólnoty na zbiórkę, biwak, akcję skautową i był gościnny.', E'Razem z 2-3 osobami pomógł duchownemu w jakiejś akcji kościelnej.', E'Zaprosił duchownego z kościoła/wspólnoty na zbiórkę i poprosił o złożenie świadectwa z jego życia z młodości.']::text[]),
  (E'zwiadowcy-sluzba-w-kosciele-niewidzialna-reka', E'zwiadowcy', E'duchowy', E'sluzba-w-kosciele', E'Służba w kościele', E'Niewidzialna Ręka', ARRAY[E'Przeczytał fragment Mat. 6:1-6. Zastanowił się, komu może w tajemnicy pomóc. O wnioskach porozmawiał z Rodzicami lub liderem.', E'Podarował w tajemnicy swoją cenną rzecz osobie potrzebującej z kościoła.', E'Przez okres miesiąca systematycznie pomagał komuś z kościoła, w tajemnicy wykonując za niego jakąś pracę.', E'Z zastępem przygotował i zrobił komuś ze swojego kościoła niespodziankę bez ujawniania, kto to zrobił.']::text[]),
  (E'zwiadowcy-sluzba-w-kosciele-pomocnik-w-kosciele', E'zwiadowcy', E'duchowy', E'sluzba-w-kosciele', E'Służba w kościele', E'Pomocnik W Kościele', ARRAY[E'Przeczytał fragment I Tym 3:14-16. Zastanowił się, co wie na temat swojego kościoła i jak należy się w nim zachowywać. O wnioskach porozmawiał z Rodzicami lub liderem.', E'Zapoznał się ze służbami w swoim kościele – wie, ile ich jest i poznał liderów służb.', E'Wykonał pięć prac na rzecz kościoła.', E'Zaprezentował na zbiórce lub spotkaniu błogosławieństwa wynikające ze służby chrześcijańskiej.']::text[]),
  (E'zwiadowcy-sluzba-w-kosciele-razem', E'zwiadowcy', E'duchowy', E'sluzba-w-kosciele', E'Służba w kościele', E'Razem', ARRAY[E'Przeczytał historię Dawida i Jonatana z I Sam. 17-20 i opowiedział o niej przyjacielowi z kościoła.', E'W świadomy sposób zadbał o relację z przyjacielem z kościoła i spotykał się z nim systematycznie raz w tygodniu przez okres trzech miesięcy.', E'Spędził min. pięć dni wakacji z przyjacielem z kościoła.', E'Zaprezentował na zbiórce lub spotkaniu błogosławieństwa wynikające z przyjaźni.']::text[]),
  (E'zwiadowcy-spoleczenstwo-dobry-sasiad', E'zwiadowcy', E'spoleczny', E'spoleczenstwo', E'Społeczeństwo', E'Dobry Sąsiad', ARRAY[E'Na bazie rozpoznania potrzeb w sąsiedztwie zrealizował weekendową akcję pomocy sąsiedzkiej.', E'Zna zasady wolontariatu - wyjaśnił je na zbiórce.', E'Potrafi wymienić kilka organizacji charytatywnych w najbliższej okolicy - zaangażował się w jedną akcję charytatywną.', E'Zaplanował i zrealizował zespołową akcję pomocy sąsiedzkiej.']::text[]),
  (E'zwiadowcy-spoleczenstwo-gwara', E'zwiadowcy', E'spoleczny', E'spoleczenstwo', E'Społeczeństwo', E'Gwara', ARRAY[E'Zaplanował i przygotował zbiórkę tematyczną dotyczącą swojej małej ojczyzny: gwara, reportaż z muzeum etnograficznego, lokalne potrawy itp.', E'Wie, w jakim regionie mieszka, czym on się charakteryzuje i co jest stolicą regionu, zna słynne historyczne i współczesne postacie regionu.', E'Brał udział w świętach regionalnych, umie wymienić najważniejsze z nich.', E'Zrealizował zbiórkę tematyczną, dotyczącą: swojej małej ojczyzny, gwary, wyjścia do muzeum etnograficznego, znajomości lokalnych potraw itp.']::text[]),
  (E'zwiadowcy-spoleczenstwo-obywatel-rp', E'zwiadowcy', E'spoleczny', E'spoleczenstwo', E'Społeczeństwo', E'Obywatel RP', ARRAY[E'Zna historię swojego kraju, umie wymienić przedstawicieli władz państwowych, umie opowiedzieć, w jaki sposób w Polsce przeprowadzane są wybory.', E'Zaangażował się w przedsięwzięcie samorządowe, wykonał podczas niego samodzielne zadanie.', E'Wykazuje postawę patriotyczną na tle grupy rówieśniczej, modli się o władzę i kraj.', E'Przygotował i przeprowadził z zespołem 2-3-osobowym zbiórkę tematyczną związaną z świętem narodowym, historią Polski itp.']::text[]),
  (E'zwiadowcy-spoleczenstwo-specjalista', E'zwiadowcy', E'spoleczny', E'spoleczenstwo', E'Społeczeństwo', E'Specjalista', ARRAY[E'Przeprowadził wywiad z osobą wykonującą ciekawy i rzadki zawód.', E'Wie, jak zdobywa się wykształcenie zawodowe, umie wymienić kolejne etapy edukacji, potrafi przekazać tę wiedzę.', E'Poszukał informacji w Internecie na temat „zawodów przyszłości”.', E'Zaprezentował na zbiórce zdobyte informacje ze wskazaniem i uzasadnieniem, jakie zawody w przyszłości będą jego zdaniem szczególnie przydatne.']::text[]),
  (E'zwiadowcy-spoleczenstwo-zielona-sprawnosc', E'zwiadowcy', E'spoleczny', E'spoleczenstwo', E'Społeczeństwo', E'Zielona Sprawność', ARRAY[E'Przygotował i przeprowadził z zastępem akcję ekologiczną.', E'Zorganizował akcję odzyskiwania surowców wtórnych w swoim otoczeniu. Środki przeznaczył na cel ekologiczny.', E'Brał udział w akcji sadzenia lasów, odnowy parków, tworzenia przyrodniczych ścieżek edukacyjnych itp.', E'Przygotował i przedstawił prezentację o tematyce ekologicznej na lekcji/zbiórce.']::text[]),
  (E'zwiadowcy-sport-moj-sport', E'zwiadowcy', E'fizyczny', E'sport', E'Sport', E'Mój Sport', ARRAY[E'Systematycznie poznaje i gra w gry nieolimpijskie.', E'Zna zasady min. pięciu sportów indywidualnych.', E'Zorganizował turniej indywidualny na zbiórce lub biwaku.', E'Był na rozgrywkach nietypowego sportu i opowiedział o tym na zbiórce.']::text[]),
  (E'zwiadowcy-sport-moj-sport-wodny', E'zwiadowcy', E'fizyczny', E'sport', E'Sport', E'Mój Sport Wodny', ARRAY[E'Zdobył Kartę Pływacką.', E'Wziął udział w zawodach pływackich.', E'Nauczył się zasad bezpiecznej kąpieli i pierwszej pomocy - przeprowadził pogadankę w zastępie.', E'Systematycznie raz na tydzień chodzi na basen (przez min. pół roku).']::text[]),
  (E'zwiadowcy-sport-sport-na-zimowisku', E'zwiadowcy', E'fizyczny', E'sport', E'Sport', E'Sport Na Zimowisku', ARRAY[E'Ma swój zimowy sprzęt sportowy (narty, łyżwy lub sanki) i dba o niego.', E'Systematycznie (min. 10 razy w okresie zimy) uczestniczył w sporcie zimowym.', E'Był uczestnikiem turnieju, zawodów w sporcie zimowym.', E'Poprowadził zimowe zajęcia sportowe dla zastępu na obozie, biwaku.']::text[]),
  (E'zwiadowcy-sport-sportowiec', E'zwiadowcy', E'fizyczny', E'sport', E'Sport', E'Sportowiec', ARRAY[E'Przeczytał fragment I Kor. 9:24-25. Modlił się o to, jaka powinna być jego postawa na treningach i poza nimi. Od czego powinien się wstrzymywać, aby być dobrym sportowcem? Porozmawiał o tym z Rodzicem lub liderem.', E'Jest zawodnikiem klubu sportowego od min. roku. Brał udział w min. trzech wydarzeniach sportowych: turniej, rozgrywki.', E'Wytłumaczył osobom z zastępu i zademonstrował min. pięć elementów technicznych gry w tę dyscyplinę. Zorganizował rozgrywki dla zastępu i był na nich sędzią.', E'Podczas rozgrywek obozowych, drużynowych w tej dyscyplinie pełnił rolę trenera i podpowiadał grającym, co mają robić, aby odnieść sukces. Spostrzeżeniami z tego zadania podzielił się z liderem.']::text[]),
  (E'zwiadowcy-szczep-druh', E'zwiadowcy', E'spoleczny', E'szczep', E'Szczep', E'Druh', ARRAY[E'Włączył się w dowolną akcję między organizacjami skautowymi.', E'Poznał wybraną organizację skautową w najbliższej okolicy - opowiedział o niej na zbiórce.', E'Utrzymuje kontakt/więzi z osobami z innej organizacji skautowej.', E'Uczestniczył w Dniu Myśli Braterskiej lub Dniu Świętego Jerzego.']::text[]),
  (E'zwiadowcy-szczep-iskra', E'zwiadowcy', E'spoleczny', E'szczep', E'Szczep', E'Iskra', ARRAY[E'Zorganizował atrakcyjne dla uczestników wspólne spotkanie zastępu poza zbiórkami.', E'Z osobami z zastępu systematycznie spotyka się poza zbiórkami.', E'Aktywnie brał udział w życiu szczepu (wykonywał zlecone zadania na co najmniej trzech imprezach szczepowych).', E'Razem z zastępem zorganizował zbiórkę z innym zastępem. Współuczestniczył (miał zadanie i je wykonał samodzielnie) w organizacji tej zbiórki.']::text[]),
  (E'zwiadowcy-szczep-proporcowy', E'zwiadowcy', E'spoleczny', E'szczep', E'Szczep', E'Proporcowy', ARRAY[E'Był proporcowym zastępu przez okres min. pół roku. W trakcie opiekował się proporcem zastępu (przechowywał, dbał, naprawiał).', E'Poznał i umie zastosować ceremoniał postępowania z proporcami zastępów.', E'Godnie pełnił funkcję proporcowego w zastępie na biwaku lub obozie.', E'W dowolnej formie zebrał i opracował elementy obrzędowości swojego zastępu - wyniki pracy przedstawił na zbiórce zastępu.']::text[]),
  (E'zwiadowcy-szczep-w-kregu', E'zwiadowcy', E'spoleczny', E'szczep', E'Szczep', E'W Kręgu', ARRAY[E'W dowolnej formie prowadzi kronikę zastępu (blog, kronika, fanpage).', E'Zna strukturę i historię swojego szczepu.', E'Zachęcił dwie osoby do przyjścia na zbiórkę RR, ma pomysły na rozpowszechnianie idei skautingu.', E'Jest odpowiedzialnym, aktywnym członkiem zastępu, współtworzył min. pięć zbiórek przygotował zajęcia skautowe, poselstwo lub poprowadził część zbiórki.']::text[]),
  (E'zwiadowcy-szkola-grupa-rowiesnicza-kolega', E'zwiadowcy', E'spoleczny', E'szkola-grupa-rowiesnicza', E'Szkoła i grupa rówieśnicza', E'Kolega', ARRAY[E'Dba o dobre relacje w klasie/zastępie - podał przykład próby zintegrowania kolegi/koleżanki, który/która ma problemy z odnalezieniem się w grupie.', E'Zorganizował w domu spotkanie dla kilku osób z klasy.', E'Razem z kilkoma osobami z klasy zorganizował wspólną akcję (wycieczka rowerowa, wyjście do teatru, ZOO itp.)', E'Przygotował urodzinową niespodziankę dla wybranego kolegi/wybranej koleżanki.']::text[]),
  (E'zwiadowcy-szkola-grupa-rowiesnicza-reprezentant-rr', E'zwiadowcy', E'spoleczny', E'szkola-grupa-rowiesnicza', E'Szkoła i grupa rówieśnicza', E'Reprezentant RR', ARRAY[E'Na akcji szkolnej (wycieczka, apel itp.) wykazał się umiejętnością nabytą w RR.', E'Zaprezentował i uzasadnił swoją przynależność do organizacji RR wśród rówieśników. Opowiedział o tym na zbiórce.', E'Dba o mundur, w dniach mundurowych chodził w nim do szkoły, wykorzystuje każdą sposobność do prezentacji RR w szkole.', E'Współorganizował akcję naborową lub propagandową w szkole lub w swoim środowisku.']::text[]),
  (E'zwiadowcy-szkola-grupa-rowiesnicza-samorzadnie', E'zwiadowcy', E'spoleczny', E'szkola-grupa-rowiesnicza', E'Szkoła i grupa rówieśnicza', E'Samorządnie', ARRAY[E'Sumiennie wypełnia powierzone mu funkcje szkolne (samorząd uczniowski, reprezentacja sportowa itp.).', E'Poznał historię swojej szkoły.', E'Był na min. trzech imprezach szkolnych i o najciekawszej opowiedział na zbiórce.', E'Zorganizował (lub współuczestniczył w organizacji, wykonując określone zadania) imprezę o charakterze szkolnym.']::text[]),
  (E'zwiadowcy-technologia-doswiadczenia', E'zwiadowcy', E'intelektualny', E'technologia', E'Technologia', E'Doświadczenia', ARRAY[E'Wyszukał i sprawdził pięć domowych sposobów na usuwanie plam i zanieczyszczeń.', E'Zapoznał się z zanieczyszczeniami obecnymi w wodzie (biologiczne, chemiczne i mechaniczne) i sposobami jej uzdatniania. Skonstruował filtr i wypróbował go.', E'Pokazał na zbiórce samodzielnie sztucznie zabarwiony kwiat, uprzednio wyhodowany w domu.', E'Wyszukał i przedstawił na zbiórce ciekawe doświadczenie z kinematyki.']::text[]),
  (E'zwiadowcy-technologia-fotograf', E'zwiadowcy', E'intelektualny', E'technologia', E'Technologia', E'Fotograf', ARRAY[E'Poznał budowę, rodzaje i zasady działania aparatów fotograficznych (w tym analogowych). Rozróżnia elementy osprzętu fotograficznego.', E'Zna zasady robienia zdjęć: kadrowania, kompozycji, naświetlania itp. Zapoznał się z pracami znanego fotografa przyrody.', E'Opanował podstawowe funkcje obróbki zdjęć w programach użytkowych (np. GIMP, Picasa).', E'Systematycznie, przez trzy miesiące, fotografował życie zastępu. Opracował i przedstawił pamiątkowy album.']::text[]),
  (E'zwiadowcy-technologia-informatyk', E'zwiadowcy', E'intelektualny', E'technologia', E'Technologia', E'Informatyk', ARRAY[E'Zna polecenia i składnię dowolnego języka programowania.', E'Był na warsztatach z robotyki.', E'Stworzył grę zawierającą kilka poziomów i punktację. W kodzie korzystał z funkcji i modułów. Zaprezentował na zbiórce grę i wytłumaczył, co robi kod źródłowy, który napisał.']::text[]),
  (E'zwiadowcy-technologia-internauta', E'zwiadowcy', E'intelektualny', E'technologia', E'Technologia', E'Internauta', ARRAY[E'Znalazł w Internecie co najmniej trzy przydatne programy użytkowe w wersji darmowej. Zainstalował je i nauczył się z nich korzystać.', E'W stopniu podstawowym opanował obsługę trzech programów użytkowych (edytor tekstu, prezentacji, kalkulacyjny).', E'Założył swój własny adres poczty elektronicznej, przesyłał i odbierał e-maile.', E'Nauczył kolegę lub członka rodziny podstaw obsługi komputera.']::text[]),
  (E'zwiadowcy-terenoznawstwo-jodelka', E'zwiadowcy', E'fizyczny', E'terenoznawstwo', E'Terenoznawstwo', E'Jodełka', ARRAY[E'Doszedł do ustalonego celu, korzystając wyłącznie z jodełki (notatek do szkicu drogi z marszu).', E'Wykonał szkic terenu z miejsca.', E'Wykonał szkic terenu z podstawy.', E'Na biwaku, obozie wykonał z zastępem mapę najbliższego terenu na podstawie szkicu drogi z marszu (żmijki).']::text[]),
  (E'zwiadowcy-terenoznawstwo-mapa', E'zwiadowcy', E'fizyczny', E'terenoznawstwo', E'Terenoznawstwo', E'Mapa', ARRAY[E'Wie, do czego służy legenda na mapie i jak przeliczać odległości według podziałki.', E'Wyznaczył strony świata za pomocą słońca i gwiazd. Rozróżnił fazy księżyca. Wskazał najważniejsze gwiazdozbiory.', E'Wziął udział w biegu na orientację. Potrafi czytać mapę bez użycia legendy.', E'Wytyczył najłatwiejszą drogę dojścia do celu na mapie, spisując azymuty, odległości i biorąc pod uwagę warstwice, drogi, przeszkody itp.']::text[]),
  (E'zwiadowcy-terenoznawstwo-pogodynka', E'zwiadowcy', E'fizyczny', E'terenoznawstwo', E'Terenoznawstwo', E'Pogodynka', ARRAY[E'Zna mechanizmy powstawania głównych zjawisk meteorologicznych: niżów, wyżów, wiatrów.', E'Korzystał z przyrządów meteorologicznych: termometru, aneroidu, barografu, deszczomierza.', E'Opisał wygląd i wysokość poszczególnych rodzajów chmur oraz zjawiska towarzyszące ich występowaniu.', E'Przepowiedział pogodę na podstawie obserwacji zjawisk meteorologicznych, wskazań przyrządów, komunikatów i mapek synoptycznych.']::text[]),
  (E'zwiadowcy-terenoznawstwo-zwiadowca', E'zwiadowcy', E'fizyczny', E'terenoznawstwo', E'Terenoznawstwo', E'Zwiadowca', ARRAY[E'Przez lornetkę obserwował z ukrycia zwierzęta w lesie i w terenie otwartym. Potrafi wykonać wabik naśladujący dźwięk zwierzęcia i nawołujący je.', E'Skrycie podszedł na obozie grupę osób i podsłuchał, o czym rozmawiają.', E'Przeprowadził zwiad terenu - opisał dokładnie, co i gdzie zobaczył, posługując się miarami: czasu, odległości i kierunków świata.', E'Nauczył zastęp rozpoznawać tropy i ślady min. 10 różnych zwierząt.']::text[]),
  (E'zwiadowcy-wedrowka-przewodnik', E'zwiadowcy', E'fizyczny', E'wedrowka', E'Wędrówka', E'Przewodnik', ARRAY[E'Poznał historię swojego regionu. Ciekawie przedstawił ją na zbiórce lub ognisku.', E'Zna ciekawe miejsca, muzea, wystawy, pomniki w swojej okolicy.', E'Opracował i przeprowadził wycieczkę zastępu po swojej okolicy, uwzględniając ciekawe miejsca i historie.', E'Nawiązał niezbędne kontakty z gospodarzem terenu lub obiektów i placówek ujętych w opracowaniu propozycji trasy wycieczkowej.']::text[]),
  (E'zwiadowcy-wedrowka-rowerzysta', E'zwiadowcy', E'fizyczny', E'wedrowka', E'Wędrówka', E'Rowerzysta', ARRAY[E'Zdobył Kartę Rowerową.', E'Systematycznie od trzech miesięcy jeździ na rowerze (min. dwa razy na tydzień). Poznał całą okolicę, jeżdżąc na rowerze.', E'Na zbiórce zastępu zrobił przegląd swojego roweru, wyczyścił go i zakonserwował.', E'Brał udział w trzech wycieczkach rowerowych.']::text[]),
  (E'zwiadowcy-wedrowka-tramp', E'zwiadowcy', E'fizyczny', E'wedrowka', E'Wędrówka', E'Tramp', ARRAY[E'Odbył co najmniej pięć samodzielnych wypraw w promieniu kilku kilometrów od miejsca zamieszkania.', E'Poznał zasady bezpiecznego marszu: tempo, odpoczynek, obciążenie, przepisy ruchu drogowego.', E'Zorganizował biwak zastępu, rozbijając go, a następnie likwidując bez pozostawienia śladów. Skompletował na ten biwak ekwipunek i prowiant.', E'Przygotował informacje na temat miejsc godnych odwiedzenia w trakcie wędrówki z zastępem. Przedstawił zebrane informacje zastępowi.']::text[]),
  (E'zwiadowcy-wedrowka-wodniak', E'zwiadowcy', E'fizyczny', E'wedrowka', E'Wędrówka', E'Wodniak', ARRAY[E'Wziął udział w kilkudniowym spływie kajakowym/pontonowym. Wiosłował w kajaku, szalupie lub łodzi na jedno i na dwa wiosła, na pych i na śrubę.', E'Zademonstrował przybijanie do brzegu i manewry: kajakiem, pontonem i rowerem wodnym.', E'Zna różne rodzaje sprzętu wodnego oraz wie, gdzie można nimi bezpiecznie pływać - zrobił prezentację dla zastępu.', E'Z zastępem zbudował i zwodował prostą tratwę. Zna zasady konserwacji i naprawy kajaków, pontonów i łodzi.']::text[])
